diffs.replacement:
{
  "name": "QuickStock QR",
  "description": "A modern stock control system with QR code support, role-based access for stockists and mechanics, and automatic transaction history tracking.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum UserRole {
  STOCKIST = 'STOCKIST',
  MECHANIC = 'MECHANIC'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  entryDate: string;
  description?: string;
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string;
}

import { GoogleGenAI } from "@google/genai";
import { InventoryItem, Transaction } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getStockInsights(items: InventoryItem[], history: Transaction[]) {
  try {
    const prompt = `
      Com base no seguinte inventário e histórico de transações, forneça 3 insights rápidos e úteis em português para o gerenciamento do estoque.
      Foque em itens com baixo estoque, movimentação frequente ou valor total.

      Inventário: ${JSON.stringify(items.map(i => ({ name: i.name, qty: i.quantity, val: i.value })))}
      Histórico Recente: ${JSON.stringify(history.slice(0, 5).map(h => ({ item: h.itemName, type: h.type, qty: h.quantity })))}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "Você é um consultor especialista em logística e gestão de estoque. Seja direto e prático.",
        temperature: 0.7,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Insight Error:", error);
    return "Não foi possível gerar insights no momento.";
  }
}

import React, { useEffect, useRef } from 'react';
import { X } from 'lucide-react';

interface QRScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

declare const Html5QrcodeScanner: any;

const QRScanner: React.FC<QRScannerProps> = ({ onScan, onClose }) => {
  const scannerRef = useRef<any>(null);

  useEffect(() => {
    scannerRef.current = new Html5QrcodeScanner(
      "qr-reader",
      { fps: 10, qrbox: { width: 250, height: 250 } },
      /* verbose= */ false
    );

    scannerRef.current.render((decodedText: string) => {
      onScan(decodedText);
      scannerRef.current.clear();
      onClose();
    }, (error: any) => {
      // Errors are common during scan search, ignore them
    });

    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear().catch((e: any) => console.error(e));
      }
    };
  }, [onScan, onClose]);

  return (
    <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden relative">
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 p-2 bg-slate-100 rounded-full hover:bg-slate-200 z-10"
        >
          <X size={20} />
        </button>
        <div className="p-6">
          <h3 className="text-xl font-bold mb-4">Escanear QR Code</h3>
          <div id="qr-reader" className="w-full"></div>
          <p className="mt-4 text-sm text-slate-500 text-center">
            Aponte a câmera para o QR Code do item para identificá-lo automaticamente.
          </p>
        </div>
      </div>
    </div>
  );
};

export default QRScanner;

import React from 'react';
import { Transaction, TransactionType } from '../types';
import { ArrowUpRight, ArrowDownLeft, Clock, User } from 'lucide-react';

interface TransactionHistoryProps {
  transactions: Transaction[];
}

const TransactionHistory: React.FC<TransactionHistoryProps> = ({ transactions }) => {
  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
        <h3 className="font-bold flex items-center gap-2">
          <Clock size={18} className="text-blue-600" />
          Histórico de Movimentações
        </h3>
      </div>
      <div className="divide-y divide-slate-100 max-h-[400px] overflow-y-auto">
        {transactions.length === 0 ? (
          <div className="p-8 text-center text-slate-400">Nenhuma movimentação registrada.</div>
        ) : (
          transactions.map((t) => (
            <div key={t.id} className="p-4 hover:bg-slate-50 transition-colors">
              <div className="flex justify-between items-start mb-1">
                <span className={`text-xs font-bold px-2 py-0.5 rounded-full flex items-center gap-1 ${
                  t.type === TransactionType.IN 
                  ? 'bg-green-100 text-green-700' 
                  : 'bg-orange-100 text-orange-700'
                }`}>
                  {t.type === TransactionType.IN ? <ArrowDownLeft size={12} /> : <ArrowUpRight size={12} />}
                  {t.type === TransactionType.IN ? 'ENTRADA' : 'SAÍDA'}
                </span>
                <span className="text-xs text-slate-400">
                  {new Date(t.date).toLocaleString('pt-BR')}
                </span>
              </div>
              <div className="flex justify-between items-end">
                <div>
                  <p className="font-semibold text-slate-800">{t.itemName}</p>
                  <p className="text-sm text-slate-500 flex items-center gap-1">
                    <User size={14} /> {t.userName} {t.recipientName ? `→ ${t.recipientName}` : ''}
                  </p>
                </div>
                <div className="text-right">
                  <p className={`font-bold ${t.type === TransactionType.IN ? 'text-green-600' : 'text-orange-600'}`}>
                    {t.type === TransactionType.IN ? '+' : '-'}{t.quantity} un
                  </p>
                </div>
              </div>
            </div>
          )).reverse()
        )}
      </div>
    </div>
  );
};

export default TransactionHistory;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, 
  Package, 
  Search, 
  QrCode, 
  Settings, 
  LogOut, 
  TrendingUp, 
  History, 
  Trash2, 
  Edit3, 
  UserCircle,
  AlertCircle,
  Zap,
  DollarSign,
  ArrowRightLeft
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

const MOCK_USERS: User[] = [
  { id: '1', name: 'Admin Estoquista', role: UserRole.STOCKIST },
  { id: '2', name: 'João Mecânico', role: UserRole.MECHANIC },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    partNumber: '',
    value: 0,
    quantity: 0,
    description: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false,
    itemId: null,
    type: TransactionType.OUT
  });

  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');

  // Persist data
  useEffect(() => {
    const savedItems = localStorage.getItem('qs_items');
    const savedHistory = localStorage.getItem('qs_history');
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_items', JSON.stringify(items));
    localStorage.setItem('qs_history', JSON.stringify(history));
  }, [items, history]);

  const fetchInsights = useCallback(async () => {
    if (items.length > 0) {
      setLoadingInsights(true);
      const text = await getStockInsights(items, history);
      setInsights(text || '');
      setLoadingInsights(false);
    }
  }, [items, history]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      ...formData,
      entryDate: new Date().toISOString()
    };
    setItems(prev => [...prev, newItem]);

    // Log initial entry
    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: newItem.id,
      itemName: newItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: TransactionType.IN,
      quantity: newItem.quantity,
      date: new Date().toISOString(),
      recipientName: 'Estoque Inicial'
    };
    setHistory(prev => [...prev, log]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, description: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId) return;

    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;

    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Quantidade insuficiente em estoque!");
      return;
    }

    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: currentItem.id,
      itemName: currentItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: movementModal.type,
      quantity: movementQty,
      date: new Date().toISOString(),
      recipientName: recipient || (movementModal.type === TransactionType.IN ? 'Fornecedor' : 'Uso Interno')
    };
    setHistory(prev => [...prev, log]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1);
    setRecipient('');
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else {
      alert("Item não encontrado para este QR Code.");
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]">
        <div className="bg-white/10 backdrop-blur-md p-8 rounded-3xl border border-white/20 w-full max-w-md text-white">
          <div className="flex flex-col items-center mb-8">
            <div className="bg-blue-600 p-4 rounded-2xl mb-4 shadow-lg shadow-blue-500/30">
              <Package size={40} />
            </div>
            <h1 className="text-3xl font-black tracking-tighter">QUICKSTOCK</h1>
            <p className="text-slate-400 mt-2">Escolha seu perfil de acesso</p>
          </div>

          <div className="space-y-4">
            {MOCK_USERS.map(user => (
              <button
                key={user.id}
                onClick={() => setCurrentUser(user)}
                className="w-full p-6 bg-white/5 hover:bg-white/10 border border-white/10 rounded-2xl flex items-center gap-4 transition-all group"
              >
                <div className={`p-3 rounded-xl ${user.role === UserRole.STOCKIST ? 'bg-indigo-500/20 text-indigo-400' : 'bg-amber-500/20 text-amber-400'}`}>
                  <UserCircle size={28} />
                </div>
                <div className="text-left flex-1">
                  <p className="font-bold text-lg">{user.name}</p>
                  <p className="text-xs uppercase tracking-widest text-slate-500">{user.role === UserRole.STOCKIST ? 'Estoquista' : 'Mecânico'}</p>
                </div>
                <ArrowRightLeft size={18} className="opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all text-blue-400" />
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {/* Sidebar - Desktop */}
      <aside className="w-full md:w-64 bg-slate-900 text-slate-300 p-6 flex flex-col hidden md:flex">
        <div className="flex items-center gap-3 mb-10">
          <div className="bg-blue-600 p-2 rounded-lg text-white">
            <Package size={24} />
          </div>
          <span className="text-xl font-black tracking-tighter text-white">QUICKSTOCK</span>
        </div>

        <nav className="flex-1 space-y-2">
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl bg-blue-600 text-white font-bold transition-all">
            <TrendingUp size={20} /> Dashboard
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-800 transition-all">
            <Package size={20} /> Inventário
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-800 transition-all">
            <History size={20} /> Histórico
          </button>
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-800">
          <div className="flex items-center gap-3 mb-6 p-2 rounded-lg bg-slate-800/50">
            <div className="w-10 h-10 bg-slate-700 rounded-full flex items-center justify-center text-blue-400 font-bold">
              {currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-bold text-white truncate">{currentUser.name}</p>
              <p className="text-[10px] uppercase tracking-widest text-slate-500">{currentUser.role === UserRole.STOCKIST ? 'Estoquista' : 'Mecânico'}</p>
            </div>
          </div>
          <button 
            onClick={() => setCurrentUser(null)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-500/10 hover:text-red-400 transition-all text-slate-500"
          >
            <LogOut size={20} /> Sair do Perfil
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        {/* Header */}
        <header className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col sm:flex-row items-center justify-between gap-4 shrink-0">
          <div className="flex items-center gap-4 w-full sm:w-auto">
            <h2 className="text-xl font-bold md:hidden">Inventário</h2>
            <div className="relative flex-1 sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Buscar item ou P/N..." 
                className="w-full pl-10 pr-4 py-2 bg-slate-100 rounded-xl border-none focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2 w-full sm:w-auto">
            <button 
              onClick={() => setIsScanning(true)}
              className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-xl hover:bg-slate-700 transition-all"
            >
              <QrCode size={18} /> <span className="hidden sm:inline">Escanear</span>
            </button>
            {currentUser.role === UserRole.STOCKIST && (
              <button 
                onClick={() => setIsAddingItem(true)}
                className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg shadow-blue-500/20 transition-all"
              >
                <Plus size={18} /> Novo Item
              </button>
            )}
          </div>
        </header>

        {/* Scrollable Area */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* Stats Bar */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-blue-50 text-blue-600 rounded-xl">
                <Package size={24} />
              </div>
              <div>
                <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">Itens Totais</p>
                <p className="text-2xl font-black">{items.length}</p>
              </div>
            </div>
            <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-green-50 text-green-600 rounded-xl">
                <DollarSign size={24} />
              </div>
              <div>
                <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">Valor em Estoque</p>
                <p className="text-2xl font-black">R$ {totalStockValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
            </div>
            <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-orange-50 text-orange-600 rounded-xl">
                <Zap size={24} />
              </div>
              <div>
                <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">Itens Críticos</p>
                <p className="text-2xl font-black text-orange-600">{items.filter(i => i.quantity <= 5).length}</p>
              </div>
            </div>
            <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-4 group cursor-pointer" onClick={fetchInsights}>
              <div className={`p-3 rounded-xl ${loadingInsights ? 'bg-indigo-100 animate-pulse' : 'bg-indigo-50 text-indigo-600'}`}>
                <Settings size={24} />
              </div>
              <div>
                <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">AI Stock Insight</p>
                <p className="text-sm font-semibold truncate max-w-[120px]">{loadingInsights ? 'Gerando...' : 'Ver Sugestões'}</p>
              </div>
            </div>
          </div>

          {/* AI Insight Box */}
          {insights && (
            <div className="bg-indigo-600 text-white p-6 rounded-3xl shadow-xl shadow-indigo-500/20 flex flex-col sm:flex-row gap-6 items-start">
              <div className="p-4 bg-white/10 rounded-2xl backdrop-blur-sm shrink-0">
                <Zap size={32} />
              </div>
              <div className="flex-1">
                <h3 className="text-xl font-bold mb-2">IA Stock Insight - Análise Inteligente</h3>
                <div className="text-indigo-100 leading-relaxed space-y-2 whitespace-pre-wrap">
                  {insights}
                </div>
              </div>
              <button 
                onClick={() => setInsights('')}
                className="text-white/50 hover:text-white transition-colors"
              >
                <Trash2 size={20} />
              </button>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Inventory List */}
            <div className="lg:col-span-2 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-lg font-bold">Catálogo de Itens</h3>
                <div className="text-sm text-slate-500">Mostrando {filteredItems.length} resultados</div>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {filteredItems.length === 0 ? (
                  <div className="bg-white border-2 border-dashed border-slate-200 rounded-2xl p-12 text-center flex flex-col items-center gap-4">
                    <Package size={48} className="text-slate-200" />
                    <p className="text-slate-400">Nenhum item encontrado.</p>
                  </div>
                ) : (
                  filteredItems.map(item => (
                    <div key={item.id} className="bg-white border border-slate-200 p-5 rounded-2xl hover:shadow-md transition-all group flex flex-col sm:flex-row gap-4 items-start sm:items-center">
                      <div className="shrink-0 p-3 bg-slate-50 rounded-xl border border-slate-100 text-slate-400">
                        <Package size={32} />
                      </div>
                      <div className="flex-1">
                        <div className="flex flex-wrap items-center gap-2 mb-1">
                          <h4 className="font-bold text-lg text-slate-800">{item.name}</h4>
                          <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-mono uppercase tracking-tighter">P/N: {item.partNumber}</span>
                        </div>
                        <p className="text-sm text-slate-500">{item.description || 'Sem descrição'}</p>
                      </div>
                      <div className="grid grid-cols-2 sm:flex sm:items-center gap-6 sm:gap-8 w-full sm:w-auto">
                        <div className="text-left sm:text-right">
                          <p className="text-[10px] text-slate-400 uppercase font-bold tracking-widest">Estoque</p>
                          <p className={`text-xl font-black ${item.quantity <= 5 ? 'text-orange-500' : 'text-slate-800'}`}>
                            {item.quantity} <span className="text-xs font-normal text-slate-400 uppercase">un</span>
                          </p>
                        </div>
                        <div className="text-left sm:text-right">
                          <p className="text-[10px] text-slate-400 uppercase font-bold tracking-widest">Valor Un.</p>
                          <p className="text-xl font-black text-slate-800">
                            <span className="text-xs font-normal text-slate-400 uppercase">R$</span> {item.value.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2 w-full sm:w-auto sm:opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.IN })}
                          className="flex-1 sm:flex-none p-2 bg-green-50 text-green-600 rounded-lg hover:bg-green-100 transition-colors" title="Dar Entrada">
                          <Plus size={20} />
                        </button>
                        <button 
                          onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT })}
                          className="flex-1 sm:flex-none p-2 bg-orange-50 text-orange-600 rounded-lg hover:bg-orange-100 transition-colors" title="Dar Saída">
                          <LogOut size={20} className="rotate-180" />
                        </button>
                        {currentUser.role === UserRole.STOCKIST && (
                          <button 
                            onClick={() => {
                              if(confirm('Deseja excluir este item do catálogo?')) {
                                setItems(prev => prev.filter(i => i.id !== item.id));
                              }
                            }}
                            className="flex-1 sm:flex-none p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors" title="Remover">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* Right column: History */}
            <div className="space-y-6">
              <TransactionHistory transactions={history} />
            </div>
          </div>
        </div>
      </main>

      {/* Add Item Modal */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-slate-950/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-2xl font-black tracking-tight text-slate-800">Novo Item</h3>
                <p className="text-slate-500">Cadastre um novo produto no estoque</p>
              </div>
              <button onClick={() => setIsAddingItem(false)} className="p-2 bg-white rounded-xl border border-slate-200 hover:bg-slate-50">
                <Trash2 size={20} className="text-slate-400" />
              </button>
            </div>
            <form onSubmit={handleAddItem} className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Nome do Item</label>
                    <input 
                      required
                      type="text" 
                      className="w-full px-4 py-3 bg-slate-100 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 outline-none"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Part Number</label>
                    <input 
                      required
                      type="text" 
                      className="w-full px-4 py-3 bg-slate-100 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 outline-none"
                      value={formData.partNumber}
                      onChange={e => setFormData({...formData, partNumber: e.target.value})}
                    />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Valor Unitário (R$)</label>
                    <input 
                      required
                      type="number" 
                      step="0.01"
                      className="w-full px-4 py-3 bg-slate-100 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 outline-none font-bold text-blue-600"
                      value={formData.value}
                      onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Qtd Inicial</label>
                    <input 
                      required
                      type="number" 
                      className="w-full px-4 py-3 bg-slate-100 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 outline-none font-bold"
                      value={formData.quantity}
                      onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})}
                    />
                  </div>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Descrição</label>
                  <textarea 
                    rows={3}
                    className="w-full px-4 py-3 bg-slate-100 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 outline-none"
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                  />
                </div>
              </div>
              <div className="pt-4 flex gap-3">
                <button 
                  type="button"
                  onClick={() => setIsAddingItem(false)}
                  className="flex-1 py-4 bg-slate-100 text-slate-600 font-bold rounded-2xl hover:bg-slate-200 transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-[2] py-4 bg-blue-600 text-white font-bold rounded-2xl hover:bg-blue-700 shadow-xl shadow-blue-500/20 transition-all"
                >
                  Confirmar Cadastro
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Movement Modal (In/Out) */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-slate-950/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden">
            <div className={`p-8 flex items-center gap-4 ${movementModal.type === TransactionType.IN ? 'bg-green-600' : 'bg-orange-600'} text-white`}>
              <div className="p-3 bg-white/20 rounded-2xl backdrop-blur-md">
                {movementModal.type === TransactionType.IN ? <Plus size={32} /> : <LogOut size={32} className="rotate-180" />}
              </div>
              <div>
                <h3 className="text-2xl font-black">Registrar {movementModal.type === TransactionType.IN ? 'Entrada' : 'Saída'}</h3>
                <p className="text-white/80">{items.find(i => i.id === movementModal.itemId)?.name}</p>
              </div>
            </div>
            <div className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Quantidade</label>
                  <input 
                    type="number" 
                    min="1"
                    className="w-full px-6 py-4 bg-slate-100 border-none rounded-2xl text-2xl font-black focus:ring-2 focus:ring-blue-500/20 outline-none"
                    value={movementQty}
                    onChange={e => setMovementQty(parseInt(e.target.value) || 1)}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Destinatário / Origem</label>
                  <input 
                    type="text" 
                    placeholder={movementModal.type === TransactionType.IN ? "Ex: Fornecedor X" : "Ex: Oficina A / Carro 42"}
                    className="w-full px-4 py-3 bg-slate-100 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 outline-none"
                    value={recipient}
                    onChange={e => setRecipient(e.target.value)}
                  />
                </div>
              </div>
              <div className="flex gap-3">
                <button 
                  onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })}
                  className="flex-1 py-4 bg-slate-100 text-slate-600 font-bold rounded-2xl hover:bg-slate-200 transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  onClick={processMovement}
                  className={`flex-[2] py-4 text-white font-bold rounded-2xl transition-all ${
                    movementModal.type === TransactionType.IN ? 'bg-green-600 hover:bg-green-700' : 'bg-orange-600 hover:bg-orange-700'
                  }`}
                >
                  Efetuar Baixa
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* QR Scanner */}
      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, 
  Package, 
  Search, 
  QrCode, 
  Settings, 
  LogOut, 
  TrendingUp, 
  History, 
  Trash2, 
  UserCircle,
  Zap,
  DollarSign,
  ArrowRightLeft,
  ShieldCheck,
  Wrench
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

const MOCK_USERS: User[] = [
  { id: '1', name: 'Estoquista Principal', role: UserRole.STOCKIST },
  { id: '2', name: 'Mecânico', role: UserRole.MECHANIC },
];

// Logo Component for consistency
const HPSLogo: React.FC<{ size?: number; className?: string }> = ({ size = 32, className = "" }) => (
  <div className={`flex items-center gap-2 ${className}`}>
    <div className="bg-emerald-500 p-1.5 rounded-lg flex items-center justify-center text-black">
      <ShieldCheck size={size} strokeWidth={2.5} />
    </div>
    <span className="font-black tracking-tighter" style={{ fontSize: size * 0.8 + 'px' }}>HPS CONTROL</span>
  </div>
);

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    partNumber: '',
    value: 0,
    quantity: 0,
    description: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false,
    itemId: null,
    type: TransactionType.OUT
  });

  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');

  // Persist data
  useEffect(() => {
    const savedItems = localStorage.getItem('hps_items');
    const savedHistory = localStorage.getItem('hps_history');
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_items', JSON.stringify(items));
    localStorage.setItem('hps_history', JSON.stringify(history));
  }, [items, history]);

  const fetchInsights = useCallback(async () => {
    if (items.length > 0) {
      setLoadingInsights(true);
      const text = await getStockInsights(items, history);
      setInsights(text || '');
      setLoadingInsights(false);
    }
  }, [items, history]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      ...formData,
      entryDate: new Date().toISOString()
    };
    setItems(prev => [...prev, newItem]);

    // Log initial entry
    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: newItem.id,
      itemName: newItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: TransactionType.IN,
      quantity: newItem.quantity,
      date: new Date().toISOString(),
      recipientName: 'Estoque Inicial'
    };
    setHistory(prev => [...prev, log]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, description: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId) return;

    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;

    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Quantidade insuficiente em estoque!");
      return;
    }

    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: currentItem.id,
      itemName: currentItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: movementModal.type,
      quantity: movementQty,
      date: new Date().toISOString(),
      recipientName: recipient || (movementModal.type === TransactionType.IN ? 'Fornecedor' : 'Uso Interno')
    };
    setHistory(prev => [...prev, log]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1);
    setRecipient('');
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else {
      alert("Item não encontrado para este QR Code.");
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
        <div className="bg-slate-900/40 backdrop-blur-xl p-10 rounded-[2.5rem] border border-emerald-500/20 w-full max-w-md text-white shadow-2xl">
          <div className="flex flex-col items-center mb-10">
            <div className="bg-emerald-500 p-5 rounded-3xl mb-4 shadow-lg shadow-emerald-500/30 transform -rotate-3">
              <ShieldCheck size={48} className="text-black" />
            </div>
            <h1 className="text-4xl font-black tracking-tighter">HPS CONTROL</h1>
            <p className="text-slate-400 mt-2 font-medium">Acesso Restrito ao Sistema</p>
          </div>

          <div className="space-y-4">
            {MOCK_USERS.map(user => (
              <button
                key={user.id}
                onClick={() => setCurrentUser(user)}
                className="w-full p-6 bg-slate-800/50 hover:bg-emerald-500/10 border border-slate-700 hover:border-emerald-500/40 rounded-3xl flex items-center gap-4 transition-all group text-left"
              >
                <div className={`p-3 rounded-2xl ${user.role === UserRole.STOCKIST ? 'bg-emerald-500 text-black shadow-lg shadow-emerald-500/20' : 'bg-slate-700 text-emerald-500'}`}>
                  {user.role === UserRole.STOCKIST ? <UserCircle size={28} /> : <Wrench size={28} />}
                </div>
                <div className="flex-1">
                  <p className="font-bold text-lg group-hover:text-emerald-400 transition-colors">{user.name}</p>
                  <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold">{user.role === UserRole.STOCKIST ? 'Setor: Estoque' : 'Setor: Manutenção'}</p>
                </div>
                <ArrowRightLeft size={18} className="opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all text-emerald-400" />
              </button>
            ))}
          </div>
          <p className="text-center text-slate-600 text-xs mt-8 font-medium">© 2024 HPS Control Systems</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {/* Sidebar - Desktop */}
      <aside className="w-full md:w-64 bg-black text-slate-300 p-6 flex flex-col hidden md:flex border-r border-emerald-500/10 shadow-2xl z-10">
        <div className="mb-10 px-2">
          <HPSLogo size={28} className="text-white" />
        </div>

        <nav className="flex-1 space-y-2">
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl bg-emerald-600 text-black font-black transition-all shadow-lg shadow-emerald-600/20">
            <TrendingUp size={20} /> Dashboard
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-900 hover:text-emerald-400 transition-all font-semibold">
            <Package size={20} /> Inventário
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-900 hover:text-emerald-400 transition-all font-semibold">
            <History size={20} /> Histórico
          </button>
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-800">
          <div className="flex items-center gap-3 mb-6 p-3 rounded-2xl bg-slate-900/50 border border-slate-800">
            <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-black font-black shadow-md">
              {currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-bold text-white truncate">{currentUser.name}</p>
              <p className="text-[10px] uppercase tracking-widest text-emerald-500 font-black">{currentUser.role === UserRole.STOCKIST ? 'Estoquista' : 'Mecânico'}</p>
            </div>
          </div>
          <button 
            onClick={() => setCurrentUser(null)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-500/10 hover:text-red-400 transition-all text-slate-500 font-medium"
          >
            <LogOut size={20} /> Sair do Perfil
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        {/* Header */}
        <header className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col sm:flex-row items-center justify-between gap-4 shrink-0 shadow-sm z-10">
          <div className="flex items-center gap-4 w-full sm:w-auto">
            <div className="md:hidden">
              <HPSLogo size={24} className="text-black" />
            </div>
            <div className="relative flex-1 sm:w-80">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Pesquisar itens, P/N ou categoria..." 
                className="w-full pl-12 pr-4 py-2.5 bg-slate-100 rounded-2xl border-none focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all font-medium"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2 w-full sm:w-auto">
            <button 
              onClick={() => setIsScanning(true)}
              className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-black text-white rounded-2xl hover:bg-slate-800 transition-all font-bold"
            >
              <QrCode size={18} className="text-emerald-400" /> <span className="hidden sm:inline">Scanner QR</span>
            </button>
            {currentUser.role === UserRole.STOCKIST && (
              <button 
                onClick={() => setIsAddingItem(true)}
                className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-emerald-500 text-black rounded-2xl hover:bg-emerald-400 shadow-lg shadow-emerald-500/20 transition-all font-black"
              >
                <Plus size={18} /> Novo Item
              </button>
            )}
          </div>
        </header>

        {/* Scrollable Area */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* Stats Bar */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-slate-100 text-black rounded-2xl">
                <Package size={24} />
              </div>
              <div>
                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Itens Totais</p>
                <p className="text-2xl font-black">{items.length}</p>
              </div>
            </div>
            <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl">
                <DollarSign size={24} />
              </div>
              <div>
                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Valor Estoque</p>
                <p className="text-2xl font-black">R$ {totalStockValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
            </div>
            <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-red-50 text-red-600 rounded-2xl">
                <Zap size={24} />
              </div>
              <div>
                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Baixo Estoque</p>
                <p className="text-2xl font-black text-red-600">{items.filter(i => i.quantity <= 5).length}</p>
              </div>
            </div>
            <div className="bg-black text-white p-5 rounded-[2rem] shadow-xl shadow-black/10 flex items-center gap-4 group cursor-pointer overflow-hidden relative" onClick={fetchInsights}>
              <div className="absolute top-0 right-0 p-1 opacity-10 group-hover:scale-125 transition-transform">
                <ShieldCheck size={80} />
              </div>
              <div className={`p-3 rounded-2xl relative z-10 ${loadingInsights ? 'bg-emerald-500 animate-pulse' : 'bg-emerald-500 text-black'}`}>
                <Settings size={24} />
              </div>
              <div className="relative z-10">
                <p className="text-[10px] text-emerald-500 uppercase font-black tracking-widest">AI Analyst</p>
                <p className="text-sm font-bold truncate max-w-[120px]">{loadingInsights ? 'Processando...' : 'Ver Insights'}</p>
              </div>
            </div>
          </div>

          {/* AI Insight Box */}
          {insights && (
            <div className="bg-emerald-600 text-black p-8 rounded-[2.5rem] shadow-xl shadow-emerald-500/20 flex flex-col sm:flex-row gap-6 items-start relative overflow-hidden">
              <div className="absolute top-0 right-0 p-2 opacity-5">
                <ShieldCheck size={160} />
              </div>
              <div className="p-4 bg-black text-emerald-400 rounded-3xl shrink-0 shadow-lg relative z-10">
                <Zap size={36} />
              </div>
              <div className="flex-1 relative z-10">
                <h3 className="text-2xl font-black mb-3">HPS Insight AI</h3>
                <div className="text-black/80 font-medium leading-relaxed space-y-2 whitespace-pre-wrap">
                  {insights}
                </div>
              </div>
              <button 
                onClick={() => setInsights('')}
                className="p-2 hover:bg-black/10 rounded-full transition-colors relative z-10"
              >
                <Trash2 size={24} />
              </button>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Inventory List */}
            <div className="lg:col-span-2 space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-xl font-black text-slate-800">Catálogo de Ativos</h3>
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest">{filteredItems.length} itens listados</div>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {filteredItems.length === 0 ? (
                  <div className="bg-white border-4 border-dashed border-slate-200 rounded-[3rem] p-16 text-center flex flex-col items-center gap-4">
                    <Package size={64} className="text-slate-100" />
                    <p className="text-slate-400 font-bold">Nenhum ativo localizado no banco de dados.</p>
                  </div>
                ) : (
                  filteredItems.map(item => (
                    <div key={item.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] hover:shadow-xl hover:border-emerald-500/30 transition-all group flex flex-col sm:flex-row gap-6 items-start sm:items-center">
                      <div className="shrink-0 p-4 bg-slate-50 rounded-3xl border border-slate-100 text-slate-300 group-hover:text-emerald-500 transition-colors">
                        <Package size={36} />
                      </div>
                      <div className="flex-1">
                        <div className="flex flex-wrap items-center gap-3 mb-1.5">
                          <h4 className="font-black text-xl text-slate-800 group-hover:text-black transition-colors">{item.name}</h4>
