import React, { useEffect, useRef } from 'react';
import { X, ShieldCheck } from 'lucide-react';

interface QRScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

declare const Html5QrcodeScanner: any;

const QRScanner: React.FC<QRScannerProps> = ({ onScan, onClose }) => {
  const scannerRef = useRef<any>(null);

  useEffect(() => {
    scannerRef.current = new Html5QrcodeScanner(
      "qr-reader",
      { 
        fps: 20, 
        qrbox: { width: 250, height: 250 },
        aspectRatio: 1.0
      },
      /* verbose= */ false
    );

    scannerRef.current.render((decodedText: string) => {
      onScan(decodedText);
      scannerRef.current.clear();
      onClose();
    }, (error: any) => {
      // Errors are expected during search
    });

    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear().catch((e: any) => console.error(e));
      }
    };
  }, [onScan, onClose]);

  return (
    <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
      <div className="bg-white rounded-[3rem] w-full max-w-lg overflow-hidden relative shadow-2xl border border-emerald-500/20">
        <button 
          onClick={onClose}
          className="absolute top-6 right-6 p-3 bg-slate-100 rounded-2xl hover:bg-slate-200 transition-all z-10 text-slate-500"
        >
          <X size={24} />
        </button>
        <div className="p-10">
          <div className="flex items-center gap-3 mb-8">
            <div className="bg-emerald-500 p-2 rounded-xl text-black shadow-lg shadow-emerald-500/20">
              <ShieldCheck size={24} strokeWidth={2.5} />
            </div>
            <h3 className="text-2xl font-black tracking-tight">Scanner HPS</h3>
          </div>

          <div className="rounded-[2rem] overflow-hidden border-4 border-emerald-500/20 shadow-inner">
            <div id="qr-reader" className="w-full"></div>
          </div>

          <div className="mt-8 text-center space-y-2">
            <p className="font-black text-slate-800">Aguardando QR Code...</p>
            <p className="text-sm text-slate-400 font-medium px-8">
              Posicione o código do item dentro da moldura para identificação instantânea.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QRScanner;

