                      onChange={e => setFormData({...formData, partNumber: e.target.value})}
                    />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Valor Un. (R$)</label>
                    <input 
                      required
                      type="number" 
                      step="0.01"
                      className="w-full px-5 py-4 bg-green-50/50 border-2 border-green-500/20 text-green-700 rounded-[1.5rem] outline-none font-black text-xl"
                      value={formData.value}
                      onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Qtd</label>
                    <input 
                      required
                      type="number" 
                      className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 rounded-[1.5rem] outline-none font-black text-xl"
                      value={formData.quantity}
                      onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Notas Técnicas</label>
                  <textarea 
                    rows={3}
                    className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 rounded-[1.5rem] outline-none transition-all font-medium"
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                  />
                </div>
              </div>
              <div className="pt-2 flex gap-4">
                <button 
                  type="button"
                  onClick={() => setIsAddingItem(false)}
                  className="flex-1 py-5 bg-slate-100 text-slate-500 font-bold rounded-[1.5rem] hover:bg-slate-200 transition-colors uppercase text-[10px]"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-[2] py-5 bg-green-500 text-black font-black rounded-[1.5rem] hover:bg-green-400 shadow-2xl shadow-green-500/30 transition-all text-xs uppercase"
                >
                  Confirmar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Movement Modal (In/Out) */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className={`p-10 flex items-center gap-5 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-black text-white'}`}>
              <div className={`p-4 rounded-3xl backdrop-blur-md ${movementModal.type === TransactionType.IN ? 'bg-black/10' : 'bg-green-500/20'}`}>
                {movementModal.type === TransactionType.IN ? <Plus size={40} strokeWidth={3} /> : <LogOut size={40} className="rotate-180" strokeWidth={3} />}
              </div>
              <div>
                <h3 className="text-3xl font-black uppercase italic tracking-tighter">Registrar {movementModal.type === TransactionType.IN ? 'Entrada' : 'Saída'}</h3>
                <p className={`font-black uppercase tracking-widest text-[10px] ${movementModal.type === TransactionType.IN ? 'text-black/60' : 'text-green-500'}`}>
                  {items.find(i => i.id === movementModal.itemId)?.name}
                </p>
              </div>
            </div>
            <div className="p-10 space-y-8">
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Quantidade</label>
                  <input 
                    type="number" 
                    min="1"
                    className="w-full px-8 py-6 bg-slate-100 border-none rounded-[2rem] text-4xl font-black focus:ring-4 focus:ring-green-500/10 outline-none text-center"
                    value={movementQty}
                    onChange={e => setMovementQty(parseInt(e.target.value) || 1)}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Destinatário / OS</label>
                  <input 
                    type="text" 
                    className="w-full px-6 py-4 bg-slate-100 border-none rounded-[1.5rem] focus:ring-2 focus:ring-green-500/20 outline-none font-bold"
                    value={recipient}
                    onChange={e => setRecipient(e.target.value)}
                  />
                </div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })}
                  className="flex-1 py-5 bg-slate-100 text-slate-500 font-bold rounded-[1.5rem] hover:bg-slate-200 transition-colors uppercase text-[10px]"
                >
                  Voltar
                </button>
                <button 
                  onClick={processMovement}
                  className={`flex-[2] py-5 font-black rounded-[1.5rem] transition-all text-xs shadow-xl uppercase ${
                    movementModal.type === TransactionType.IN 
                    ? 'bg-green-500 text-black hover:bg-green-400 shadow-green-500/20' 
                    : 'bg-black text-white hover:bg-slate-900 shadow-black/20'
                  }`}
                >
                  Confirmar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* QR Scanner */}
      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, 
  Package, 
  Search, 
  QrCode, 
  Settings, 
  LogOut, 
  TrendingUp, 
  History, 
  Trash2, 
  UserCircle,
  Zap,
  DollarSign,
  ArrowRightLeft,
  Wrench
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

const MOCK_USERS: User[] = [
  { id: '1', name: 'Estoquista Principal', role: UserRole.STOCKIST },
  { id: '2', name: 'Mecânico', role: UserRole.MECHANIC },
];

/**
 * Componente de Logo HPS
 * Nota: Certifique-se de que o arquivo 'logo.png' esteja na raiz do projeto.
 */
const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg', className?: string }> = ({ size = 'md', className = "" }) => {
  const dimensions = {
    sm: { width: '100px' },
    md: { width: '140px' },
    lg: { width: '220px' }
  };

  return (
    <div className={`flex flex-col items-center ${className} select-none`}>
      <img 
        src="logo.png" 
        alt="HPS CONTROL" 
        style={dimensions[size]}
        className="drop-shadow-[0_0_15px_rgba(0,255,0,0.2)] object-contain"
        onError={(e) => {
          // Fallback caso a imagem não seja encontrada
          e.currentTarget.style.display = 'none';
        }}
      />
    </div>
  );
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    partNumber: '',
    value: 0,
    quantity: 0,
    description: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false,
    itemId: null,
    type: TransactionType.OUT
  });

  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');

  useEffect(() => {
    const savedItems = localStorage.getItem('hps_items');
    const savedHistory = localStorage.getItem('hps_history');
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_items', JSON.stringify(items));
    localStorage.setItem('hps_history', JSON.stringify(history));
  }, [items, history]);

  const fetchInsights = useCallback(async () => {
    if (items.length > 0) {
      setLoadingInsights(true);
      const text = await getStockInsights(items, history);
      setInsights(text || '');
      setLoadingInsights(false);
    }
  }, [items, history]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      ...formData,
      entryDate: new Date().toISOString()
    };
    setItems(prev => [...prev, newItem]);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: newItem.id,
      itemName: newItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: TransactionType.IN,
      quantity: newItem.quantity,
      date: new Date().toISOString(),
      recipientName: 'Estoque Inicial'
    };
    setHistory(prev => [...prev, log]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, description: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId) return;

    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;

    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Quantidade insuficiente em estoque!");
      return;
    }

    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: currentItem.id,
      itemName: currentItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: movementModal.type,
      quantity: movementQty,
      date: new Date().toISOString(),
      recipientName: recipient || (movementModal.type === TransactionType.IN ? 'Fornecedor' : 'Uso Interno')
    };
    setHistory(prev => [...prev, log]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1);
    setRecipient('');
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else {
      alert("Item não encontrado para este QR Code.");
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
        <div className="bg-slate-900/40 backdrop-blur-xl p-10 rounded-[2.5rem] border border-green-500/20 w-full max-w-md text-white shadow-2xl">
          <div className="flex flex-col items-center mb-10">
            <HPSLogo size="lg" className="mb-4" />
            <h1 className="text-xl font-black tracking-widest text-white border-t border-white/10 pt-6 w-full text-center">LOGIN HPS CONTROL</h1>
          </div>

          <div className="space-y-4">
            {MOCK_USERS.map(user => (
              <button
                key={user.id}
                onClick={() => setCurrentUser(user)}
                className="w-full p-6 bg-slate-800/50 hover:bg-green-500/10 border border-slate-700 hover:border-green-500/40 rounded-3xl flex items-center gap-4 transition-all group text-left"
              >
                <div className={`p-3 rounded-2xl ${user.role === UserRole.STOCKIST ? 'bg-green-500 text-black shadow-lg shadow-green-500/20' : 'bg-slate-700 text-green-500'}`}>
                  {user.role === UserRole.STOCKIST ? <UserCircle size={28} /> : <Wrench size={28} />}
                </div>
                <div className="flex-1">
                  <p className="font-bold text-lg group-hover:text-green-400 transition-colors">{user.name}</p>
                  <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold">{user.role === UserRole.STOCKIST ? 'Acesso: Estoquista' : 'Acesso: Mecânico'}</p>
                </div>
                <ArrowRightLeft size={18} className="opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all text-green-400" />
              </button>
            ))}
          </div>
          <p className="text-center text-slate-600 text-[10px] mt-8 font-medium italic tracking-widest uppercase">HPS Control Systems • 2024</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      <aside className="w-full md:w-64 bg-black text-slate-300 p-6 flex flex-col hidden md:flex border-r border-green-500/10 shadow-2xl z-10">
        <div className="mb-12 flex justify-center md:justify-start">
          <HPSLogo size="sm" className="items-start" />
        </div>

        <nav className="flex-1 space-y-2">
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl bg-green-600 text-black font-black transition-all shadow-lg shadow-green-600/20">
            <TrendingUp size={20} /> Dashboard
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-900 hover:text-green-400 transition-all font-semibold">
            <Package size={20} /> Inventário
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl hover:bg-slate-900 hover:text-green-400 transition-all font-semibold">
            <History size={20} /> Histórico
          </button>
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-800">
          <div className="flex items-center gap-3 mb-6 p-3 rounded-2xl bg-slate-900/50 border border-slate-800">
            <div className="w-10 h-10 bg-green-500 rounded-xl flex items-center justify-center text-black font-black shadow-md uppercase">
              {currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-bold text-white truncate">{currentUser.name}</p>
              <p className="text-[10px] uppercase tracking-widest text-green-500 font-black">{currentUser.role === UserRole.STOCKIST ? 'Estoquista' : 'Mecânico'}</p>
            </div>
          </div>
          <button 
            onClick={() => setCurrentUser(null)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-500/10 hover:text-red-400 transition-all text-slate-500 font-medium"
          >
            <LogOut size={20} /> Sair
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col sm:flex-row items-center justify-between gap-4 shrink-0 shadow-sm z-10">
          <div className="flex items-center gap-4 w-full sm:w-auto">
            <div className="md:hidden">
              <HPSLogo size="sm" />
            </div>
            <div className="relative flex-1 sm:w-80">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Pesquisar ativos ou P/N..." 
                className="w-full pl-12 pr-4 py-2.5 bg-slate-100 rounded-2xl border-none focus:ring-2 focus:ring-green-500/20 outline-none transition-all font-medium"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2 w-full sm:w-auto">
            <button 
              onClick={() => setIsScanning(true)}
              className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-black text-white rounded-2xl hover:bg-slate-800 transition-all font-bold"
            >
              <QrCode size={18} className="text-green-400" /> <span className="hidden sm:inline text-[10px] uppercase tracking-tighter">Scanner</span>
            </button>
            {currentUser.role === UserRole.STOCKIST && (
              <button 
                onClick={() => setIsAddingItem(true)}
                className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-green-500 text-black rounded-2xl hover:bg-green-400 shadow-lg shadow-green-500/20 transition-all font-black text-[10px] uppercase"
              >
                <Plus size={18} /> Novo Ativo
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-slate-100 text-black rounded-2xl">
                <Package size={24} />
              </div>
              <div>
                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Itens Totais</p>
                <p className="text-2xl font-black">{items.length}</p>
              </div>
            </div>
            <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-green-50 text-green-600 rounded-2xl">
                <DollarSign size={24} />
              </div>
              <div>
                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Valor em Estoque</p>
                <p className="text-2xl font-black">R$ {totalStockValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
            </div>
            <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
              <div className="p-3 bg-red-50 text-red-600 rounded-2xl">
                <Zap size={24} />
              </div>
              <div>
                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Estoque Crítico</p>
                <p className="text-2xl font-black text-red-600">{items.filter(i => i.quantity <= 5).length}</p>
              </div>
            </div>
            <div className="bg-black text-white p-5 rounded-[2rem] shadow-xl shadow-black/10 flex items-center gap-4 group cursor-pointer overflow-hidden relative" onClick={fetchInsights}>
              <div className="absolute top-0 right-0 p-1 opacity-10 group-hover:scale-125 transition-transform">
                 <Package size={80} />
              </div>
              <div className={`p-3 rounded-2xl relative z-10 ${loadingInsights ? 'bg-green-500 animate-pulse' : 'bg-green-500 text-black'}`}>
                <Settings size={24} />
              </div>
              <div className="relative z-10">
                <p className="text-[10px] text-green-500 uppercase font-black tracking-widest">IA Insight</p>
                <p className="text-sm font-bold truncate max-w-[120px]">{loadingInsights ? '...' : 'Análise IA'}</p>
              </div>
            </div>
          </div>

          {insights && (
            <div className="bg-green-600 text-black p-8 rounded-[2.5rem] shadow-xl shadow-green-500/20 flex flex-col sm:flex-row gap-6 items-start relative overflow-hidden">
              <div className="p-4 bg-black text-green-400 rounded-3xl shrink-0 shadow-lg relative z-10">
                <Zap size={36} />
              </div>
              <div className="flex-1 relative z-10">
                <h3 className="text-2xl font-black mb-3 italic tracking-tighter">HPS ESTRATÉGICO</h3>
                <div className="text-black/80 font-medium leading-relaxed space-y-2 whitespace-pre-wrap">
                  {insights}
                </div>
              </div>
              <button 
                onClick={() => setInsights('')}
                className="p-2 hover:bg-black/10 rounded-full transition-colors relative z-10"
              >
                <Trash2 size={24} />
              </button>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter italic">Gerenciamento HPS</h3>
                <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{filteredItems.length} componentes</div>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {filteredItems.length === 0 ? (
                  <div className="bg-white border-4 border-dashed border-slate-200 rounded-[3rem] p-16 text-center flex flex-col items-center gap-4">
                    <Package size={64} className="text-slate-100" />
                    <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Estoque Vazio</p>
                  </div>
                ) : (
                  filteredItems.map(item => (
                    <div key={item.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] hover:shadow-xl hover:border-green-500/30 transition-all group flex flex-col sm:flex-row gap-6 items-start sm:items-center">
                      <div className="shrink-0 p-4 bg-slate-50 rounded-3xl border border-slate-100 text-slate-300 group-hover:text-green-500 transition-colors">
                        <Package size={36} />
                      </div>
                      <div className="flex-1">
                        <div className="flex flex-wrap items-center gap-3 mb-1.5">
                          <h4 className="font-black text-xl text-slate-800 group-hover:text-black transition-colors uppercase tracking-tight">{item.name}</h4>
                          <span className="text-[10px] bg-black text-green-400 px-2.5 py-1 rounded-lg font-black uppercase tracking-tighter shadow-sm">P/N: {item.partNumber}</span>
                        </div>
                        <p className="text-sm text-slate-500 font-medium italic">{item.description || 'Sem descrição'}</p>
                      </div>
                      <div className="grid grid-cols-2 sm:flex sm:items-center gap-8 sm:gap-12 w-full sm:w-auto">
                        <div className="text-left sm:text-right">
                          <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Quantidade</p>
                          <p className={`text-2xl font-black ${item.quantity <= 5 ? 'text-red-500' : 'text-slate-800'}`}>
                            {item.quantity} <span className="text-xs font-bold text-slate-300 uppercase">UN</span>
                          </p>
                        </div>
                        <div className="text-left sm:text-right">
                          <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Valor Unit.</p>
                          <p className="text-2xl font-black text-slate-800">
                            <span className="text-xs font-bold text-slate-300 uppercase">R$</span> {item.value.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2 w-full sm:w-auto md:opacity-0 group-hover:opacity-100 transition-all">
                        <button 
                          onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.IN })}
                          className="flex-1 sm:flex-none p-3 bg-green-500 text-black rounded-2xl hover:bg-green-400 transition-colors shadow-lg shadow-green-500/10" title="Entrada">
                          <Plus size={20} strokeWidth={3} />
                        </button>
                        <button 
                          onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT })}
                          className="flex-1 sm:flex-none p-3 bg-black text-emerald-400 rounded-2xl hover:bg-slate-900 transition-colors shadow-lg shadow-black/10" title="Saída">
                          <LogOut size={20} className="rotate-180" strokeWidth={3} />
                        </button>
                        {currentUser.role === UserRole.STOCKIST && (
                          <button 
                            onClick={() => {
                              if(confirm('Excluir este ativo definitivamente?')) {
                                setItems(prev => prev.filter(i => i.id !== item.id));
                              }
                            }}
                            className="flex-1 sm:flex-none p-3 bg-red-50 text-red-600 rounded-2xl hover:bg-red-100 transition-colors" title="Remover">
                            <Trash2 size={20} />
                          </button>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            <div className="space-y-6">
              <TransactionHistory transactions={history} />
            </div>
          </div>
        </div>
      </main>

      {isAddingItem && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/80">
              <div>
                <h3 className="text-3xl font-black tracking-tight text-slate-800 uppercase italic">Novo Cadastro</h3>
                <p className="text-slate-500 font-medium">Registro de componente HPS</p>
              </div>
              <button onClick={() => setIsAddingItem(false)} className="p-3 bg-white rounded-2xl border border-slate-200 hover:bg-slate-50 text-slate-400 hover:text-slate-800 transition-all">
                <Trash2 size={24} />
              </button>
            </div>
            <form onSubmit={handleAddItem} className="p-10 space-y-8">
              <div className="space-y-5">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Nome do Ativo</label>
                    <input 
                      required
                      type="text" 
                      className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 focus:bg-white rounded-[1.5rem] outline-none transition-all font-bold"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Part Number</label>
                    <input 
                      required
                      type="text" 
                      className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 focus:bg-white rounded-[1.5rem] outline-none transition-all font-bold"
                      value={formData.partNumber}
                      onChange={e => setFormData({...formData, partNumber: e.target.value})}
                    />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Valor Un. (R$)</label>
                    <input 
                      required
                      type="number" 
                      step="0.01"
                      className="w-full px-5 py-4 bg-green-50/50 border-2 border-green-500/20 text-green-700 rounded-[1.5rem] outline-none font-black text-xl"
                      value={formData.value}
                      onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Quantidade</label>
                    <input 
                      required
                      type="number" 
                      className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 rounded-[1.5rem] outline-none font-black text-xl"
                      value={formData.quantity}
                      onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Observações Técnicas</label>
                  <textarea 
                    rows={3}
                    className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 rounded-[1.5rem] outline-none transition-all font-medium"
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                  />
                </div>
              </div>
              <div className="pt-2 flex gap-4">
                <button 
                  type="button"
                  onClick={() => setIsAddingItem(false)}
                  className="flex-1 py-5 bg-slate-100 text-slate-500 font-bold rounded-[1.5rem] hover:bg-slate-200 transition-colors uppercase text-[10px]"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-[2] py-5 bg-green-500 text-black font-black rounded-[1.5rem] hover:bg-green-400 shadow-2xl shadow-green-500/30 transition-all text-xs uppercase"
                >
                  Salvar Ativo
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className={`p-10 flex items-center gap-5 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-black text-white'}`}>
              <div className={`p-4 rounded-3xl backdrop-blur-md ${movementModal.type === TransactionType.IN ? 'bg-black/10' : 'bg-green-500/20'}`}>
                {movementModal.type === TransactionType.IN ? <Plus size={40} strokeWidth={3} /> : <LogOut size={40} className="rotate-180" strokeWidth={3} />}
              </div>
              <div>
                <h3 className="text-3xl font-black uppercase italic tracking-tighter">Registrar {movementModal.type === TransactionType.IN ? 'Entrada' : 'Saída'}</h3>
                <p className={`font-black uppercase tracking-widest text-[10px] ${movementModal.type === TransactionType.IN ? 'text-black/60' : 'text-green-500'}`}>
                  {items.find(i => i.id === movementModal.itemId)?.name}
                </p>
              </div>
            </div>
            <div className="p-10 space-y-8">
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Volume</label>
                  <input 
                    type="number" 
                    min="1"
                    className="w-full px-8 py-6 bg-slate-100 border-none rounded-[2rem] text-4xl font-black focus:ring-4 focus:ring-green-500/10 outline-none text-center"
                    value={movementQty}
                    onChange={e => setMovementQty(parseInt(e.target.value) || 1)}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Destinatário ou OS</label>
                  <input 
                    type="text" 
                    className="w-full px-6 py-4 bg-slate-100 border-none rounded-[1.5rem] focus:ring-2 focus:ring-green-500/20 outline-none font-bold"
                    value={recipient}
                    onChange={e => setRecipient(e.target.value)}
                  />
                </div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })}
                  className="flex-1 py-5 bg-slate-100 text-slate-500 font-bold rounded-[1.5rem] hover:bg-slate-200 transition-colors uppercase text-[10px]"
                >
                  Voltar
                </button>
                <button 
                  onClick={processMovement}
                  className={`flex-[2] py-5 font-black rounded-[1.5rem] transition-all text-xs shadow-xl uppercase ${
                    movementModal.type === TransactionType.IN 
                    ? 'bg-green-500 text-black hover:bg-green-400 shadow-green-500/20' 
                    : 'bg-black text-white hover:bg-slate-900 shadow-black/20'
                  }`}
                >
                  Confirmar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, 
  Package, 
  Search, 
  QrCode, 
  Settings, 
  LogOut, 
  TrendingUp, 
  History, 
  Trash2, 
  UserCircle,
  Zap,
  DollarSign,
  ArrowRightLeft,
  Wrench,
  FileText,
  Printer,
  ChevronRight
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

const MOCK_USERS: User[] = [
  { id: '1', name: 'Estoquista Principal', role: UserRole.STOCKIST },
  { id: '2', name: 'Mecânico', role: UserRole.MECHANIC },
];

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'reports';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg', className?: string }> = ({ size = 'md', className = "" }) => {
  const dimensions = {
    sm: { width: '100px' },
    md: { width: '140px' },
    lg: { width: '220px' }
  };

  return (
    <div className={`flex flex-col items-center ${className} select-none`}>
      <img 
        src="logo.png" 
        alt="HPS CONTROL" 
        style={dimensions[size]}
        className="drop-shadow-[0_0_15px_rgba(0,255,0,0.2)] object-contain"
        onError={(e) => {
          e.currentTarget.style.display = 'none';
        }}
      />
    </div>
  );
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    partNumber: '',
    value: 0,
    quantity: 0,
    description: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false,
    itemId: null,
    type: TransactionType.OUT
  });

  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');

  useEffect(() => {
    const savedItems = localStorage.getItem('hps_items');
    const savedHistory = localStorage.getItem('hps_history');
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_items', JSON.stringify(items));
    localStorage.setItem('hps_history', JSON.stringify(history));
  }, [items, history]);

  const fetchInsights = useCallback(async () => {
    if (items.length > 0) {
      setLoadingInsights(true);
      const text = await getStockInsights(items, history);
      setInsights(text || '');
      setLoadingInsights(false);
    }
  }, [items, history]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      ...formData,
      entryDate: new Date().toISOString()
    };
    setItems(prev => [...prev, newItem]);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: newItem.id,
      itemName: newItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: TransactionType.IN,
      quantity: newItem.quantity,
      date: new Date().toISOString(),
      recipientName: 'Estoque Inicial'
    };
    setHistory(prev => [...prev, log]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, description: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId) return;

    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;

    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Quantidade insuficiente em estoque!");
      return;
    }

    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: currentItem.id,
      itemName: currentItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: movementModal.type,
      quantity: movementQty,
      date: new Date().toISOString(),
      recipientName: recipient || (movementModal.type === TransactionType.IN ? 'Fornecedor' : 'Uso Interno')
    };
    setHistory(prev => [...prev, log]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1);
    setRecipient('');
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else {
      alert("Item não encontrado para este QR Code.");
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);
  const totalUnits = items.reduce((acc, curr) => acc + curr.quantity, 0);

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
        <div className="bg-slate-900/40 backdrop-blur-xl p-10 rounded-[2.5rem] border border-green-500/20 w-full max-w-md text-white shadow-2xl">
          <div className="flex flex-col items-center mb-10">
            <HPSLogo size="lg" className="mb-4" />
            <h1 className="text-xl font-black tracking-widest text-white border-t border-white/10 pt-6 w-full text-center uppercase italic">Acesso HPS Control</h1>
          </div>

          <div className="space-y-4">
            {MOCK_USERS.map(user => (
              <button
                key={user.id}
                onClick={() => setCurrentUser(user)}
                className="w-full p-6 bg-slate-800/50 hover:bg-green-500/10 border border-slate-700 hover:border-green-500/40 rounded-3xl flex items-center gap-4 transition-all group text-left"
              >
                <div className={`p-3 rounded-2xl ${user.role === UserRole.STOCKIST ? 'bg-green-500 text-black shadow-lg shadow-green-500/20' : 'bg-slate-700 text-green-500'}`}>
                  {user.role === UserRole.STOCKIST ? <UserCircle size={28} /> : <Wrench size={28} />}
                </div>
                <div className="flex-1">
                  <p className="font-bold text-lg group-hover:text-green-400 transition-colors">{user.name}</p>
                  <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold">{user.role === UserRole.STOCKIST ? 'Acesso: Estoquista' : 'Acesso: Mecânico'}</p>
                </div>
                <ArrowRightLeft size={18} className="opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all text-green-400" />
              </button>
            ))}
          </div>
          <p className="text-center text-slate-600 text-[10px] mt-8 font-medium italic tracking-widest uppercase">High Performance SSV • System</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      <aside className="w-full md:w-64 bg-black text-slate-300 p-6 flex flex-col hidden md:flex border-r border-green-500/10 shadow-2xl z-10 print:hidden">
        <div className="mb-12 flex justify-center md:justify-start">
          <HPSLogo size="sm" className="items-start" />
        </div>

        <nav className="flex-1 space-y-2">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all font-bold ${activeTab === 'dashboard' ? 'bg-green-600 text-black shadow-lg shadow-green-600/20' : 'hover:bg-slate-900 hover:text-green-400'}`}
          >
            <TrendingUp size={20} /> Painel Principal
          </button>

          <button 
            onClick={() => setActiveTab('reports')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all font-bold ${activeTab === 'reports' ? 'bg-green-600 text-black shadow-lg shadow-green-600/20' : 'hover:bg-slate-900 hover:text-green-400'}`}
          >
            <FileText size={20} /> Inventário Completo
          </button>

          <button 
            onClick={() => setActiveTab('history')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all font-bold ${activeTab === 'history' ? 'bg-green-600 text-black shadow-lg shadow-green-600/20' : 'hover:bg-slate-900 hover:text-green-400'}`}
          >
            <History size={20} /> Log de Atividades
          </button>
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-800">
          <div className="flex items-center gap-3 mb-6 p-3 rounded-2xl bg-slate-900/50 border border-slate-800">
            <div className="w-10 h-10 bg-green-500 rounded-xl flex items-center justify-center text-black font-black shadow-md uppercase">
              {currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-bold text-white truncate">{currentUser.name}</p>
              <p className="text-[10px] uppercase tracking-widest text-green-500 font-black">{currentUser.role === UserRole.STOCKIST ? 'Estoquista' : 'Mecânico'}</p>
            </div>
          </div>
          <button 
            onClick={() => setCurrentUser(null)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-500/10 hover:text-red-400 transition-all text-slate-500 font-medium"
          >
            <LogOut size={20} /> Sair
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col sm:flex-row items-center justify-between gap-4 shrink-0 shadow-sm z-10 print:hidden">
          <div className="flex items-center gap-4 w-full sm:w-auto">
            <div className="md:hidden">
              <HPSLogo size="sm" />
            </div>
            <div className="relative flex-1 sm:w-80">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Pesquisar ativos ou P/N..." 
                className="w-full pl-12 pr-4 py-2.5 bg-slate-100 rounded-2xl border-none focus:ring-2 focus:ring-green-500/20 outline-none transition-all font-medium"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2 w-full sm:w-auto">
            <button 
              onClick={() => setIsScanning(true)}
              className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-black text-white rounded-2xl hover:bg-slate-800 transition-all font-bold"
            >
              <QrCode size={18} className="text-green-400" /> <span className="hidden sm:inline text-[10px] uppercase tracking-tighter">Scanner QR</span>
            </button>
            {currentUser.role === UserRole.STOCKIST && (
              <button 
                onClick={() => setIsAddingItem(true)}
                className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-green-500 text-black rounded-2xl hover:bg-green-400 shadow-lg shadow-green-500/20 transition-all font-black text-[10px] uppercase"
              >
                <Plus size={18} /> Novo Registro
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {activeTab === 'dashboard' && (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4 cursor-pointer hover:bg-slate-50 transition-colors" onClick={() => setActiveTab('reports')}>
                  <div className="p-3 bg-slate-100 text-black rounded-2xl">
                    <Package size={24} />
                  </div>
                  <div>
                    <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Ativos Diferentes</p>
                    <p className="text-2xl font-black">{items.length}</p>
                  </div>
                </div>
                <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
                  <div className="p-3 bg-green-50 text-green-600 rounded-2xl">
                    <DollarSign size={24} />
                  </div>
                  <div>
                    <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Patrimônio Total</p>
                    <p className="text-2xl font-black">R$ {totalStockValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                </div>
                <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-200 flex items-center gap-4">
                  <div className="p-3 bg-red-50 text-red-600 rounded-2xl">
                    <Zap size={24} />
                  </div>
                  <div>
                    <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Estoque Baixo</p>
                    <p className="text-2xl font-black text-red-600">{items.filter(i => i.quantity <= 5).length}</p>
                  </div>
                </div>
                <div className="bg-black text-white p-5 rounded-[2rem] shadow-xl shadow-black/10 flex items-center gap-4 group cursor-pointer overflow-hidden relative" onClick={fetchInsights}>
                  <div className="absolute top-0 right-0 p-1 opacity-10 group-hover:scale-125 transition-transform">
                     <Package size={80} />
                  </div>
                  <div className={`p-3 rounded-2xl relative z-10 ${loadingInsights ? 'bg-green-500 animate-pulse' : 'bg-green-500 text-black'}`}>
                    <Settings size={24} />
                  </div>
                  <div className="relative z-10">
                    <p className="text-[10px] text-green-500 uppercase font-black tracking-widest">IA Strategic</p>
                    <p className="text-sm font-bold truncate max-w-[120px]">{loadingInsights ? 'Analizando...' : 'Insights HPS'}</p>
                  </div>
                </div>
              </div>

              {insights && (
                <div className="bg-green-600 text-black p-8 rounded-[2.5rem] shadow-xl shadow-green-500/20 flex flex-col sm:flex-row gap-6 items-start relative overflow-hidden">
                  <div className="p-4 bg-black text-green-400 rounded-3xl shrink-0 shadow-lg relative z-10">
                    <Zap size={36} />
                  </div>
                  <div className="flex-1 relative z-10">
                    <h3 className="text-2xl font-black mb-3 italic tracking-tighter">HPS ESTRATÉGICO - INSIGHTS IA</h3>
                    <div className="text-black/80 font-medium leading-relaxed space-y-2 whitespace-pre-wrap">
