          {activeTab === 'reports' && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8">
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6 print:hidden">
                <div>
                  <h2 className="text-3xl font-black text-black uppercase italic tracking-tighter">Relatório de Inventário HPS</h2>
                  <p className="text-slate-500 font-medium">Relatório patrimonial completo de ativos em estoque</p>
                </div>
                <button 
                  onClick={() => window.print()}
