              <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                <div className="bg-black text-white p-8 rounded-[2.5rem] shadow-xl border border-green-500/10">
                  <p className="text-xs font-black text-green-500 uppercase tracking-widest mb-1">Patrimônio Financeiro</p>
                  <p className="text-3xl font-black text-white">R$ {totalStockValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  <p className="text-[10px] text-slate-500 mt-2 italic font-bold">Valor Total das Unidades</p>
