      </main>

      {isAddingItem && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/80">
              <div>
                <h3 className="text-3xl font-black tracking-tight text-slate-800 uppercase italic tracking-tighter">Novo Componente</h3>
                <p className="text-slate-500 font-medium">Cadastrar nova peça na frota HPS</p>
              </div>
              <button onClick={() => setIsAddingItem(false)} className="p-3 bg-white rounded-2xl border border-slate-200 hover:bg-slate-50 text-slate-400 hover:text-slate-800 transition-all">
                <Trash2 size={24} />
              </button>
            </div>
            <form onSubmit={handleAddItem} className="p-10 space-y-8">
              <div className="space-y-5">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Nome da Peça</label>
                    <input required type="text" className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 focus:bg-white rounded-[1.5rem] outline-none transition-all font-bold" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Part Number</label>
                    <input required type="text" className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 focus:bg-white rounded-[1.5rem] outline-none transition-all font-bold" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Valor Unitário (R$)</label>
                    <input required type="number" step="0.01" className="w-full px-5 py-4 bg-green-50/50 border-2 border-green-500/20 text-green-700 rounded-[1.5rem] outline-none font-black text-xl" value={formData.value} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Quantidade</label>
                    <input required type="number" className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 rounded-[1.5rem] outline-none font-black text-xl" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Notas Técnicas</label>
                  <textarea rows={3} className="w-full px-5 py-4 bg-slate-100 border-2 border-transparent focus:border-green-500 rounded-[1.5rem] outline-none transition-all font-medium" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                </div>
              </div>
              <div className="pt-2 flex gap-4">
                <button type="button" onClick={() => setIsAddingItem(false)} className="flex-1 py-5 bg-slate-100 text-slate-500 font-bold rounded-[1.5rem] hover:bg-slate-200 transition-colors uppercase text-[10px]">Cancelar</button>
                <button type="submit" className="flex-[2] py-5 bg-green-500 text-black font-black rounded-[1.5rem] hover:bg-green-400 shadow-2xl shadow-green-500/30 transition-all text-xs uppercase">Salvar no Estoque</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className={`p-10 flex items-center gap-5 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-black text-white'}`}>
              <div className={`p-4 rounded-3xl backdrop-blur-md ${movementModal.type === TransactionType.IN ? 'bg-black/10' : 'bg-green-500/20'}`}>
                {movementModal.type === TransactionType.IN ? <Plus size={40} strokeWidth={3} /> : <LogOut size={40} className="rotate-180" strokeWidth={3} />}
              </div>
              <div>
                <h3 className="text-3xl font-black uppercase italic tracking-tighter">Registrar {movementModal.type === TransactionType.IN ? 'Entrada' : 'Saída'}</h3>
                <p className={`font-black uppercase tracking-widest text-[10px] ${movementModal.type === TransactionType.IN ? 'text-black/60' : 'text-green-500'}`}>
                  {items.find(i => i.id === movementModal.itemId)?.name}
                </p>
              </div>
            </div>
            <div className="p-10 space-y-8">
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Quantidade</label>
                  <input type="number" min="1" className="w-full px-8 py-6 bg-slate-100 border-none rounded-[2rem] text-4xl font-black focus:ring-4 focus:ring-green-500/10 outline-none text-center" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{movementModal.type === TransactionType.IN ? 'Fornecedor / Origem' : 'Destinatário / OS'}</label>
                  <input type="text" className="w-full px-6 py-4 bg-slate-100 border-none rounded-[1.5rem] focus:ring-2 focus:ring-green-500/20 outline-none font-bold" value={recipient} onChange={e => setRecipient(e.target.value)} />
                </div>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-5 bg-slate-100 text-slate-500 font-bold rounded-[1.5rem] hover:bg-slate-200 transition-colors uppercase text-[10px]">Voltar</button>
                <button onClick={processMovement} className={`flex-[2] py-5 font-black rounded-[1.5rem] transition-all text-xs shadow-xl uppercase ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black hover:bg-green-400 shadow-green-500/20' : 'bg-black text-white hover:bg-slate-900 shadow-black/20'}`}>Confirmar Movimento</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

export enum UserRole {
  STOCKIST = 'STOCKIST',
  MECHANIC = 'MECHANIC'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  minQuantity: number; // Estoque mínimo para alerta
  qrGroup: string;     // Ex: "QR 1 - FREIOS"
  entryDate: string;
  description?: string;
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string; // No caso de saída, o mecânico
  notes?: string;       // Observações da baixa
}

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, 
  Package, 
  Search, 
  QrCode, 
  Settings, 
  LogOut, 
  TrendingUp, 
  History, 
  Trash2, 
  UserCircle,
  Zap,
  DollarSign,
  ArrowRightLeft,
  Wrench,
  FileText,
  Printer,
  AlertTriangle,
  ClipboardList,
  UserCheck
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

const MOCK_USERS: User[] = [
  { id: '1', name: 'Estoquista Principal', role: UserRole.STOCKIST },
  { id: '2', name: 'Mecânico', role: UserRole.MECHANIC },
];

const QR_GROUPS = [
  "QR 1 - FREIOS",
  "QR 2 - SUSPENSÃO",
  "QR 3 - MOTOR",
  "QR 4 - TRANSMISSÃO",
  "QR 5 - ELÉTRICA",
  "QR 6 - ACESSÓRIOS"
];

const MECANICOS = [
  "Carlos Silva",
  "Roberto Souza",
  "Marcos Oliveira",
  "Felipe Santos",
  "Uso Geral / Frota"
];

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'reports' | 'restock';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg', className?: string }> = ({ size = 'md', className = "" }) => {
  const dimensions = {
    sm: { width: '80px' },
    md: { width: '120px' },
    lg: { width: '200px' }
  };

  return (
    <div className={`flex flex-col items-center ${className} select-none`}>
      <img 
        src="logo.png" 
        alt="HPS CONTROL" 
        style={dimensions[size]}
        className="drop-shadow-[0_0_15px_rgba(0,255,0,0.3)] object-contain"
        onError={(e) => {
          e.currentTarget.style.display = 'none';
        }}
      />
    </div>
  );
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    partNumber: '',
    value: 0,
    quantity: 0,
    minQuantity: 1,
    qrGroup: QR_GROUPS[0],
    description: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false,
    itemId: null,
    type: TransactionType.OUT
  });

  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [movementNotes, setMovementNotes] = useState('');

  // Persist data
  useEffect(() => {
    const savedItems = localStorage.getItem('hps_items');
    const savedHistory = localStorage.getItem('hps_history');
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_items', JSON.stringify(items));
    localStorage.setItem('hps_history', JSON.stringify(history));
  }, [items, history]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      ...formData,
      entryDate: new Date().toISOString()
    };
    setItems(prev => [...prev, newItem]);

    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      itemId: newItem.id,
      itemName: newItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: TransactionType.IN,
      quantity: newItem.quantity,
      date: new Date().toISOString(),
      recipientName: 'Cadastro Inicial',
      notes: 'Entrada via cadastro de novo ativo.'
    }]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, qrGroup: QR_GROUPS[0], description: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId) return;

    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;

    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Quantidade insuficiente em estoque!");
      return;
    }

    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: currentItem.id,
      itemName: currentItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: movementModal.type,
      quantity: movementQty,
      date: new Date().toISOString(),
      recipientName: recipient || (movementModal.type === TransactionType.IN ? 'Fornecedor' : 'Não Informado'),
      notes: movementNotes
    };
    setHistory(prev => [...prev, log]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1);
    setRecipient('');
    setMovementNotes('');
  };

  const handleQRScan = (decodedText: string) => {
    // Busca por Part Number ou ID
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setActiveTab('inventory');
      setSearchTerm(item.partNumber);
      setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else {
      // Verifica se é um grupo
      if (QR_GROUPS.includes(decodedText)) {
        setActiveTab('inventory');
        setSearchTerm(decodedText);
      } else {
