                  <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Log de Movimentações</h2>
                  <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-[0.2em]">Auditoria de Entradas e Saídas Destinadas</p>
                </div>
              </div>
              <TransactionHistory transactions={history} />
            </div>
          )}

          {activeTab === 'inventory' && (
             <div className="bg-zinc-900 p-10 rounded-[3rem] border border-zinc-800">
               <h3 className="text-2xl font-black mb-8 italic uppercase tracking-tighter">Busca Avançada de Itens</h3>
               {/* Aqui seria uma lista filtrada simples para o mecânico */}
