                          <span className={`font-black text-xl ${item.quantity <= item.minQuantity ? 'text-amber-500 underline decoration-amber-500' : 'text-zinc-300'}`}>{item.quantity}</span>
                        </td>
                        <td className="px-8 py-6 text-right font-bold text-zinc-500">
                          R$ {item.value.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </td>
                        <td className="px-8 py-6 text-right font-black text-green-400 text-xl">
