                    <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest px-2">Nome da Peça</label>
                    <input required type="text" className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none transition-all font-black text-white" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest px-2">Part Number</label>
                    <input required type="text" className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none transition-all font-black text-white" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest px-2">Vínculo de Grupo QR</label>
                    <select className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none transition-all font-black text-white uppercase text-xs" value={formData.qrGroup} onChange={e => setFormData({...formData, qrGroup: e.target.value})}>
                      {QR_GROUPS.map(g => <option key={g} value={g}>{g}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest px-2">Preço Unitário (R$)</label>
                    <input required type="number" step="0.01" className="w-full px-6 py-4 bg-green-500/5 border-2 border-green-500/20 text-green-700 rounded-2xl outline-none font-black text-xl" value={formData.value} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest px-2">Saldo Atual</label>
                    <input required type="number" className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none font-black text-xl text-white" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest px-2 text-amber-500">Estoque Mínimo (Alerta)</label>
                    <input required type="number" className="w-full px-6 py-4 bg-amber-500/5 border-2 border-amber-500/20 text-amber-500 rounded-2xl outline-none font-black text-xl" value={formData.minQuantity} onChange={e => setFormData({...formData, minQuantity: parseInt(e.target.value) || 1})} />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest px-2">Notas / Ficha Técnica</label>
                  <textarea rows={2} className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none transition-all font-bold text-white text-sm" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                </div>
              </div>
              <div className="pt-4 flex gap-4">
                <button type="button" onClick={() => setIsAddingItem(false)} className="flex-1 py-5 bg-zinc-800 text-zinc-500 font-black rounded-2xl hover:bg-zinc-700 transition-colors uppercase text-[10px]">Cancelar</button>
                <button type="submit" className="flex-[2] py-5 bg-green-500 text-black font-black rounded-2xl hover:bg-green-400 shadow-2xl shadow-green-500/30 transition-all text-xs uppercase">Concluir Cadastro</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL: MOVIMENTAÇÃO (BAIXA) */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-xl z-50 flex items-center justify-center p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom-10 duration-300">
            <div className={`p-12 flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
              <div className={`p-5 rounded-3xl ${movementModal.type === TransactionType.IN ? 'bg-black/10' : 'bg-black/5'}`}>
                {movementModal.type === TransactionType.IN ? <Plus size={48} strokeWidth={3} /> : <LogOut size={48} className="rotate-180" strokeWidth={3} />}
              </div>
              <div>
                <h3 className="text-3xl font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada HPS' : 'Saída HPS'}</h3>
                <p className="font-black uppercase tracking-widest text-[10px] opacity-70">
                  Item: {items.find(i => i.id === movementModal.itemId)?.name}
                </p>
              </div>
            </div>
            <div className="p-12 space-y-10">
              <div className="space-y-8">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">Volume da Movimentação</label>
                  <input 
                    type="number" 
                    min="1"
                    className="w-full px-8 py-8 bg-zinc-950 border border-zinc-800 rounded-3xl text-5xl font-black focus:ring-4 focus:ring-green-500/10 outline-none text-center text-green-500"
                    value={movementQty}
                    onChange={e => setMovementQty(parseInt(e.target.value) || 1)}
                  />
                </div>

                <div className="grid grid-cols-1 gap-8">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2 flex items-center gap-2">
                      <UserCheck size={14} /> {movementModal.type === TransactionType.IN ? 'Origem / Fornecedor' : 'Destinar ao Mecânico'}
                    </label>
                    {movementModal.type === TransactionType.OUT ? (
                      <select className="w-full px-6 py-4 bg-zinc-800 border-none rounded-2xl focus:ring-2 focus:ring-green-500/40 outline-none font-black text-white text-xs uppercase" value={recipient} onChange={e => setRecipient(e.target.value)}>
                        <option value="">Selecione o Profissional...</option>
                        {MECANICOS.map(m => <option key={m} value={m}>{m}</option>)}
                      </select>
                    ) : (
                      <input type="text" placeholder="Nome do Fornecedor..." className="w-full px-6 py-4 bg-zinc-800 border-none rounded-2xl focus:ring-2 focus:ring-green-500/40 outline-none font-black text-white text-xs" value={recipient} onChange={e => setRecipient(e.target.value)} />
                    )}
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">Observações / Ordem de Serviço</label>
                    <textarea 
                      placeholder="Ex: OS #2201 - Reparo Suspensão Dianteira..."
                      className="w-full px-6 py-4 bg-zinc-800 border-none rounded-2xl focus:ring-2 focus:ring-green-500/40 outline-none font-bold text-white text-xs"
                      rows={2}
                      value={movementNotes}
                      onChange={e => setMovementNotes(e.target.value)}
                    />
                  </div>
                </div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => {
                    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
                    setRecipient('');
                    setMovementNotes('');
                  }} 
                  className="flex-1 py-5 bg-zinc-800 text-zinc-500 font-black rounded-2xl hover:bg-zinc-700 transition-colors uppercase text-[10px]"
                >
                  Voltar
                </button>
                <button 
                  onClick={processMovement}
                  className={`flex-[2] py-5 font-black rounded-2xl transition-all text-xs shadow-2xl uppercase ${
                    movementModal.type === TransactionType.IN 
                    ? 'bg-green-500 text-black hover:bg-green-400 shadow-green-500/20' 
                    : 'bg-white text-black hover:bg-zinc-200 shadow-white/10'
                  }`}
                >
                  Confirmar Registro
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, 
  Package, 
  Search, 
  QrCode, 
  Settings, 
  LogOut, 
  TrendingUp, 
  History, 
  Trash2, 
  UserCircle,
  Zap,
  DollarSign,
  ArrowRightLeft,
  Wrench,
  FileText,
  Printer,
  AlertTriangle,
  ClipboardList,
  UserCheck,
  ChevronRight,
  Users,
  Download,
  PlusCircle,
  X
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

const MOCK_USERS: User[] = [
  { id: '1', name: 'Estoquista Principal', role: UserRole.STOCKIST },
  { id: '2', name: 'Mecânico', role: UserRole.MECHANIC },
];

const QR_GROUPS = [
  "QR 1 - FREIOS",
  "QR 2 - SUSPENSÃO",
  "QR 3 - MOTOR",
  "QR 4 - TRANSMISSÃO",
  "QR 5 - ELÉTRICA",
  "QR 6 - ACESSÓRIOS"
];

const MECANICOS = [
  "João Paulo",
  "Romulo",
  "Leonardo",
  "Anselmo",
  "David",
  "Uso Geral / Frota"
];

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'reports' | 'restock' | 'team';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg', className?: string }> = ({ size = 'md', className = "" }) => {
  const dimensions = {
    sm: { width: '80px' },
    md: { width: '120px' },
    lg: { width: '200px' }
  };

  return (
    <div className={`flex flex-col items-center ${className} select-none`}>
      <img 
        src="logo.png" 
        alt="HPS CONTROL" 
        style={dimensions[size]}
        className="drop-shadow-[0_0_15px_rgba(0,255,0,0.3)] object-contain"
        onError={(e) => {
          e.currentTarget.style.display = 'none';
        }}
      />
    </div>
  );
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [selectedMechanic, setSelectedMechanic] = useState<string>(MECANICOS[0]);

  // Quick Assign State
  const [isAssigningModalOpen, setIsAssigningModalOpen] = useState(false);
  const [assignSearch, setAssignSearch] = useState('');
  const [assignQty, setAssignQty] = useState(1);
  const [selectedItemToAssign, setSelectedItemToAssign] = useState<InventoryItem | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    partNumber: '',
    value: 0,
    quantity: 0,
    minQuantity: 1,
    qrGroup: QR_GROUPS[0],
    description: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false,
    itemId: null,
    type: TransactionType.OUT
  });

  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [movementNotes, setMovementNotes] = useState('');

  const fetchInsights = useCallback(async () => {
    if (loadingInsights) return;
    setLoadingInsights(true);
    try {
      const result = await getStockInsights(items, history);
      setInsights(result || "Análise concluída com sucesso.");
    } catch (error) {
      console.error("Gemini Error:", error);
      setInsights("Não foi possível gerar insights no momento.");
    } finally {
      setLoadingInsights(false);
    }
  }, [items, history, loadingInsights]);

  // Persist data
  useEffect(() => {
    const savedItems = localStorage.getItem('hps_items');
    const savedHistory = localStorage.getItem('hps_history');
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_items', JSON.stringify(items));
    localStorage.setItem('hps_history', JSON.stringify(history));
  }, [items, history]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      ...formData,
      entryDate: new Date().toISOString()
    };
    setItems(prev => [...prev, newItem]);

    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      itemId: newItem.id,
      itemName: newItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: TransactionType.IN,
      quantity: newItem.quantity,
      date: new Date().toISOString(),
      recipientName: 'Cadastro Inicial',
      notes: 'Entrada via cadastro de novo ativo.'
    }]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, qrGroup: QR_GROUPS[0], description: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId) return;

    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;

    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Quantidade insuficiente em estoque!");
      return;
    }

    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: currentItem.id,
      itemName: currentItem.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: movementModal.type,
      quantity: movementQty,
      date: new Date().toISOString(),
      recipientName: recipient || (movementModal.type === TransactionType.IN ? 'Fornecedor' : 'Não Informado'),
      notes: movementNotes
    };
    setHistory(prev => [...prev, log]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1);
    setRecipient('');
    setMovementNotes('');
  };

  // Quick Assignment for Team Tab
  const handleQuickAssign = () => {
    if (!selectedItemToAssign || assignQty < 1) return;

    if (selectedItemToAssign.quantity < assignQty) {
      alert("Saldo insuficiente no estoque principal!");
      return;
    }

    const itemIndex = items.findIndex(i => i.id === selectedItemToAssign.id);
    const updatedItems = [...items];
    updatedItems[itemIndex].quantity -= assignQty;
    setItems(updatedItems);

    const log: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: selectedItemToAssign.id,
      itemName: selectedItemToAssign.name,
      userId: currentUser!.id,
      userName: currentUser!.name,
      type: TransactionType.OUT,
      quantity: assignQty,
      date: new Date().toISOString(),
      recipientName: selectedMechanic,
      notes: `Lançamento direto via Ficha de Equipe (Admin)`
    };

    setHistory(prev => [...prev, log]);
    setIsAssigningModalOpen(false);
    setSelectedItemToAssign(null);
    setAssignQty(1);
    setAssignSearch('');
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setActiveTab('inventory');
      setSearchTerm(item.partNumber);
      setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else {
      if (QR_GROUPS.includes(decodedText)) {
        setActiveTab('inventory');
        setSearchTerm(decodedText);
      } else {
        alert("Código não reconhecido pelo sistema HPS.");
      }
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
    i.qrGroup.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const assignFilteredItems = items.filter(i => 
    i.name.toLowerCase().includes(assignSearch.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(assignSearch.toLowerCase())
  );

  const criticalItems = items.filter(i => i.quantity <= i.minQuantity);
  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);

  const mechanicHistory = history.filter(h => h.recipientName === selectedMechanic && h.type === TransactionType.OUT);

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
        <div className="bg-zinc-900/60 backdrop-blur-2xl p-10 rounded-[2.5rem] border border-green-500/20 w-full max-w-md text-white shadow-2xl">
          <div className="flex flex-col items-center mb-10">
            <HPSLogo size="lg" className="mb-6" />
            <div className="h-1 w-20 bg-green-500 rounded-full mb-6"></div>
            <h1 className="text-xl font-black tracking-widest text-white text-center uppercase italic">Controle Operacional</h1>
          </div>

          <div className="space-y-4">
            {MOCK_USERS.map(user => (
              <button
                key={user.id}
                onClick={() => setCurrentUser(user)}
                className="w-full p-6 bg-zinc-800/50 hover:bg-green-500/10 border border-zinc-700 hover:border-green-500/40 rounded-3xl flex items-center gap-4 transition-all group text-left"
              >
                <div className={`p-3 rounded-2xl ${user.role === UserRole.STOCKIST ? 'bg-green-500 text-black' : 'bg-zinc-700 text-green-500'}`}>
                  {user.role === UserRole.STOCKIST ? <UserCircle size={28} /> : <Wrench size={28} />}
                </div>
                <div className="flex-1">
                  <p className="font-black text-lg group-hover:text-green-400 transition-colors uppercase tracking-tighter">{user.name}</p>
                  <p className="text-[10px] uppercase tracking-widest text-zinc-500 font-bold">{user.role === UserRole.STOCKIST ? 'Perfil: Estoque' : 'Perfil: Oficina'}</p>
                </div>
                <ChevronRight size={18} className="text-zinc-600 group-hover:text-green-400" />
              </button>
            ))}
          </div>
          <p className="text-center text-zinc-600 text-[9px] mt-10 font-bold italic tracking-[0.2em] uppercase">High Performance SSV</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 font-sans">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-black p-6 flex flex-col hidden md:flex border-r border-green-500/10 shadow-2xl z-20 print:hidden shrink-0">
        <div className="mb-10 flex justify-center">
          <HPSLogo size="sm" />
        </div>

        <nav className="flex-1 space-y-1.5">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-2xl transition-all font-black uppercase text-[11px] tracking-wider ${activeTab === 'dashboard' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900 hover:text-green-400'}`}
          >
            <TrendingUp size={18} /> Painel Principal
          </button>

          {currentUser.role === UserRole.STOCKIST && (
            <button 
              onClick={() => setActiveTab('team')}
              className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-2xl transition-all font-black uppercase text-[11px] tracking-wider ${activeTab === 'team' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900 hover:text-green-400'}`}
            >
              <Users size={18} /> Gestão de Equipe
            </button>
          )}

          <button 
            onClick={() => setActiveTab('reports')}
            className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-2xl transition-all font-black uppercase text-[11px] tracking-wider ${activeTab === 'reports' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900 hover:text-green-400'}`}
          >
            <FileText size={18} /> Inventário Geral
          </button>

          <button 
            onClick={() => setActiveTab('restock')}
            className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-2xl transition-all font-black uppercase text-[11px] tracking-wider relative ${activeTab === 'restock' ? 'bg-amber-500 text-black' : 'text-zinc-400 hover:bg-zinc-900 hover:text-amber-400'}`}
          >
            <AlertTriangle size={18} /> Reposição
            {criticalItems.length > 0 && (
              <span className="absolute top-2 right-2 flex h-4 w-4">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-4 w-4 bg-red-600 text-[9px] text-white items-center justify-center font-black">{criticalItems.length}</span>
              </span>
            )}
          </button>

          <button 
            onClick={() => setActiveTab('history')}
            className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-2xl transition-all font-black uppercase text-[11px] tracking-wider ${activeTab === 'history' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900 hover:text-green-400'}`}
          >
            <History size={18} /> Histórico Geral
          </button>
        </nav>

        <div className="mt-auto pt-6 border-t border-zinc-800">
          <div className="flex items-center gap-3 mb-6 p-4 rounded-2xl bg-zinc-900/50 border border-zinc-800">
            <div className="w-10 h-10 bg-green-500 rounded-xl flex items-center justify-center text-black font-black shadow-md uppercase">
              {currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-xs font-black text-white truncate uppercase">{currentUser.name}</p>
              <p className="text-[9px] uppercase tracking-widest text-green-500 font-black">{currentUser.role === UserRole.STOCKIST ? 'Administrador' : 'Oficina'}</p>
            </div>
          </div>
          <button 
            onClick={() => setCurrentUser(null)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-500/10 hover:text-red-400 transition-all text-zinc-600 font-bold uppercase text-[10px]"
          >
            <LogOut size={18} /> Sair do Sistema
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-black/40 backdrop-blur-xl border-b border-zinc-800 px-6 py-4 flex flex-col sm:flex-row items-center justify-between gap-4 shrink-0 z-10 print:hidden">
          <div className="flex items-center gap-4 w-full sm:w-auto">
            <div className="md:hidden">
              <HPSLogo size="sm" />
            </div>
            <div className="relative flex-1 sm:w-96">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500" size={18} />
