  "QR 1 - FREIOS",
  "QR 2 - SUSPENSÃO",
  "QR 3 - MOTOR",
  "QR 4 - TRANSMISSÃO",
  "QR 5 - ELÉTRICA",
  "QR 6 - ACESSÓRIOS"
];

