import React, { useEffect, useRef } from 'react';
import { X, QrCode } from 'lucide-react';

interface QRScannerProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
}

declare const Html5QrcodeScanner: any;

const QRScanner: React.FC<QRScannerProps> = ({ onScan, onClose }) => {
  const scannerRef = useRef<any>(null);

  useEffect(() => {
    // Configurações para priorizar a câmera traseira em celulares
    scannerRef.current = new Html5QrcodeScanner(
      "qr-reader",
      { 
        fps: 15, 
        qrbox: { width: 250, height: 250 },
        aspectRatio: 1.0,
        showTorchButtonIfSupported: true,
        videoConstraints: {
          facingMode: { exact: "environment" } // Prioriza câmera traseira
        }
      },
      /* verbose= */ false
    );

    scannerRef.current.render((decodedText: string) => {
      onScan(decodedText);
      // Oculta o scanner após leitura bem sucedida
      if (scannerRef.current) {
        scannerRef.current.clear().catch((e: any) => console.error(e));
      }
      onClose();
    }, (error: any) => {
      // Ignora erros de leitura contínua (comum durante busca de foco)
    });

    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear().catch((e: any) => console.error(e));
      }
    };
  }, [onScan, onClose]);

  return (
    <div className="fixed inset-0 bg-black/98 z-[120] flex items-center justify-center p-4 backdrop-blur-xl">
      <div className="bg-white rounded-[2.5rem] w-full max-w-lg overflow-hidden relative shadow-2xl border-4 border-green-500/20">
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 p-3 bg-slate-100/80 rounded-2xl hover:bg-red-100 hover:text-red-500 transition-all z-[130] text-slate-500"
        >
          <X size={20} />
        </button>
        <div className="p-6 sm:p-10">
          <div className="flex items-center gap-3 mb-6">
            <div className="bg-green-500 p-2 rounded-xl text-black shadow-lg">
              <QrCode size={20} strokeWidth={2.5} />
            </div>
            <h3 className="text-xl font-black tracking-tight uppercase italic">Scanner Ativo</h3>
          </div>

          <div className="rounded-[1.5rem] overflow-hidden border-2 border-green-500/20 bg-black">
            <div id="qr-reader" className="w-full"></div>
          </div>

          <div className="mt-6 text-center space-y-2">
            <p className="font-black text-slate-800 uppercase tracking-widest text-xs">Identificando Componente...</p>
            <p className="text-[10px] text-slate-400 font-bold px-4 italic leading-relaxed">
              Posicione o código QR no centro da moldura para leitura automática.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

