      {/* MODAL: MOVIMENTAÇÃO (ADMIN) */}
      {movementModal.isOpen && isAdmin && (
        <div className="fixed inset-0 bg-black/98 z-[100] flex items-center justify-center p-4 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3rem] w-full max-w-lg shadow-glow overflow-hidden">
            <div className={`p-10 flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
              <div className="p-5 rounded-3xl bg-black/10">
                {movementModal.type === TransactionType.IN ? <Plus size={36} /> : <LogOut size={36} className="rotate-180" />}
              </div>
              <div>
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada HPS' : 'Saída HPS'}</h3>
