          </div>

          {authView === 'login' && (
            <form onSubmit={handleLogin} className="space-y-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-zinc-500 tracking-widest ml-4">Usuário / Identificação</label>
                <div className="relative">
                  <UserCircle className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                  <input required type="text" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})}
                    className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black uppercase text-sm focus:ring-2 focus:ring-green-500/30 transition-all" placeholder="USUÁRIO" />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-zinc-500 tracking-widest ml-4">Senha de Acesso</label>
                <div className="relative">
                  <KeyRound className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                  <input required type="password" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})}
                    className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black text-sm focus:ring-2 focus:ring-green-500/30 transition-all" placeholder="••••••••" />
                </div>
              </div>
              <div className="flex justify-between items-center px-4">
                <button type="button" onClick={() => {setAuthView('forgot'); setLoginError('');}} className="text-[9px] font-black uppercase text-zinc-600 hover:text-white transition-colors">Esqueci minha senha</button>
                <button type="button" onClick={() => {setAuthView('signup'); setLoginError('');}} className="text-[9px] font-black uppercase text-green-600 hover:text-green-400 transition-colors">Primeiro acesso</button>
              </div>
              {loginError && <p className="text-red-500 text-[10px] font-black uppercase text-center animate-pulse">{loginError}</p>}
              <button type="submit" className="w-full py-6 bg-green-500 text-black rounded-[2rem] font-black uppercase text-sm hover:bg-green-400 transition-all shadow-glow flex items-center justify-center gap-3">
                <ShieldCheck size={20} /> Autenticar
              </button>
            </form>
          )}

          {authView === 'signup' && (
            <form onSubmit={handleSignup} className="space-y-4">
              <div className="flex justify-center mb-4">
                <div className="w-24 h-24 bg-black border-2 border-dashed border-zinc-800 rounded-full flex flex-col items-center justify-center text-zinc-700 hover:text-green-500 hover:border-green-500 transition-all cursor-pointer overflow-hidden relative group">
                  {signupForm.avatarUrl ? (
                    <img src={signupForm.avatarUrl} className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <Camera size={24} />
                      <span className="text-[8px] font-black uppercase mt-1">Sua Foto</span>
                    </>
                  )}
                  <input type="url" placeholder="URL da foto" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => setSignupForm({...signupForm, avatarUrl: e.target.value})} />
                </div>
              </div>
              <input required type="text" placeholder="NOME COMPLETO" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-xs" />
              <input required type="text" placeholder="NOME DE USUÁRIO (LOGIN)" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-xs" />
              <input required type="password" placeholder="CRIE UMA SENHA" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black text-xs" />
              <div className="space-y-1">
                <label className="text-[9px] font-black uppercase text-zinc-500 ml-4">FUNÇÃO / CARGO</label>
                <select className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-xs" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
                  <option value={UserRole.MECHANIC}>Oficina / Mecânico</option>
                  <option value={UserRole.STOCKIST}>Gestão / Estoque</option>
                </select>
              </div>
              <button type="submit" className="w-full py-5 bg-green-500 text-black rounded-[1.5rem] font-black uppercase text-xs hover:bg-green-400 transition-all mt-4">Criar Minha Conta</button>
              <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-500 hover:text-white">Já tenho acesso</button>
            </form>
          )}

          {authView === 'forgot' && (
            <form onSubmit={handleValidateForReset} className="space-y-6">
              <p className="text-zinc-500 text-[10px] font-bold uppercase text-center px-4 leading-relaxed">Localize sua conta HPS informando seu nome de usuário para redefinir sua senha.</p>
              <div className="relative">
                <UserCircle className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                <input required type="text" value={forgotForm.username} onChange={e => setForgotForm({username: e.target.value})}
                  className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black uppercase text-sm" placeholder="USUÁRIO" />
              </div>
              {loginError && <p className="text-red-500 text-[10px] font-black uppercase text-center animate-pulse">{loginError}</p>}
              <button type="submit" className="w-full py-6 bg-white text-black rounded-[2rem] font-black uppercase text-sm hover:bg-zinc-200 transition-all">Verificar Usuário</button>
              <button type="button" onClick={() => {setAuthView('login'); setLoginError('');}} className="w-full text-[9px] font-black uppercase text-zinc-500 hover:text-white">Voltar para o Login</button>
            </form>
          )}

          {authView === 'reset' && (
            <form onSubmit={handleSetNewPassword} className="space-y-6">
              <p className="text-zinc-500 text-[10px] font-bold uppercase text-center px-4 leading-relaxed italic">
                Crie sua nova chave de acesso HPS para o usuário: <span className="text-green-500 font-black">{resetTargetUser}</span>
              </p>
              <div className="space-y-4">
                <div className="relative">
                  <KeyRound className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                  <input required type="password" value={resetForm.password} onChange={e => setResetForm({...resetForm, password: e.target.value})}
                    className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black text-sm" placeholder="NOVA SENHA" />
                </div>
                <div className="relative">
                  <RefreshCcw className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                  <input required type="password" value={resetForm.confirmPassword} onChange={e => setResetForm({...resetForm, confirmPassword: e.target.value})}
                    className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black text-sm" placeholder="CONFIRMAR SENHA" />
                </div>
              </div>
              {loginError && <p className="text-red-500 text-[10px] font-black uppercase text-center animate-pulse">{loginError}</p>}
              <button type="submit" className="w-full py-6 bg-green-500 text-black rounded-[2rem] font-black uppercase text-sm hover:bg-green-400 transition-all shadow-glow">Gravar Nova Senha</button>
              <button type="button" onClick={() => {setAuthView('login'); setResetTargetUser(null); setLoginError('');}} className="w-full text-[9px] font-black uppercase text-zinc-500 hover:text-white">Cancelar e Sair</button>
            </form>
          )}

          <p className="text-center text-zinc-700 text-[8px] mt-10 font-bold uppercase tracking-widest italic">High Performance SSV</p>
        </div>
      </div>
    );
  }

  const isAdmin = currentUser.role === UserRole.STOCKIST;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 font-sans">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-black p-6 flex flex-col hidden md:flex border-r border-green-500/10 shadow-2xl z-20 print:hidden shrink-0">
        <div className="mb-10 flex justify-center"><HPSLogo size="sm" /></div>

        <nav className="flex-1 space-y-1.5">
          <button onClick={() => setActiveTab('dashboard')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'dashboard' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
            <TrendingUp size={18} /> {isAdmin ? 'Painel Geral' : 'Meu Espelho'}
          </button>

          {isAdmin && (
            <>
              <button onClick={() => setActiveTab('team')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'team' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
                <Users size={18} /> Gestão de Equipe
              </button>
              <button onClick={() => setActiveTab('users')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'users' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
                <Lock size={18} /> Contas de Acesso
              </button>
            </>
          )}

          <button onClick={() => setActiveTab('reports')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'reports' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
            <FileText size={18} /> Inventário
          </button>

          {isAdmin && (
            <button onClick={() => setActiveTab('restock')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider relative ${activeTab === 'restock' ? 'bg-amber-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
              <AlertTriangle size={18} /> Reposição
              {criticalItems.length > 0 && <span className="absolute top-2 right-2 bg-red-600 rounded-full h-4 w-4 flex items-center justify-center text-[8px] text-white font-black">{criticalItems.length}</span>}
            </button>
          )}

          <button onClick={() => setActiveTab('history')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'history' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
            <History size={18} /> Log de Movimentos
          </button>
        </nav>

        <div className="mt-auto pt-6 border-t border-zinc-800">
          <button 
            onClick={() => setActiveTab('profile')}
            className={`w-full flex items-center gap-3 p-4 rounded-2xl mb-4 transition-all border ${activeTab === 'profile' ? 'bg-green-500/10 border-green-500 shadow-glow' : 'bg-zinc-900/50 border-zinc-800 hover:border-zinc-700'}`}
          >
            <div className="w-10 h-10 bg-zinc-800 rounded-xl flex items-center justify-center text-green-500 font-black uppercase shadow-glow overflow-hidden">
              {currentUser.avatarUrl ? <img src={currentUser.avatarUrl} className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden text-left">
              <p className="text-[11px] font-black text-white truncate uppercase">{currentUser.name}</p>
              <p className="text-[8px] uppercase tracking-widest text-green-500 font-bold">Meu Perfil</p>
            </div>
            <Edit3 size={14} className="ml-auto text-zinc-600" />
          </button>
          <button onClick={() => setCurrentUser(null)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-500/10 hover:text-red-400 transition-all text-zinc-600 font-black uppercase text-[9px]">
            <LogOut size={18} /> Encerrar Sessão
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-black/40 backdrop-blur-xl border-b border-zinc-800 px-4 py-4 flex items-center justify-between gap-4 shrink-0 z-10 print:hidden">
          <div className="flex items-center gap-4 w-full sm:w-auto">
            <div className="md:hidden" onClick={() => setActiveTab('profile')}>
                <div className="w-10 h-10 rounded-full border border-green-500/30 overflow-hidden bg-zinc-800 flex items-center justify-center">
                    {currentUser.avatarUrl ? <img src={currentUser.avatarUrl} className="w-full h-full object-cover" /> : <UserCircle size={24} className="text-green-500" />}
                </div>
            </div>
            <div className="relative flex-1 sm:w-80 lg:w-96">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500" size={18} />
              <input type="text" placeholder="Localizar item..." className="w-full pl-12 pr-4 py-3 bg-zinc-900 border border-zinc-800 rounded-2xl outline-none font-bold text-sm text-white focus:ring-2 focus:ring-green-500/20 transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
