          <div className="flex items-center gap-2">
            <button onClick={() => setIsScanning(true)} className="p-3 bg-white text-black rounded-2xl hover:bg-zinc-200 transition-all shadow-xl"><QrCode size={20} /></button>
            {isAdmin && <button onClick={() => setIsAddingItem(true)} className="p-3 bg-green-500 text-black rounded-2xl hover:bg-green-400 shadow-xl"><Plus size={20} /></button>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-8">
          {activeTab === 'dashboard' && (
            <div className="animate-in fade-in duration-500 space-y-10">
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {isAdmin ? (
                  <>
                    <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2.5rem] flex items-center gap-4">
                      <div className="p-4 bg-zinc-800 text-green-500 rounded-2xl"><Package size={24} /></div>
                      <div><p className="text-[9px] text-zinc-500 uppercase font-black tracking-widest">SKUs</p><p className="text-2xl font-black text-white">{items.length}</p></div>
