                    <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2.5rem] flex items-center gap-4">
                      <div className="p-4 bg-green-500/10 text-green-500 rounded-2xl"><DollarSign size={24} /></div>
                      <div><p className="text-[9px] text-zinc-500 uppercase font-black tracking-widest">Patrimônio</p><p className="text-xl font-black text-white">R$ {totalStockValue.toLocaleString('pt-BR')}</p></div>
