                      <div className="p-4 bg-amber-500/10 text-amber-500 rounded-2xl"><AlertTriangle size={24} /></div>
                      <div><p className="text-[9px] text-zinc-500 uppercase font-black tracking-widest">Reposição</p><p className="text-2xl font-black text-white">{criticalItems.length}</p></div>
