                      <div className="p-4 bg-black text-green-500 rounded-2xl">{loadingInsights ? <div className="animate-spin h-5 w-5 border-2 border-t-green-500 rounded-full"></div> : <Zap size={24} />}</div>
                      <div><p className="text-[9px] text-black font-black uppercase tracking-widest">IA Strategic</p><p className="text-xs font-black text-black">Insights</p></div>
