                      <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter text-glow">Bem-vindo, {currentUser.name}!</h2>
                      <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-widest mt-2">Sessão ativa sob supervisão HPS.</p>
                    </div>
                    <div className="text-right">
                      <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest italic">Retiradas no seu nome</p>
