                        <p className="text-xs text-zinc-500 font-bold uppercase tracking-widest opacity-80">{item.description || 'Padrão HPS'}</p>
                      </div>
                      <div className="text-center md:text-right">
                        <p className="text-[9px] text-zinc-600 uppercase font-black tracking-widest mb-1">Disponível</p>
