                        <div className="flex gap-2">
                          <button onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.IN })} className="p-4 bg-zinc-800 text-green-500 rounded-2xl hover:bg-green-500 hover:text-black transition-all shadow-glow"><Plus size={20} /></button>
                          <button onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT })} className="p-4 bg-green-500 text-black rounded-2xl hover:bg-black hover:text-green-500 transition-all shadow-glow"><LogOut size={20} className="rotate-180" /></button>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'profile' && (
            <div className="animate-in fade-in slide-in-from-right-10 duration-500 max-w-2xl mx-auto space-y-10">
              <div className="flex items-center gap-6">
                <div className="p-5 bg-green-500 text-black rounded-3xl shadow-glow"><Edit3 size={32} /></div>
                <div>
                  <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Meu Cadastro</h2>
                  <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-widest">Edição de login, senha e identificação</p>
                </div>
              </div>

              <div className="bg-zinc-900 border border-zinc-800 p-10 rounded-[3rem] space-y-10">
                <div className="flex flex-col items-center">
                   <div className="w-32 h-32 bg-black border-2 border-green-500/20 rounded-full relative group overflow-hidden mb-6 shadow-glow">
                      {profileEdit.avatarUrl ? <img src={profileEdit.avatarUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-zinc-800"><UserCircle size={60} /></div>}
                      <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center transition-opacity cursor-pointer">
                        <Camera size={24} className="text-green-500" />
                        <span className="text-[8px] font-black uppercase text-white mt-1">Alterar Foto</span>
                      </div>
                      <input type="url" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => setProfileEdit({...profileEdit, avatarUrl: e.target.value})} placeholder="URL da foto" />
                   </div>
                   <p className="text-[9px] font-black uppercase text-zinc-600 tracking-widest">Foto de Identificação Operacional</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-zinc-500 ml-2">Nome de Exibição</label>
                    <input type="text" value={profileEdit.name} onChange={e => setProfileEdit({...profileEdit, name: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-sm focus:border-green-500/40" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-zinc-500 ml-2">Identificador (Login)</label>
                    <input type="text" value={profileEdit.username} onChange={e => setProfileEdit({...profileEdit, username: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-sm focus:border-green-500/40" />
                  </div>
                  <div className="space-y-2 sm:col-span-2">
                    <label className="text-[10px] font-black uppercase text-zinc-500 ml-2">Alterar Senha HPS</label>
                    <div className="relative">
                      <KeyRound className="absolute left-6 top-1/2 -translate-y-1/2 text-green-500" size={18} />
                      <input type="password" value={profileEdit.password} onChange={e => setProfileEdit({...profileEdit, password: e.target.value})} className="w-full pl-14 pr-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black text-sm focus:border-green-500/40" placeholder="NOVA SENHA" />
                    </div>
                  </div>
                </div>

                <button onClick={updateProfile} className="w-full py-6 bg-green-500 text-black font-black uppercase text-sm rounded-[2rem] hover:bg-green-400 shadow-glow transition-all flex items-center justify-center gap-3">
                  <Save size={20} /> Salvar Alterações
                </button>
              </div>
            </div>
          )}

          {activeTab === 'users' && isAdmin && (
            <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 space-y-8">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Base de Usuários</h2>
                  <p className="text-zinc-500 font-bold uppercase text-[9px] tracking-widest">Controle mestre de permissões e acessos HPS</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {users.map((u, idx) => (
                  <div key={u.id} className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] relative group">
                    <div className="flex items-center gap-4 mb-6">
                        <div className="w-16 h-16 bg-black rounded-2xl overflow-hidden border border-zinc-800 shadow-glow">
                            {u.avatarUrl ? <img src={u.avatarUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-zinc-800"><UserCircle size={32} /></div>}
                        </div>
                        <div>
                            <h4 className="text-lg font-black text-white uppercase italic leading-tight">{u.name}</h4>
                            <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest">{u.role === UserRole.STOCKIST ? 'Gestão Total' : 'Oficina'}</p>
                        </div>
                    </div>

                    <div className="space-y-4 pt-6 border-t border-zinc-800">
                      <div>
                        <p className="text-[8px] font-black text-zinc-600 uppercase mb-1">Username</p>
                        <p className="text-xs font-bold text-white uppercase">{u.username}</p>
                      </div>
                      <div>
                        <p className="text-[8px] font-black text-zinc-600 uppercase mb-1">Chave de Acesso</p>
                        <p className="text-xs font-bold text-green-500">••••••••</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="animate-in fade-in duration-500">
              <div className="flex items-center gap-4 mb-10">
                <div className="p-5 bg-green-500 rounded-3xl text-black shadow-glow"><History size={32} /></div>
                <div>
                  <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">{isAdmin ? 'Log HPS' : 'Meu Espelho'}</h2>
                  <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-widest">Rastreabilidade integral de peças</p>
                </div>
              </div>
              <TransactionHistory transactions={displayHistory} />
            </div>
          )}

          {activeTab === 'team' && isAdmin && (
            <div className="animate-in fade-in duration-500 space-y-10">
              <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem] flex items-center justify-between">
                <div className="flex items-center gap-6">
                  <div className="p-5 bg-green-500 text-black rounded-[2rem] shadow-glow"><Users size={32} /></div>
                  <div>
                    <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Relatórios Profissionais</h2>
                    <p className="text-zinc-500 font-bold uppercase text-[9px] tracking-widest">Auditoria por técnico</p>
                  </div>
                </div>
                <select className="bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black uppercase text-xs outline-none focus:ring-2 focus:ring-green-500/20" value={selectedMechanic} onChange={e => setSelectedMechanic(e.target.value)}>
                  {users.filter(u => u.role === UserRole.MECHANIC).map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                </select>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <div className="lg:col-span-1 space-y-6">
                  <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] text-center">
                    <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2">Total Extraído</p>
                    <p className="text-6xl font-black text-green-500 italic">{displayHistory.length}</p>
                  </div>
                  <button onClick={() => setIsAssigningModalOpen(true)} className="w-full p-6 bg-green-500 text-black rounded-[1.8rem] font-black uppercase text-xs hover:bg-green-400 transition-all flex items-center justify-center gap-2 shadow-glow">
                    <PlusCircle size={20} /> Lançar para {selectedMechanic.split(' ')[0]}
                  </button>
                </div>
                <div className="lg:col-span-3">
                  <TransactionHistory transactions={displayHistory} />
                </div>
              </div>
            </div>
          )}

          {activeTab === 'reports' && (
            <div className="animate-in fade-in duration-500 space-y-10">
              <div className="flex justify-between items-center bg-zinc-900 p-10 rounded-[3rem] border border-zinc-800">
                <div>
                  <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Relatório HPS</h2>
                  <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-widest">Status atual do patrimônio móvel</p>
                </div>
                <button onClick={() => window.print()} className="px-8 py-4 bg-white text-black rounded-2xl font-black uppercase text-[10px] flex items-center gap-2 hover:bg-zinc-200 transition-all shadow-xl"><Printer size={18} /> Imprimir</button>
              </div>

              <div className="bg-zinc-900 rounded-[3rem] border border-zinc-800 overflow-hidden shadow-2xl overflow-x-auto">
                <table className="w-full text-left min-w-[800px]">
                  <thead>
                    <tr className="bg-zinc-800/40 border-b border-zinc-800">
                      <th className="px-8 py-6 text-[10px] font-black uppercase text-zinc-500 tracking-widest">Componente</th>
                      <th className="px-8 py-6 text-[10px] font-black uppercase text-zinc-500 tracking-widest text-center">Saldo</th>
                      {isAdmin && <th className="px-8 py-6 text-[10px] font-black uppercase text-zinc-500 tracking-widest text-right">Unitário</th>}
                      {isAdmin && <th className="px-8 py-6 text-[10px] font-black uppercase text-zinc-500 tracking-widest text-right">Acumulado</th>}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-800">
                    {items.map(item => (
                      <tr key={item.id} className="hover:bg-zinc-800/20 transition-colors">
                        <td className="px-8 py-6">
                          <p className="font-black text-white uppercase italic">{item.name}</p>
                          <p className="text-[9px] text-zinc-600 font-black">PN: {item.partNumber}</p>
                        </td>
                        <td className="px-8 py-6 text-center font-black text-xl text-green-500">{item.quantity}</td>
                        {isAdmin && <td className="px-8 py-6 text-right font-bold text-zinc-500 text-sm">R$ {item.value.toLocaleString('pt-BR')}</td>}
                        {isAdmin && <td className="px-8 py-6 text-right font-black text-white text-xl">R$ {(item.value * item.quantity).toLocaleString('pt-BR')}</td>}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODAL: LANÇAMENTO DIRETO (EQUIPE) */}
      {isAssigningModalOpen && isAdmin && (
        <div className="fixed inset-0 bg-black/98 z-[100] flex items-center justify-center p-4 backdrop-blur-xl animate-in zoom-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3rem] w-full max-w-2xl shadow-glow overflow-hidden">
            <div className="p-10 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/50">
              <div>
                <h3 className="text-2xl font-black text-white uppercase italic tracking-tighter">Lançamento de Saída</h3>
                <p className="text-green-500 font-bold text-[10px] uppercase tracking-widest mt-1">Destinar insumos para: {selectedMechanic}</p>
              </div>
              <button onClick={() => setIsAssigningModalOpen(false)} className="p-4 bg-zinc-800 rounded-2xl hover:text-white transition-all"><X size={24} /></button>
            </div>
            <div className="p-10 space-y-8">
              {!selectedItemToAssign ? (
                <div className="space-y-6">
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500" size={18} />
                    <input type="text" placeholder="Localizar item..." className="w-full pl-12 pr-4 py-5 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-bold" value={assignSearch} onChange={e => setAssignSearch(e.target.value)} autoFocus />
                  </div>
                  <div className="max-h-[300px] overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                    {items.filter(i => i.name.toLowerCase().includes(assignSearch.toLowerCase())).map(item => (
                      <button key={item.id} onClick={() => setSelectedItemToAssign(item)} className="w-full p-5 bg-zinc-800/40 border border-zinc-800 rounded-2xl flex justify-between items-center group hover:border-green-500/40 transition-all">
                        <div className="text-left">
                          <p className="font-black text-white uppercase italic text-sm group-hover:text-green-400">{item.name}</p>
                          <p className="text-[9px] text-zinc-600 font-black">PN: {item.partNumber}</p>
                        </div>
                        <p className="text-lg font-black text-zinc-400">{item.quantity} UN</p>
                      </button>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="space-y-10">
                  <div className="bg-green-500/5 p-8 rounded-[2rem] border border-green-500/20">
                    <p className="text-[10px] font-black text-green-500 uppercase tracking-widest mb-1">Item Selecionado</p>
                    <h4 className="text-2xl font-black text-white uppercase italic">{selectedItemToAssign.name}</h4>
                    <p className="text-xs text-zinc-500 font-bold uppercase">{selectedItemToAssign.partNumber}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">Quantidade</label>
                      <input type="number" min="1" max={selectedItemToAssign.quantity} className="w-full px-8 py-6 bg-black border border-zinc-800 rounded-[1.5rem] text-4xl font-black text-green-500 text-center outline-none focus:ring-2 focus:ring-green-500/40" value={assignQty} onChange={e => setAssignQty(parseInt(e.target.value) || 1)} />
                    </div>
                    <div className="flex flex-col justify-end gap-3">
                      <button onClick={handleQuickAssign} className="w-full p-6 bg-green-500 text-black font-black uppercase text-xs rounded-3xl hover:bg-green-400 transition-all shadow-glow">Confirmar Retirada</button>
                      <button onClick={() => setSelectedItemToAssign(null)} className="w-full p-6 bg-zinc-800 text-zinc-500 font-black uppercase text-xs rounded-3xl hover:bg-zinc-700 transition-all">Cancelar</button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* MODAL: NOVO ITEM (ADMIN) */}
      {isAddingItem && isAdmin && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4 backdrop-blur-md overflow-y-auto">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3rem] w-full max-w-2xl shadow-glow my-auto animate-in zoom-in duration-300">
            <div className="p-10 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/50">
              <h3 className="text-3xl font-black text-white uppercase italic tracking-tighter">Novo Componente</h3>
              <button onClick={() => setIsAddingItem(false)} className="p-4 bg-zinc-800 rounded-2xl hover:text-white transition-all"><X size={24} /></button>
            </div>
            <form onSubmit={handleAddItem} className="p-10 space-y-8">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest ml-2">Nome</label>
                  <input required type="text" className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none text-white font-black uppercase text-sm" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest ml-2">Part Number</label>
                  <input required type="text" className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none text-white font-black uppercase text-sm" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest ml-2">Unitário (R$)</label>
                  <input required type="number" step="0.01" className="w-full px-6 py-4 bg-green-500/5 border-2 border-green-500/20 text-green-500 rounded-2xl outline-none font-black text-lg" value={formData.value} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest ml-2">Saldo Inicial</label>
                  <input required type="number" className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none text-white font-black text-lg" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest ml-2">URL da Imagem</label>
                <input type="url" className="w-full px-6 py-4 bg-zinc-800 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none text-white font-bold text-xs" value={formData.imageUrl} onChange={e => setFormData({...formData, imageUrl: e.target.value})} placeholder="https://..." />
              </div>
              <button type="submit" className="w-full py-6 bg-green-500 text-black font-black uppercase text-sm rounded-3xl hover:bg-green-400 transition-all shadow-glow">Concluir Registro</button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL: MOVIMENTAÇÃO (ADMIN) */}
      {movementModal.isOpen && isAdmin && (
        <div className="fixed inset-0 bg-black/98 z-[100] flex items-center justify-center p-4 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3rem] w-full max-w-lg shadow-glow overflow-hidden">
            <div className={`p-10 flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
              <div className="p-5 rounded-3xl bg-black/10">
                {movementModal.type === TransactionType.IN ? <Plus size={36} /> : <LogOut size={36} className="rotate-180" />}
              </div>
              <div>
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada HPS' : 'Saída HPS'}</h3>
                <p className="font-black uppercase tracking-widest text-[10px] opacity-70">{items.find(i => i.id === movementModal.itemId)?.name}</p>
              </div>
            </div>
            <div className="p-10 space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">Quantidade</label>
                <input type="number" min="1" className="w-full px-8 py-8 bg-zinc-950 border border-zinc-800 rounded-[2rem] text-5xl font-black focus:ring-4 focus:ring-green-500/10 outline-none text-center text-green-500" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
              </div>
              <div className="space-y-4">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">{movementModal.type === TransactionType.OUT ? 'Mecânico Destinatário' : 'Notas Operacionais'}</label>
                {movementModal.type === TransactionType.OUT ? (
                  <select className="w-full px-6 py-4 bg-zinc-800 rounded-2xl text-white font-black text-sm uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                    <option value="">SELECIONE O TÉCNICO...</option>
                    {users.filter(u => u.role === UserRole.MECHANIC).map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                  </select>
                ) : (
                  <textarea value={movementNotes} onChange={e => setMovementNotes(e.target.value)} className="w-full px-6 py-4 bg-zinc-800 rounded-2xl text-white font-bold text-sm outline-none" rows={2} placeholder="Descreva o motivo..." />
                )}
              </div>
              <div className="flex gap-4">
                <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-5 bg-zinc-800 text-zinc-500 font-black rounded-2xl uppercase text-[10px]">Sair</button>
                <button onClick={processMovement} className={`flex-[2] py-5 font-black rounded-2xl uppercase text-xs shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar Movimento</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}

      {/* MODAL: IMAGE VIEW */}
      {viewingImage && (
        <div className="fixed inset-0 bg-black/98 z-[120] flex items-center justify-center p-4 backdrop-blur-3xl animate-in fade-in duration-300">
           <div className="relative max-w-4xl w-full bg-zinc-900 border border-zinc-800 rounded-[3rem] overflow-hidden">
             <button onClick={() => setViewingImage(null)} className="absolute top-6 right-6 p-4 bg-black/50 hover:bg-red-500 text-white rounded-2xl transition-all z-10"><X size={24} /></button>
             <div className="p-10">
               <h3 className="text-xl font-black text-white uppercase italic tracking-tighter mb-6 flex items-center gap-3"><ImageIcon className="text-amber-500" /> {viewingImage.title}</h3>
               <div className="rounded-[2rem] overflow-hidden border border-zinc-800 bg-black flex items-center justify-center min-h-[400px]">
                 <img src={viewingImage.url} className="max-w-full max-h-[70vh] object-contain" />
               </div>
             </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  STOCKIST = 'STOCKIST', // Acesso Total
  MECHANIC = 'MECHANIC'  // Acesso Limitado
}

export interface User {
  id: string;
  username: string;
  password?: string;
  email?: string;       // Novo campo para recuperação
  name: string;
  role: UserRole;
  avatarUrl?: string;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  minQuantity: number;
  qrGroup: string;
  entryDate: string;
  description?: string;
  imageUrl?: string;
  applicationImageUrl?: string;
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string;
  notes?: string;
}

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  Trash2, UserCircle, Zap, DollarSign, Wrench, FileText, 
  Printer, AlertTriangle, ClipboardList, UserCheck, ChevronRight, 
  Users, Download, PlusCircle, X, ExternalLink, ImageIcon, Eye, 
  Maximize2, Lock, KeyRound, ShieldCheck, UserPlus, Camera, Edit3, Save,
  RefreshCcw, Mail
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

// Configuração de Usuários Iniciais (Database Mock)
const INITIAL_USERS: User[] = [
  { id: 'a1', username: 'GUILHERME', email: 'guilherme@hps.com', password: '123', name: 'Guilherme', role: UserRole.STOCKIST },
  { id: 'a2', username: 'ANNA JULYA', email: 'anna@hps.com', password: '123', name: 'Anna Julya', role: UserRole.STOCKIST },
  { id: 'a3', username: 'JULIANA', email: 'juliana@hps.com', password: '123', name: 'Juliana', role: UserRole.STOCKIST },
  { id: 'a4', username: 'DAVISON', email: 'davison@hps.com', password: '123', name: 'Davison', role: UserRole.STOCKIST },
  { id: 'm1', username: 'JOAO PAULO', email: 'joao@hps.com', password: '0123', name: 'João Paulo', role: UserRole.MECHANIC },
  { id: 'm2', username: 'ROMULO', email: 'romulo@hps.com', password: '0123', name: 'Romulo', role: UserRole.MECHANIC },
  { id: 'm3', username: 'LEONARDO', email: 'leo@hps.com', password: '0123', name: 'Leonardo', role: UserRole.MECHANIC },
  { id: 'm4', username: 'ANSELMO', email: 'anselmo@hps.com', password: '0123', name: 'Anselmo', role: UserRole.MECHANIC },
  { id: 'm5', username: 'DAVID', email: 'david@hps.com', password: '0123', name: 'David', role: UserRole.MECHANIC },
];

const QR_GROUPS = [
  "QR 1 - FREIOS", "QR 2 - SUSPENSÃO", "QR 3 - MOTOR", 
  "QR 4 - TRANSMISSÃO", "QR 5 - ELÉTRICA", "QR 6 - ACESSÓRIOS"
];

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'reports' | 'restock' | 'team' | 'users' | 'profile';
type AuthView = 'login' | 'signup' | 'forgot' | 'reset';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg', className?: string }> = ({ size = 'md', className = "" }) => {
  const dimensions = { sm: { width: '80px' }, md: { width: '120px' }, lg: { width: '200px' } };
  return (
    <div className={`flex flex-col items-center ${className} select-none`}>
      <img src="logo.png" alt="HPS CONTROL" style={dimensions[size]} className="drop-shadow-[0_0_15px_rgba(0,255,0,0.3)] object-contain"
        onError={(e) => { e.currentTarget.style.display = 'none'; }} />
    </div>
  );
};

const App: React.FC = () => {
  // Database State (Persistência)
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);

  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authView, setAuthView] = useState<AuthView>('login');

  // Auth Forms
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', email: '', password: '', role: UserRole.MECHANIC, avatarUrl: '' });
  const [forgotForm, setForgotForm] = useState({ email: '' });
  const [resetForm, setResetForm] = useState({ password: '', confirmPassword: '' });
  const [resetTargetUser, setResetTargetUser] = useState<User | null>(null);
  const [loginError, setLoginError] = useState('');

  // UI State
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [selectedMechanic, setSelectedMechanic] = useState<string>('');
  const [viewingImage, setViewingImage] = useState<{url: string, title: string} | null>(null);

  // Profile State
  const [profileEdit, setProfileEdit] = useState({ name: '', username: '', email: '', password: '', avatarUrl: '' });

  // Movement Modals
  const [isAssigningModalOpen, setIsAssigningModalOpen] = useState(false);
  const [assignSearch, setAssignSearch] = useState('');
  const [assignQty, setAssignQty] = useState(1);
  const [selectedItemToAssign, setSelectedItemToAssign] = useState<InventoryItem | null>(null);
  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [movementNotes, setMovementNotes] = useState('');
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    qrGroup: QR_GROUPS[0], description: '', imageUrl: '', applicationImageUrl: ''
  });

  // Database Initialization (LocalStorage)
  useEffect(() => {
    const savedItems = localStorage.getItem('hps_items');
    const savedHistory = localStorage.getItem('hps_history');
    const savedUsers = localStorage.getItem('hps_users');

    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));

    if (savedUsers) {
      setUsers(JSON.parse(savedUsers));
    } else {
      setUsers(INITIAL_USERS);
      localStorage.setItem('hps_users', JSON.stringify(INITIAL_USERS));
    }
  }, []);

  // Database Sync
  useEffect(() => {
    localStorage.setItem('hps_items', JSON.stringify(items));
    localStorage.setItem('hps_history', JSON.stringify(history));
    localStorage.setItem('hps_users', JSON.stringify(users));
  }, [items, history, users]);

  // Sync profile editing
  useEffect(() => {
    if (currentUser) {
      setProfileEdit({
        name: currentUser.name,
        username: currentUser.username,
        email: currentUser.email || '',
        password: currentUser.password || '',
        avatarUrl: currentUser.avatarUrl || ''
      });
    }
  }, [currentUser]);

  // Auth Handlers
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toUpperCase() === loginForm.username.toUpperCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
      setLoginError('');
      setActiveTab('dashboard');
      if (user.role === UserRole.MECHANIC) setSelectedMechanic(user.name);
      else setSelectedMechanic(users.find(u => u.role === UserRole.MECHANIC)?.name || '');
    } else {
      setLoginError('Falha na autenticação HPS. Verifique os dados.');
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toUpperCase() === signupForm.username.toUpperCase())) {
      setLoginError('Este usuário já está registrado no banco de dados.');
      return;
    }
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      ...signupForm
    };
    setUsers(prev => [...prev, newUser]);
    setAuthView('login');
    setLoginError('Cadastro realizado com sucesso! Faça login.');
    setLoginForm({ username: signupForm.username, password: signupForm.password });
  };

  const handleForgotFlow = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.email?.toLowerCase() === forgotForm.email.toLowerCase());
    if (user) {
      setResetTargetUser(user);
      setAuthView('reset');
      setLoginError('');
    } else {
      setLoginError('E-mail não localizado na base de dados HPS.');
    }
  };

  const handlePasswordReset = (e: React.FormEvent) => {
    e.preventDefault();
    if (resetForm.password !== resetForm.confirmPassword) {
      setLoginError('As senhas digitadas não coincidem.');
      return;
    }
    if (!resetTargetUser) return;

    const updatedUsers = users.map(u => 
      u.id === resetTargetUser.id ? { ...u, password: resetForm.password } : u
    );

    setUsers(updatedUsers);
    setAuthView('login');
    setLoginError('Senha atualizada! Utilize sua nova chave de acesso.');
    setLoginForm({ username: resetTargetUser.username, password: resetForm.password });
    setResetForm({ password: '', confirmPassword: '' });
    setResetTargetUser(null);
  };

  const updateProfile = () => {
    if (!currentUser) return;
    const updatedUsers = users.map(u => u.id === currentUser.id ? { ...u, ...profileEdit } : u);
    setUsers(updatedUsers);
    setCurrentUser({ ...currentUser, ...profileEdit });
    alert('Base de dados atualizada: Perfil gravado com sucesso!');
  };

  // Stock Handlers
  const fetchInsights = useCallback(async () => {
    if (loadingInsights || currentUser?.role !== UserRole.STOCKIST) return;
    setLoadingInsights(true);
    try {
      const result = await getStockInsights(items, history);
      setInsights(result || "Auditoria concluída.");
    } catch (error) {
      setInsights("Erro na conexão com IA.");
    } finally {
      setLoadingInsights(false);
    }
  }, [items, history, loadingInsights, currentUser]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentUser?.role !== UserRole.STOCKIST) return;
    const newItem: InventoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      ...formData,
      entryDate: new Date().toISOString()
    };
    setItems(prev => [...prev, newItem]);
    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      itemId: newItem.id, itemName: newItem.name,
      userId: currentUser.id, userName: currentUser.name,
      type: TransactionType.IN, quantity: newItem.quantity,
      date: new Date().toISOString(), recipientName: 'Estoque Central', notes: 'Entrada via Registro Novo'
    }]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, qrGroup: QR_GROUPS[0], description: '', imageUrl: '', applicationImageUrl: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId || currentUser?.role !== UserRole.STOCKIST) return;
    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;
    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Quantidade insuficiente em estoque!");
      return;
    }
    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);
    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      itemId: currentItem.id, itemName: currentItem.name,
      userId: currentUser.id, userName: currentUser.name,
      type: movementModal.type, quantity: movementQty,
      date: new Date().toISOString(), recipientName: recipient || 'HPS', notes: movementNotes
    }]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setMovementNotes('');
  };

  const handleQuickAssign = () => {
    if (!selectedItemToAssign || assignQty < 1 || currentUser?.role !== UserRole.STOCKIST) return;
    if (selectedItemToAssign.quantity < assignQty) { alert("Saldo insuficiente!"); return; }
    const itemIndex = items.findIndex(i => i.id === selectedItemToAssign.id);
    const updatedItems = [...items];
    updatedItems[itemIndex].quantity -= assignQty;
    setItems(updatedItems);
    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9), itemId: selectedItemToAssign.id, itemName: selectedItemToAssign.name,
      userId: currentUser.id, userName: currentUser.name, type: TransactionType.OUT, quantity: assignQty,
      date: new Date().toISOString(), recipientName: selectedMechanic, notes: `Destinado para: ${selectedMechanic}`
    }]);
    setIsAssigningModalOpen(false); setSelectedItemToAssign(null); setAssignQty(1); setAssignSearch('');
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setActiveTab('inventory');
      setSearchTerm(item.partNumber);
      if (currentUser?.role === UserRole.STOCKIST) {
        setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
      }
    } else {
      alert("QR Code não registrado no banco HPS.");
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);
  const criticalItems = items.filter(i => i.quantity <= i.minQuantity);
  const displayHistory = history.filter(h => {
    if (currentUser?.role === UserRole.MECHANIC) return h.recipientName === currentUser.name;
    if (activeTab === 'team') return h.recipientName === selectedMechanic;
    return true;
  });

  // AUTH SCREENS
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
        <div className="bg-zinc-900/60 backdrop-blur-2xl p-8 sm:p-10 rounded-[3rem] border border-green-500/20 w-full max-w-md shadow-2xl animate-in fade-in duration-700">
          <div className="flex flex-col items-center mb-8">
            <HPSLogo size="lg" className="mb-4" />
            <h1 className="text-lg font-black tracking-[0.3em] text-white text-center uppercase italic">
              {authView === 'login' ? 'Acesso HPS' : authView === 'signup' ? 'Novo Cadastro' : authView === 'forgot' ? 'Recuperação' : 'Nova Chave'}
            </h1>
          </div>

          {authView === 'login' && (
            <form onSubmit={handleLogin} className="space-y-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-zinc-500 ml-4">Usuário</label>
                <div className="relative">
                  <UserCircle className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                  <input required type="text" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})}
                    className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black uppercase text-sm focus:ring-2 focus:ring-green-500/30" placeholder="LOGIN" />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-zinc-500 ml-4">Senha</label>
                <div className="relative">
                  <KeyRound className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                  <input required type="password" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})}
                    className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black text-sm focus:ring-2 focus:ring-green-500/30" placeholder="••••••••" />
                </div>
              </div>
              <div className="flex justify-between items-center px-4">
                <button type="button" onClick={() => {setAuthView('forgot'); setLoginError('');}} className="text-[9px] font-black uppercase text-zinc-600 hover:text-white transition-colors">Esqueci a senha</button>
                <button type="button" onClick={() => {setAuthView('signup'); setLoginError('');}} className="text-[9px] font-black uppercase text-green-600 hover:text-green-400 transition-colors">Primeiro acesso</button>
              </div>
              {loginError && <p className="text-red-500 text-[10px] font-black uppercase text-center animate-pulse">{loginError}</p>}
              <button type="submit" className="w-full py-6 bg-green-500 text-black rounded-[2rem] font-black uppercase text-sm hover:bg-green-400 shadow-glow flex items-center justify-center gap-3">
                <ShieldCheck size={20} /> Entrar
              </button>
            </form>
          )}

          {authView === 'signup' && (
            <form onSubmit={handleSignup} className="space-y-4">
              <div className="flex justify-center mb-4">
                <div className="w-24 h-24 bg-black border-2 border-dashed border-zinc-800 rounded-full flex flex-col items-center justify-center text-zinc-700 hover:text-green-500 hover:border-green-500 transition-all cursor-pointer overflow-hidden relative group shadow-glow">
                  {signupForm.avatarUrl ? <img src={signupForm.avatarUrl} className="w-full h-full object-cover" /> : <><Camera size={24} /><span className="text-[8px] font-black uppercase mt-1">Sua Foto</span></>}
                  <input type="url" placeholder="URL da foto" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => setSignupForm({...signupForm, avatarUrl: e.target.value})} />
                </div>
              </div>
              <input required type="text" placeholder="NOME COMPLETO" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-xs" />
              <div className="grid grid-cols-2 gap-4">
                <input required type="text" placeholder="USUÁRIO" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-xs" />
                <input required type="password" placeholder="SENHA" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black text-xs" />
              </div>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600" size={14} />
                <input required type="email" placeholder="E-MAIL CORPORATIVO" value={signupForm.email} onChange={e => setSignupForm({...signupForm, email: e.target.value})} className="w-full pl-12 pr-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black text-xs" />
              </div>
              <select className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-xs" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
                <option value={UserRole.MECHANIC}>Oficina / Mecânico</option>
                <option value={UserRole.STOCKIST}>Gestão / Estoque</option>
              </select>
              <button type="submit" className="w-full py-5 bg-green-500 text-black rounded-[1.5rem] font-black uppercase text-xs hover:bg-green-400 mt-4">Registrar no Banco</button>
              <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-500">Voltar</button>
            </form>
          )}

          {authView === 'forgot' && (
            <form onSubmit={handleForgotFlow} className="space-y-6">
              <p className="text-zinc-500 text-[10px] font-bold uppercase text-center px-4 leading-relaxed">Localize sua conta através do e-mail corporativo cadastrado para criar uma nova senha.</p>
              <div className="relative">
                <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-green-500" size={20} />
                <input required type="email" value={forgotForm.email} onChange={e => setForgotForm({email: e.target.value})}
                  className="w-full pl-14 pr-6 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black text-sm" placeholder="E-MAIL" />
              </div>
              {loginError && <p className="text-red-500 text-[10px] font-black uppercase text-center">{loginError}</p>}
              <button type="submit" className="w-full py-6 bg-white text-black rounded-[2rem] font-black uppercase text-sm hover:bg-zinc-200">Validar E-mail</button>
              <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-500">Cancelar</button>
            </form>
          )}

          {authView === 'reset' && (
            <form onSubmit={handlePasswordReset} className="space-y-6">
              <p className="text-zinc-500 text-[10px] font-bold uppercase text-center px-4 leading-relaxed italic">
                Gravando nova senha para: <span className="text-green-500 font-black">{resetTargetUser?.name}</span>
              </p>
              <div className="space-y-4">
                <input required type="password" value={resetForm.password} onChange={e => setResetForm({...resetForm, password: e.target.value})}
                  className="w-full px-8 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black text-sm" placeholder="NOVA SENHA" />
                <input required type="password" value={resetForm.confirmPassword} onChange={e => setResetForm({...resetForm, confirmPassword: e.target.value})}
                  className="w-full px-8 py-5 bg-black border border-zinc-800 rounded-3xl outline-none text-white font-black text-sm" placeholder="CONFIRMAR" />
              </div>
              {loginError && <p className="text-red-500 text-[10px] font-black uppercase text-center">{loginError}</p>}
              <button type="submit" className="w-full py-6 bg-green-500 text-black rounded-[2rem] font-black uppercase text-sm hover:bg-green-400 shadow-glow">Atualizar Banco</button>
            </form>
          )}

          <p className="text-center text-zinc-700 text-[8px] mt-10 font-bold uppercase tracking-widest italic">High Performance SSV Database</p>
        </div>
      </div>
    );
  }

  const isAdmin = currentUser.role === UserRole.STOCKIST;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 font-sans">
      {/* Sidebar Navigation */}
      <aside className="w-full md:w-64 bg-black p-6 flex flex-col hidden md:flex border-r border-green-500/10 shadow-2xl z-20 print:hidden shrink-0">
        <div className="mb-10 flex justify-center"><HPSLogo size="sm" /></div>
        <nav className="flex-1 space-y-1.5">
          <button onClick={() => setActiveTab('dashboard')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'dashboard' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
            <TrendingUp size={18} /> {isAdmin ? 'Painel Geral' : 'Meu Espelho'}
          </button>
          {isAdmin && (
            <>
              <button onClick={() => setActiveTab('team')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'team' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
                <Users size={18} /> Gestão Equipe
              </button>
              <button onClick={() => setActiveTab('users')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'users' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
                <Lock size={18} /> Base Usuários
              </button>
            </>
          )}
          <button onClick={() => setActiveTab('reports')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'reports' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
            <FileText size={18} /> Inventário
          </button>
          <button onClick={() => setActiveTab('history')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all font-black uppercase text-[10px] tracking-wider ${activeTab === 'history' ? 'bg-green-500 text-black' : 'text-zinc-400 hover:bg-zinc-900'}`}>
            <History size={18} /> Log Atividades
          </button>
        </nav>
        <div className="mt-auto pt-6 border-t border-zinc-800">
          <button onClick={() => setActiveTab('profile')} className={`w-full flex items-center gap-3 p-4 rounded-2xl mb-4 transition-all border ${activeTab === 'profile' ? 'bg-green-500/10 border-green-500 shadow-glow' : 'bg-zinc-900/50 border-zinc-800'}`}>
            <div className="w-10 h-10 bg-zinc-800 rounded-xl flex items-center justify-center text-green-500 font-black shadow-glow overflow-hidden">
