                <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-5 bg-zinc-800 text-zinc-500 font-black rounded-2xl uppercase text-[10px]">Fechar</button>
                <button onClick={processMovement} className={`flex-[2] py-5 font-black rounded-2xl uppercase text-xs shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar Movimento</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

