const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authView, setAuthView] = useState<AuthView>('login');

  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', email: '', password: '', role: UserRole.MECHANIC, avatarUrl: '' });
  const [forgotForm, setForgotForm] = useState({ email: '' });
  const [resetForm, setResetForm] = useState({ password: '', confirmPassword: '' });
  const [resetTargetUser, setResetTargetUser] = useState<User | null>(null);
  const [loginError, setLoginError] = useState('');

  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [selectedMechanic, setSelectedMechanic] = useState<string>('');
  const [viewingImage, setViewingImage] = useState<{url: string, title: string} | null>(null);

  const [profileEdit, setProfileEdit] = useState({ name: '', username: '', email: '', password: '', avatarUrl: '' });

  const [isAssigningModalOpen, setIsAssigningModalOpen] = useState(false);
  const [assignSearch, setAssignSearch] = useState('');
  const [assignQty, setAssignQty] = useState(1);
  const [selectedItemToAssign, setSelectedItemToAssign] = useState<InventoryItem | null>(null);
  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [movementNotes, setMovementNotes] = useState('');
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    qrGroup: QR_GROUPS[0], description: '', imageUrl: '', applicationImageUrl: ''
  });

  useEffect(() => {
    const savedItems = localStorage.getItem('hps_items');
    const savedHistory = localStorage.getItem('hps_history');
    const savedUsers = localStorage.getItem('hps_users');
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedUsers) setUsers(JSON.parse(savedUsers));
    else {
      setUsers(INITIAL_USERS);
      localStorage.setItem('hps_users', JSON.stringify(INITIAL_USERS));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_items', JSON.stringify(items));
    localStorage.setItem('hps_history', JSON.stringify(history));
    localStorage.setItem('hps_users', JSON.stringify(users));
  }, [items, history, users]);

  useEffect(() => {
    if (currentUser) {
      setProfileEdit({
        name: currentUser.name,
        username: currentUser.username,
        email: currentUser.email || '',
        password: currentUser.password || '',
        avatarUrl: currentUser.avatarUrl || ''
      });
    }
  }, [currentUser]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toUpperCase() === loginForm.username.toUpperCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
      setLoginError('');
      setActiveTab('dashboard');
      if (user.role === UserRole.MECHANIC) setSelectedMechanic(user.name);
      else setSelectedMechanic(users.find(u => u.role === UserRole.MECHANIC)?.name || '');
    } else {
      setLoginError('Falha na autenticação HPS.');
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toUpperCase() === signupForm.username.toUpperCase())) {
      setLoginError('Usuário já existe.');
      return;
    }
    const newUser: User = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers(prev => [...prev, newUser]);
    setAuthView('login');
    setLoginError('Cadastro realizado! Logue abaixo.');
    setLoginForm({ username: signupForm.username, password: signupForm.password });
  };

  const handleForgotFlow = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.email?.toLowerCase() === forgotForm.email.toLowerCase());
    if (user) {
      setResetTargetUser(user);
      setAuthView('reset');
      setLoginError('');
    } else {
      setLoginError('E-mail não localizado.');
    }
  };

  const handlePasswordReset = (e: React.FormEvent) => {
    e.preventDefault();
    if (resetForm.password !== resetForm.confirmPassword) {
      setLoginError('Senhas não coincidem.');
      return;
    }
    if (!resetTargetUser) return;
    const updatedUsers = users.map(u => u.id === resetTargetUser.id ? { ...u, password: resetForm.password } : u);
    setUsers(updatedUsers);
    setAuthView('login');
    setLoginError('Senha atualizada!');
    setLoginForm({ username: resetTargetUser.username, password: resetForm.password });
    setResetForm({ password: '', confirmPassword: '' });
    setResetTargetUser(null);
  };

  const updateProfile = () => {
    if (!currentUser) return;
    const updatedUsers = users.map(u => u.id === currentUser.id ? { ...u, ...profileEdit } : u);
    setUsers(updatedUsers);
    setCurrentUser({ ...currentUser, ...profileEdit });
    alert('Perfil atualizado!');
  };

  const fetchInsights = useCallback(async () => {
    if (loadingInsights || currentUser?.role !== UserRole.STOCKIST) return;
    setLoadingInsights(true);
    try {
      const result = await getStockInsights(items, history);
      setInsights(result || "Insight gerado.");
    } catch (error) {
      setInsights("Erro IA.");
    } finally {
      setLoadingInsights(false);
    }
  }, [items, history, loadingInsights, currentUser]);

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentUser?.role !== UserRole.STOCKIST) return;
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    setItems(prev => [...prev, newItem]);
    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser.id, userName: currentUser.name,
      type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'Depósito', notes: 'Entrada Inicial'
    }]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, qrGroup: QR_GROUPS[0], description: '', imageUrl: '', applicationImageUrl: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId || currentUser?.role !== UserRole.STOCKIST) return;
    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;
    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Estoque insuficiente!");
      return;
    }
    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);
    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9), itemId: currentItem.id, itemName: currentItem.name, userId: currentUser.id, userName: currentUser.name,
      type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', notes: movementNotes
    }]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setMovementNotes('');
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setActiveTab('inventory');
      setSearchTerm(item.partNumber);
      if (currentUser?.role === UserRole.STOCKIST) setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else alert("Item não encontrado.");
  };

  const filteredItems = items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase()));
  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);
  const criticalItems = items.filter(i => i.quantity <= i.minQuantity);
  const displayHistory = history.filter(h => {
    if (currentUser?.role === UserRole.MECHANIC) return h.recipientName === currentUser.name;
    if (activeTab === 'team') return h.recipientName === selectedMechanic;
    return true;
  });

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-4">
        <div className="bg-zinc-900 border border-green-500/10 p-6 sm:p-10 rounded-[2.5rem] w-full max-w-sm shadow-2xl animate-in fade-in duration-500">
