              <input required type="password" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black text-xs focus:ring-1 focus:ring-green-500/30" placeholder="SENHA" />
              <div className="flex justify-between px-2">
                <button type="button" onClick={() => setAuthView('forgot')} className="text-[8px] font-black uppercase text-zinc-600">Esqueci a senha</button>
