              </div>
              {loginError && <p className="text-red-500 text-[9px] font-black uppercase text-center">{loginError}</p>}
              <button type="submit" className="w-full py-5 bg-green-500 text-black rounded-2xl font-black uppercase text-xs hover:bg-green-400 shadow-glow transition-all">Entrar no Sistema</button>
            </form>
          )}
          {authView === 'signup' && (
            <form onSubmit={handleSignup} className="space-y-3">
