                  <input type="url" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => setSignupForm({...signupForm, avatarUrl: e.target.value})} />
                </div>
              </div>
              <input required type="text" placeholder="NOME" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" />
              <input required type="text" placeholder="USUÁRIO" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" />
              <input required type="password" placeholder="SENHA" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black text-[10px]" />
              <input required type="email" placeholder="E-MAIL" value={signupForm.email} onChange={e => setSignupForm({...signupForm, email: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black text-[10px]" />
              <select className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
