             <div onClick={() => setActiveTab('profile')} className="w-8 h-8 rounded-full border border-green-500/30 overflow-hidden bg-zinc-800 flex items-center justify-center shadow-glow md:hidden">
                {currentUser.avatarUrl ? <img src={currentUser.avatarUrl} className="w-full h-full object-cover" /> : <UserCircle size={20} className="text-green-500" />}
