          <div className="flex items-center gap-2">
            <button onClick={() => setIsScanning(true)} className="p-2.5 bg-white text-black rounded-xl shadow-lg"><QrCode size={18} /></button>
            {isAdmin && <button onClick={() => setIsAddingItem(true)} className="p-2.5 bg-green-500 text-black rounded-xl shadow-lg"><Plus size={18} /></button>}
          </div>
        </header>

