              {/* Stats Grid */}
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl flex items-center gap-3">
                  <div className="p-2.5 bg-zinc-800 text-green-500 rounded-xl"><Package size={20} /></div>
                  <div><p className="text-[8px] text-zinc-500 uppercase font-black">Itens</p><p className="text-lg font-black">{items.length}</p></div>
                </div>
                <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl flex items-center gap-3">
                  <div className="p-2.5 bg-amber-500/10 text-amber-500 rounded-xl"><AlertTriangle size={20} /></div>
                  <div><p className="text-[8px] text-zinc-500 uppercase font-black">Baixos</p><p className="text-lg font-black">{criticalItems.length}</p></div>
                </div>
