                  <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl flex items-center gap-3 col-span-2 lg:col-span-1">
                    <div className="p-2.5 bg-green-500/10 text-green-500 rounded-xl"><DollarSign size={20} /></div>
                    <div><p className="text-[8px] text-zinc-500 uppercase font-black">Patrimônio</p><p className="text-sm font-black">R$ {totalStockValue.toLocaleString('pt-BR')}</p></div>
