                  <div className="space-y-1"><label className="text-[8px] font-black uppercase text-zinc-500 ml-2">Login</label><input type="text" value={profileEdit.username} onChange={e => setProfileEdit({...profileEdit, username: e.target.value})} className="w-full bg-black border border-zinc-800 px-5 py-3 rounded-xl text-white font-black uppercase text-[10px]" /></div>
