                <input required type="text" placeholder="P/N" className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <input required type="number" step="0.01" placeholder="VALOR R$" className="w-full px-5 py-3 bg-green-500/5 border border-green-500/10 text-green-500 rounded-xl font-black text-[10px]" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                <input required type="number" placeholder="SALDO" className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black text-[10px]" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
              </div>
              <input type="url" placeholder="URL DA IMAGEM" className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-bold text-[10px]" value={formData.imageUrl} onChange={e => setFormData({...formData, imageUrl: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl hover:bg-green-400 mt-4 shadow-glow">Gravar Componente</button>
            </form>
          </div>
        </div>
      )}

      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[100] flex items-center justify-center p-4 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] w-full max-w-xs shadow-glow overflow-hidden">
            <div className={`p-6 flex items-center gap-4 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
              <div className="p-3 rounded-xl bg-black/10">{movementModal.type === TransactionType.IN ? <Plus size={24} /> : <LogOut size={24} className="rotate-180" />}</div>
              <h3 className="text-lg font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Retirada'}</h3>
            </div>
            <div className="p-8 space-y-6">
              <input type="number" min="1" className="w-full px-6 py-6 bg-zinc-950 border border-zinc-800 rounded-2xl text-4xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
              {movementModal.type === TransactionType.OUT && (
                <select className="w-full px-4 py-3 bg-zinc-800 rounded-xl text-white font-black text-[10px] uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                  <option value="">PROFISSIONAL...</option>
                  {users.filter(u => u.role === UserRole.MECHANIC).map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                </select>
              )}
              <div className="flex gap-2">
                <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-4 bg-zinc-800 text-zinc-500 font-black rounded-xl uppercase text-[9px]">Sair</button>
                <button onClick={processMovement} className={`flex-[2] py-4 font-black rounded-xl uppercase text-[9px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-zinc-200 text-black'}`}>Confirmar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

