              <button type="button" onClick={() => setAuthView('login')} className="w-full text-[8px] font-black uppercase text-zinc-500 py-2">Voltar</button>
            </form>
          )}

          {authView === 'forgot' && (
            <form onSubmit={handleForgotFlow} className="space-y-4">
              <p className="text-zinc-500 text-[9px] font-bold uppercase text-center leading-relaxed">Enviaremos um link de recuperação para seu e-mail cadastrado.</p>
