              </div>
              {loginError && <p className="text-red-500 text-[9px] font-black uppercase text-center">{loginError}</p>}
              <button type="submit" className="w-full py-5 bg-white text-black rounded-2xl font-black uppercase text-xs shadow-glow">Enviar Recuperação</button>
