              </div>
              <button onClick={() => setAuthView('login')} className="w-full py-5 bg-green-500 text-black rounded-2xl font-black uppercase text-xs shadow-glow">Voltar para Login</button>
            </div>
          )}
        </div>
      </div>
    );
