      <header className="bg-black/60 backdrop-blur-xl border-b border-zinc-800 px-4 py-3 flex items-center justify-between sticky top-0 z-30">
        <div className="flex items-center gap-3">
           <div onClick={() => setActiveTab('profile')} className="w-9 h-9 rounded-full border border-green-500/30 overflow-hidden bg-zinc-800 flex items-center justify-center shadow-glow">
              {currentUser.avatarUrl ? <img src={currentUser.avatarUrl} className="w-full h-full object-cover" /> : <UserCircle size={24} className="text-green-500" />}
           </div>
           <HPSLogo size="sm" />
        </div>
        <div className="flex items-center gap-2">
          {/* Atalho EPC BRP */}
          <a 
