            title="Catálogo BRP EPC"
          >
            <Globe size={18} />
          </a>
          <button onClick={() => setIsScanning(true)} className="p-3 bg-white text-black rounded-xl shadow-lg active:scale-90 transition-transform"><QrCode size={18} /></button>
          {isAdmin && <button onClick={() => setIsAddingItem(true)} className="p-3 bg-green-500 text-black rounded-xl shadow-lg active:scale-90 transition-transform"><Plus size={18} /></button>}
        </div>
      </header>

      {/* Content Body */}
      <main className="flex-1 overflow-y-auto p-4 space-y-6">
        {activeTab === 'dashboard' && (
          <div className="animate-in fade-in duration-500 space-y-6">
            <div className="grid grid-cols-2 gap-3">
              <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl">
                <div className="p-2.5 bg-zinc-800 text-green-500 rounded-xl w-fit mb-3"><Package size={20} /></div>
                <p className="text-[8px] text-zinc-500 uppercase font-black">Total de Itens</p>
                <p className="text-xl font-black">{items.length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl">
                <div className="p-2.5 bg-amber-500/10 text-amber-500 rounded-xl w-fit mb-3"><AlertTriangle size={20} /></div>
                <p className="text-[8px] text-zinc-500 uppercase font-black">Reposição</p>
                <p className="text-xl font-black">{criticalItems.length}</p>
              </div>
            </div>

            {/* AI Insights Section */}
            <div className="bg-zinc-900 border border-green-500/10 p-6 rounded-[2rem] space-y-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Sparkles className="text-green-500" size={18} />
                  <h3 className="text-[10px] font-black uppercase text-white italic">AI Stock Insights</h3>
                </div>
                <button 
                  onClick={handleGenerateInsights}
                  disabled={loadingInsights}
                  className="p-2 bg-green-500 text-black rounded-lg active:scale-95 disabled:opacity-50 transition-all"
                >
                  {loadingInsights ? <RefreshCcw size={14} className="animate-spin" /> : <RefreshCcw size={14} />}
                </button>
              </div>
              {insights ? (
                <div className="bg-black/40 p-4 rounded-2xl border border-zinc-800">
                  <p className="text-[10px] text-zinc-300 font-medium leading-relaxed whitespace-pre-wrap">{insights}</p>
                </div>
              ) : (
                <p className="text-[8px] text-zinc-600 font-black uppercase tracking-widest text-center py-2 italic">Clique para gerar insights inteligentes do estoque</p>
