            <div className="space-y-4">
              <div className="flex items-center justify-between px-1">
                <h3 className="text-xs font-black uppercase italic text-zinc-500">Catálogo HPS</h3>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-700" size={12} />
                  <input type="text" placeholder="Localizar..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="bg-black border border-zinc-800 rounded-full pl-8 pr-4 py-1.5 text-[10px] font-bold text-white outline-none focus:border-green-500/50" />
                </div>
              </div>
