                          {item.quantity} UN DISPONÍVEL
                        </span>
                      </div>
                    </div>
                    {isAdmin && (
                      <div className="flex flex-col gap-2">
                        <button onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.IN })} className="p-2 bg-zinc-800 text-green-500 rounded-lg active:bg-green-500 active:text-black"><Plus size={16} /></button>
                        <button onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT })} className="p-2 bg-zinc-800 text-white rounded-lg active:bg-white active:text-black"><LogOut size={16} className="rotate-180" /></button>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'profile' && (
          <div className="animate-in slide-in-from-bottom-10 duration-500 pb-10">
            <h2 className="text-xl font-black text-white uppercase italic tracking-widest px-2 mb-6">Configuração</h2>
            <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] space-y-8 shadow-2xl">
              <div className="flex flex-col items-center">
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="w-24 h-24 bg-black border-2 border-green-500/20 rounded-full relative group overflow-hidden mb-4 shadow-glow cursor-pointer"
                 >
                    {profileEdit.avatarUrl ? <img src={profileEdit.avatarUrl} className="w-full h-full object-cover" /> : <UserCircle size={40} className="m-auto h-full text-zinc-800" />}
                    <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <Camera size={18} className="text-green-500" />
                    </div>
                 </div>
                 <input 
                  type="file" 
                  ref={fileInputRef} 
                  accept="image/*" 
                  capture="user" 
                  className="hidden" 
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleImageFile(file, (base64) => setProfileEdit({...profileEdit, avatarUrl: base64}));
                  }}
                />
                 <p className="text-[8px] font-black uppercase text-zinc-600 tracking-widest italic">{currentUser.role === UserRole.STOCKIST ? 'Acesso Gestor' : 'Acesso Operacional'}</p>
              </div>
              <div className="space-y-4">
                <input type="text" value={profileEdit.name} onChange={e => setProfileEdit({...profileEdit, name: e.target.value})} className="w-full bg-black border border-zinc-800 px-5 py-4 rounded-xl text-white font-black uppercase text-[10px]" placeholder="NOME" />
                <input type="text" value={profileEdit.username} onChange={e => setProfileEdit({...profileEdit, username: e.target.value})} className="w-full bg-black border border-zinc-800 px-5 py-4 rounded-xl text-white font-black uppercase text-[10px]" placeholder="LOGIN" />
                <input type="email" value={profileEdit.email} onChange={e => setProfileEdit({...profileEdit, email: e.target.value})} className="w-full bg-black border border-zinc-800 px-5 py-4 rounded-xl text-white font-black text-[10px]" placeholder="E-MAIL" />
                <input type="password" value={profileEdit.password} onChange={e => setProfileEdit({...profileEdit, password: e.target.value})} className="w-full bg-black border border-zinc-800 px-5 py-4 rounded-xl text-white font-black text-[10px]" placeholder="NOVA SENHA" />
              </div>
              <button onClick={updateProfile} className="w-full py-5 bg-green-500 text-black font-black uppercase text-[10px] rounded-2xl shadow-glow flex items-center justify-center gap-2"><Save size={16} /> Gravar Perfil</button>
              <button onClick={() => setCurrentUser(null)} className="w-full py-4 bg-zinc-800 text-red-400 font-black uppercase text-[10px] rounded-2xl flex items-center justify-center gap-2"><LogOut size={16} /> Encerrar Sessão</button>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <h2 className="text-xl font-black text-white uppercase italic tracking-widest px-2">Movimentações</h2>
            <TransactionHistory transactions={displayHistory} />
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex justify-between items-center px-2">
              <h2 className="text-xl font-black text-white uppercase italic tracking-widest">Inventário</h2>
              <button onClick={() => window.print()} className="p-2.5 bg-zinc-900 border border-zinc-800 rounded-xl"><Printer size={18} /></button>
            </div>
            <div className="bg-zinc-900 rounded-[2rem] border border-zinc-800 overflow-hidden shadow-2xl">
              <div className="overflow-x-auto no-scrollbar">
                <table className="w-full text-left text-[9px]">
                  <thead className="bg-zinc-800/40 border-b border-zinc-800">
                    <tr><th className="px-5 py-4 font-black uppercase text-zinc-500">Componente</th><th className="px-5 py-4 font-black uppercase text-zinc-500 text-center">Saldo</th>{isAdmin && <th className="px-5 py-4 font-black uppercase text-zinc-500 text-right">Acumulado</th>}</tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-800">
                    {items.map(item => (
                      <tr key={item.id}>
                        <td className="px-5 py-4 font-black text-white uppercase italic leading-tight">{item.name}<br/><span className="text-[7px] text-zinc-600">PN: {item.partNumber}</span></td>
                        <td className="px-5 py-4 text-center font-black text-green-500 text-sm">{item.quantity}</td>
                        {isAdmin && <td className="px-5 py-4 text-right font-black text-white">R${(item.value * item.quantity).toLocaleString('pt-BR')}</td>}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Mobile Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-black/80 backdrop-blur-2xl border-t border-zinc-800 flex justify-around items-center p-3 z-40 shadow-[0_-10px_30px_rgba(0,0,0,0.5)]">
        <button onClick={() => setActiveTab('dashboard')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'dashboard' ? 'text-green-500' : 'text-zinc-600'}`}>
          <TrendingUp size={22} /><span className="text-[7px] font-black uppercase">Home</span>
        </button>
        <button onClick={() => setActiveTab('reports')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'reports' ? 'text-green-500' : 'text-zinc-600'}`}>
          <FileText size={22} /><span className="text-[7px] font-black uppercase">Stock</span>
        </button>
        <button onClick={() => setIsScanning(true)} className="w-14 h-14 bg-green-500 rounded-full flex items-center justify-center -mt-10 border-4 border-black shadow-glow active:scale-90 transition-transform">
          <QrCode size={26} className="text-black" />
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'history' ? 'text-green-500' : 'text-zinc-600'}`}>
          <History size={22} /><span className="text-[7px] font-black uppercase">Logs</span>
        </button>
        <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'profile' ? 'text-green-500' : 'text-zinc-600'}`}>
          <UserCircle size={22} /><span className="text-[7px] font-black uppercase">Conta</span>
        </button>
      </nav>

      {/* MODALS MOBILE-FIRST */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex items-end justify-center backdrop-blur-md overflow-y-auto">
          <div className="bg-zinc-900 border border-zinc-800 rounded-t-[3rem] w-full max-w-lg shadow-glow animate-in slide-in-from-bottom-20 duration-500">
            <div className="p-8 border-b border-zinc-800 flex justify-between items-center">
              <h3 className="text-lg font-black text-white uppercase italic">Novo Componente</h3>
              <button onClick={() => setIsAddingItem(false)} className="p-3 bg-zinc-800 rounded-xl"><X size={20} /></button>
            </div>
            <form onSubmit={handleAddItem} className="p-8 space-y-4">
              <div className="flex flex-col items-center mb-4">
                <div 
                  onClick={() => itemImageInputRef.current?.click()}
                  className="w-28 h-28 bg-black border-2 border-dashed border-zinc-800 rounded-2xl flex items-center justify-center text-zinc-700 relative group overflow-hidden cursor-pointer shadow-glow"
                >
                  {formData.imageUrl ? (
                    <img src={formData.imageUrl} className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center">
                      <Upload size={24} />
                      <span className="text-[7px] font-black uppercase mt-1">Foto do Item</span>
                    </div>
                  )}
                </div>
                <input 
                  type="file" 
                  ref={itemImageInputRef} 
                  accept="image/*" 
                  capture="environment" 
                  className="hidden" 
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleImageFile(file, (base64) => setFormData({...formData, imageUrl: base64}));
                  }}
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <input required type="text" placeholder="NOME" className="w-full px-5 py-4 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                <input required type="text" placeholder="PART NUMBER" className="w-full px-5 py-4 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <input required type="number" step="0.01" placeholder="VALOR UNIT." className="w-full px-5 py-4 bg-green-500/5 border border-green-500/10 text-green-500 rounded-xl font-black text-[10px]" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                <input required type="number" placeholder="SALDO INICIAL" className="w-full px-5 py-4 bg-black border border-zinc-800 rounded-xl text-white font-black text-[10px]" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
              </div>
              <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl hover:bg-green-400 mt-4 shadow-glow">Gravar Componente</button>
            </form>
          </div>
        </div>
      )}

      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[100] flex items-center justify-center p-4 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] w-full max-w-xs shadow-glow overflow-hidden">
            <div className={`p-6 flex items-center gap-4 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
              <div className="p-3 rounded-xl bg-black/10">{movementModal.type === TransactionType.IN ? <Plus size={24} /> : <LogOut size={24} className="rotate-180" />}</div>
              <h3 className="text-lg font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Retirada'}</h3>
            </div>
            <div className="p-8 space-y-6">
              <input type="number" min="1" className="w-full px-6 py-6 bg-zinc-950 border border-zinc-800 rounded-2xl text-4xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
              {movementModal.type === TransactionType.OUT && (
                <select className="w-full px-4 py-4 bg-zinc-800 rounded-xl text-white font-black text-[10px] uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                  <option value="">PROFISSIONAL DESTINO...</option>
                  {users.filter(u => u.role === UserRole.MECHANIC).map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                </select>
              )}
              <div className="flex gap-2 pt-2">
                <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-4 bg-zinc-800 text-zinc-500 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
                <button onClick={processMovement} className={`flex-[2] py-4 font-black rounded-xl uppercase text-[9px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-zinc-200 text-black'}`}>Confirmar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  Trash2, UserCircle, Zap, DollarSign, Wrench, FileText, 
  Printer, AlertTriangle, ClipboardList, UserCheck, ChevronRight, 
  Users, Download, PlusCircle, X, ExternalLink, ImageIcon, Eye, 
  Maximize2, Lock, KeyRound, ShieldCheck, UserPlus, Camera, Edit3, Save,
  RefreshCcw, Mail, Menu, CheckCircle2, Upload, Sparkles, Globe
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { getStockInsights } from './services/geminiService';

// Base de dados inicial totalmente limpa
const INITIAL_USERS: User[] = [];

const QR_GROUPS = [
  "QR 1 - FREIOS", "QR 2 - SUSPENSÃO", "QR 3 - MOTOR", 
  "QR 4 - TRANSMISSÃO", "QR 5 - ELÉTRICA", "QR 6 - ACESSÓRIOS"
];

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'reports' | 'restock' | 'team' | 'users' | 'profile';
type AuthView = 'login' | 'signup' | 'forgot' | 'email-sent' | 'reset';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg', className?: string }> = ({ size = 'md', className = "" }) => {
  const dimensions = { sm: { width: '60px' }, md: { width: '100px' }, lg: { width: '160px' } };
  return (
    <div className={`flex flex-col items-center ${className} select-none`}>
      <img src="logo.png" alt="HPS CONTROL" style={dimensions[size]} className="drop-shadow-[0_0_15px_rgba(0,255,0,0.3)] object-contain"
        onError={(e) => { e.currentTarget.style.display = 'none'; }} />
    </div>
  );
};

const App: React.FC = () => {
  // Inicialização vazia para atender ao pedido de exclusão de todos os cadastros
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);

  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authView, setAuthView] = useState<AuthView>('login');

  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', email: '', password: '', role: UserRole.MECHANIC, avatarUrl: '' });
  const [forgotForm, setForgotForm] = useState({ email: '' });
  const [resetForm, setResetForm] = useState({ password: '', confirmPassword: '' });
  const [resetTargetUser, setResetTargetUser] = useState<User | null>(null);
  const [loginError, setLoginError] = useState('');

  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [insights, setInsights] = useState<string>('');
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [selectedMechanic, setSelectedMechanic] = useState<string>('');

  const [profileEdit, setProfileEdit] = useState({ name: '', username: '', email: '', password: '', avatarUrl: '' });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [movementNotes, setMovementNotes] = useState('');
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    qrGroup: QR_GROUPS[0], description: '', imageUrl: '', applicationImageUrl: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const itemImageInputRef = useRef<HTMLInputElement>(null);

  // Efeito para limpar o localStorage no primeiro carregamento (Reset de Fábrica)
  useEffect(() => {
    // Para garantir que os dados antigos sumam do navegador do usuário
    localStorage.removeItem('hps_items');
    localStorage.removeItem('hps_history');
    localStorage.removeItem('hps_users');

    // Estados já começam vazios, mas forçamos aqui por segurança
    setItems([]);
    setHistory([]);
    setUsers([]);
  }, []);

  // Efeito para persistir apenas NOVOS cadastros
  useEffect(() => {
    if (items.length > 0) localStorage.setItem('hps_items', JSON.stringify(items));
    if (history.length > 0) localStorage.setItem('hps_history', JSON.stringify(history));
    if (users.length > 0) localStorage.setItem('hps_users', JSON.stringify(users));
  }, [items, history, users]);

  useEffect(() => {
    if (currentUser) {
      setProfileEdit({
        name: currentUser.name,
        username: currentUser.username,
        email: currentUser.email || '',
        password: currentUser.password || '',
        avatarUrl: currentUser.avatarUrl || ''
      });
    }
  }, [currentUser]);

  const handleImageFile = (file: File, callback: (base64: string) => void) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      callback(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toUpperCase() === loginForm.username.toUpperCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
      setLoginError('');
      setActiveTab('dashboard');
      if (user.role === UserRole.MECHANIC) setSelectedMechanic(user.name);
      else setSelectedMechanic(users.find(u => u.role === UserRole.MECHANIC)?.name || '');
    } else {
      setLoginError('Credenciais incorretas.');
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toUpperCase() === signupForm.username.toUpperCase())) {
      setLoginError('Usuário já existe.');
      return;
    }
    const newUser: User = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers(prev => [...prev, newUser]);
    setAuthView('login');
    setLoginError('Cadastrado com sucesso!');
    setLoginForm({ username: signupForm.username, password: signupForm.password });
  };

  const handleForgotFlow = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.email?.toLowerCase() === forgotForm.email.toLowerCase());
    if (user) {
      setResetTargetUser(user);
      setAuthView('email-sent'); 
      setLoginError('');
    } else {
      setLoginError('E-mail não localizado na base HPS.');
    }
  };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentUser?.role !== UserRole.STOCKIST) return;
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    setItems(prev => [...prev, newItem]);
    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser.id, userName: currentUser.name,
      type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'Depósito Central', notes: 'Entrada Inicial'
    }]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
      qrGroup: QR_GROUPS[0], description: '', imageUrl: '', applicationImageUrl: '' });
  };

  const processMovement = () => {
    if (!movementModal.itemId || currentUser?.role !== UserRole.STOCKIST) return;
    const itemIndex = items.findIndex(i => i.id === movementModal.itemId);
    if (itemIndex === -1) return;
    const currentItem = items[itemIndex];
    if (movementModal.type === TransactionType.OUT && currentItem.quantity < movementQty) {
      alert("Estoque insuficiente!");
      return;
    }
    const updatedItems = [...items];
    const qtyChange = movementModal.type === TransactionType.IN ? movementQty : -movementQty;
    updatedItems[itemIndex].quantity += qtyChange;
    setItems(updatedItems);
    setHistory(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9), itemId: currentItem.id, itemName: currentItem.name, userId: currentUser.id, userName: currentUser.name,
      type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', notes: movementNotes
    }]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setMovementNotes('');
  };

  const updateProfile = () => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, ...profileEdit };
    setCurrentUser(updatedUser);
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    alert("Perfil atualizado com sucesso!");
  };

  const handleGenerateInsights = async () => {
    setLoadingInsights(true);
    const result = await getStockInsights(items, history);
    setInsights(result || "Nenhum insight disponível.");
    setLoadingInsights(false);
  };

  const handleQRScan = (decodedText: string) => {
    const item = items.find(i => i.partNumber === decodedText || i.id === decodedText);
    if (item) {
      setActiveTab('inventory');
      setSearchTerm(item.partNumber);
      if (currentUser?.role === UserRole.STOCKIST) setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
    } else alert("QR Code não reconhecido.");
  };

  const filteredItems = items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase()));
  const totalStockValue = items.reduce((acc, curr) => acc + (curr.value * curr.quantity), 0);
  const criticalItems = items.filter(i => i.quantity <= i.minQuantity);
  const displayHistory = history.filter(h => {
    if (currentUser?.role === UserRole.MECHANIC) return h.recipientName === currentUser.name;
    if (activeTab === 'team') return h.recipientName === selectedMechanic;
    return true;
  });

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-4">
        <div className="bg-zinc-900 border border-green-500/10 p-6 sm:p-10 rounded-[2.5rem] w-full max-w-sm shadow-2xl animate-in fade-in duration-500">
          <HPSLogo size="lg" className="mb-6" />
          <h1 className="text-sm font-black text-white uppercase tracking-[0.2em] text-center mb-8 italic">
            {authView === 'login' ? 'HPS CONTROL' : authView === 'signup' ? 'Novo Cadastro' : authView === 'forgot' ? 'Recuperação' : 'E-mail Enviado'}
          </h1>

          {authView === 'login' && (
            <form onSubmit={handleLogin} className="space-y-4">
              <input required type="text" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black uppercase text-xs focus:ring-1 focus:ring-green-500/30" placeholder="USUÁRIO" />
              <input required type="password" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} className="w-full px-6 py-4 bg-black border border-zinc-800 rounded-2xl outline-none text-white font-black text-xs focus:ring-1 focus:ring-green-500/30" placeholder="SENHA" />
              <div className="flex justify-between px-2">
                <button type="button" onClick={() => setAuthView('forgot')} className="text-[8px] font-black uppercase text-zinc-600">Esqueci a senha</button>
                <button type="button" onClick={() => setAuthView('signup')} className="text-[8px] font-black uppercase text-green-600">Criar acesso</button>
              </div>
              {loginError && <p className="text-red-500 text-[9px] font-black uppercase text-center">{loginError}</p>}
              <button type="submit" className="w-full py-5 bg-green-500 text-black rounded-2xl font-black uppercase text-xs hover:bg-green-400 shadow-glow transition-all">Entrar</button>
            </form>
          )}

          {authView === 'signup' && (
            <form onSubmit={handleSignup} className="space-y-3">
              <div className="flex flex-col items-center mb-4">
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-24 h-24 bg-black border-2 border-dashed border-zinc-800 rounded-full flex items-center justify-center text-zinc-700 relative group overflow-hidden cursor-pointer shadow-glow"
                >
                  {signupForm.avatarUrl ? (
                    <img src={signupForm.avatarUrl} className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center">
                      <Camera size={24} />
                      <span className="text-[7px] font-black uppercase mt-1">Foto Perfil</span>
                    </div>
                  )}
                </div>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  accept="image/*" 
                  capture="user" 
                  className="hidden" 
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleImageFile(file, (base64) => setSignupForm({...signupForm, avatarUrl: base64}));
                  }}
                />
              </div>
              <input required type="text" placeholder="NOME COMPLETO" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" />
              <input required type="text" placeholder="USUÁRIO (LOGIN)" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" />
              <input required type="email" placeholder="E-MAIL" value={signupForm.email} onChange={e => setSignupForm({...signupForm, email: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black text-[10px]" />
              <input required type="password" placeholder="SENHA" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black text-[10px]" />
              <select className="w-full px-5 py-3 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
