                <option value={UserRole.STOCKIST}>Estoquista (Gestão)</option>
              </select>
              <button type="submit" className="w-full py-4 bg-green-500 text-black rounded-xl font-black uppercase text-[10px] mt-2 shadow-glow">Finalizar Cadastro</button>
              <button type="button" onClick={() => setAuthView('login')} className="w-full text-[8px] font-black uppercase text-zinc-500 py-2">Voltar</button>
            </form>
          )}

          {authView === 'forgot' && (
            <form onSubmit={handleForgotFlow} className="space-y-4">
