            </form>
          )}

          {authView === 'email-sent' && (
            <div className="text-center space-y-6 animate-in zoom-in duration-300">
              <div className="w-20 h-20 bg-green-500/10 rounded-full flex items-center justify-center mx-auto text-green-500">
                <CheckCircle2 size={40} />
              </div>
