              ) : (
                <div className="grid grid-cols-1 gap-3">
                  {filteredItems.map(item => (
                    <div key={item.id} className="bg-zinc-900/60 border border-zinc-800 p-4 rounded-[2rem] flex items-center gap-4 shadow-sm">
                      <div className="w-16 h-16 bg-black border border-zinc-800 rounded-2xl overflow-hidden shrink-0">
                        {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={24} className="text-zinc-800 m-auto h-full" />}
