                <input type="email" value={profileEdit.email} onChange={e => setProfileEdit({...profileEdit, email: e.target.value})} className="w-full bg-black border border-zinc-800 px-5 py-4 rounded-xl text-white font-black text-[10px]" placeholder="E-MAIL" />
                <input type="password" value={profileEdit.password} onChange={e => setProfileEdit({...profileEdit, password: e.target.value})} className="w-full bg-black border border-zinc-800 px-5 py-4 rounded-xl text-white font-black text-[10px]" placeholder="SENHA" />
