                        {isAdmin && <td className="px-5 py-4 text-right font-black text-white">R${(item.value * item.quantity).toLocaleString('pt-BR')}</td>}
                      </tr>
                    ))}
                    {items.length === 0 && (
                      <tr>
                        <td colSpan={isAdmin ? 3 : 2} className="px-5 py-10 text-center text-zinc-700 italic font-black uppercase">Nenhum dado</td>
