            <form onSubmit={handleAddItem} className="p-8 space-y-4">
              <div className="flex flex-col items-center mb-4">
                <div 
                  onClick={() => itemImageInputRef.current?.click()}
                  className="w-28 h-28 bg-black border-2 border-dashed border-zinc-800 rounded-2xl flex items-center justify-center text-zinc-700 relative group overflow-hidden cursor-pointer shadow-glow"
                >
                  {formData.imageUrl ? (
                    <img src={formData.imageUrl} className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center">
                      <Upload size={24} />
                      <span className="text-[7px] font-black uppercase mt-1">Foto da Peça</span>
                    </div>
                  )}
                </div>
                <input 
                  type="file" 
                  ref={itemImageInputRef} 
                  accept="image/*" 
                  capture="environment" 
                  className="hidden" 
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleImageFile(file, (base64) => setFormData({...formData, imageUrl: base64}));
                  }}
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <input required type="text" placeholder="DESCRIÇÃO" className="w-full px-5 py-4 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                <input required type="text" placeholder="PART NUMBER" className="w-full px-5 py-4 bg-black border border-zinc-800 rounded-xl text-white font-black uppercase text-[10px]" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <input required type="number" step="0.01" placeholder="VALOR R$" className="w-full px-5 py-4 bg-green-500/5 border border-green-500/10 text-green-500 rounded-xl font-black text-[10px]" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                <input required type="number" placeholder="SALDO" className="w-full px-5 py-4 bg-black border border-zinc-800 rounded-xl text-white font-black text-[10px]" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
              </div>
              <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-transform mt-4">Registrar Item</button>
            </form>
          </div>
        </div>
      )}

      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[100] flex items-center justify-center p-4 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] w-full max-w-xs shadow-glow overflow-hidden">
            <div className={`p-6 flex items-center gap-4 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
              <div className="p-3 rounded-xl bg-black/10">{movementModal.type === TransactionType.IN ? <Plus size={24} /> : <LogOut size={24} className="rotate-180" />}</div>
              <h3 className="text-lg font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Baixa'}</h3>
            </div>
            <div className="p-8 space-y-6">
              <input type="number" min="1" className="w-full px-6 py-6 bg-zinc-950 border border-zinc-800 rounded-2xl text-4xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
              {movementModal.type === TransactionType.OUT && (
                <select className="w-full px-4 py-4 bg-zinc-800 rounded-xl text-white font-black text-[10px] uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                  <option value="">PROFISSIONAL...</option>
                  {users.filter(u => u.role === UserRole.MECHANIC).map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                </select>
              )}
              <div className="flex gap-2 pt-2">
                <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-4 bg-zinc-800 text-zinc-500 font-black rounded-xl uppercase text-[9px]">Voltar</button>
                <button onClick={processMovement} className={`flex-[2] py-4 font-black rounded-xl uppercase text-[9px] shadow-glow active:scale-95 transition-all ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-zinc-200 text-black'}`}>Executar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

export enum UserRole {
  STOCKIST = 'STOCKIST', // Acesso Total (Gerenciamento)
  MECHANIC = 'MECHANIC'  // Acesso Limitado (Apenas retirada destinada)
}

export interface User {
  id: string;
  username: string;
  password?: string;
  email?: string;
  name: string;
  role: UserRole;
  avatarUrl?: string;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  minQuantity: number;
  qrGroup: string;
  entryDate: string;
  linkedQRCode?: string; // Código QR exclusivo vinculado à peça
  description?: string;
  imageUrl?: string;
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string;
  notes?: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, Upload, 
  Camera, Save, Mail, CheckCircle2, Globe, ShieldAlert, Check,
  ChevronRight, Smartphone
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';

const QR_GROUPS = ["FREIOS", "SUSPENSÃO", "MOTOR", "TRANSMISSÃO", "ELÉTRICA", "ACESSÓRIOS"];

type ActiveTab = 'dashboard' | 'history' | 'reports' | 'profile';
type AuthView = 'login' | 'signup' | 'forgot' | 'email-sent';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => {
  const width = size === 'sm' ? '60px' : size === 'md' ? '100px' : '150px';
  return (
    <div className="flex flex-col items-center select-none">
      <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
        <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  // --- ESTADO GLOBAL ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [targetItemForValidation, setTargetItemForValidation] = useState<InventoryItem | null>(null);

  // --- FORM STATE ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', email: '', password: '', role: UserRole.MECHANIC, avatarUrl: '' });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    qrGroup: QR_GROUPS[0], linkedQRCode: '', imageUrl: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');

  // --- PERSISTÊNCIA ---
  useEffect(() => {
    const savedItems = localStorage.getItem('hps_v3_items');
    const savedHistory = localStorage.getItem('hps_v3_history');
    const savedUsers = localStorage.getItem('hps_v3_users');

    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedUsers) setUsers(JSON.parse(savedUsers));
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_v3_items', JSON.stringify(items));
    localStorage.setItem('hps_v3_history', JSON.stringify(history));
    localStorage.setItem('hps_v3_users', JSON.stringify(users));
  }, [items, history, users]);

  // --- ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
    } else {
      alert("Usuário ou senha incorretos.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === signupForm.username.toLowerCase())) {
      alert("Este nome de usuário já está em uso.");
      return;
    }
    const newUser: User = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers(prev => [...prev, newUser]);
    setAuthView('login');
    alert("Conta criada! Agora entre com seus dados.");
  };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { 
      id: Math.random().toString(36).substr(2, 9), 
      ...formData, 
      entryDate: new Date().toISOString() 
    };

    // Adiciona o item à lista imediatamente
    setItems(prev => [newItem, ...prev]);

    // Registra no histórico
    setHistory(prev => [{
      id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name,
      type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'DEPÓSITO', notes: 'Cadastro Inicial'
    }, ...prev]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, qrGroup: QR_GROUPS[0], linkedQRCode: '', imageUrl: '' });
    alert("Item registrado com sucesso!");
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    // Se for saída e tiver QR vinculado, exige validação se ainda não validou
    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setTargetItemForValidation(item);
      setScanMode('validate');
      setIsScanning(true);
      return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Estoque insuficiente!");
      return;
    }

    setItems(prev => prev.map(i => {
      if (i.id === item.id) {
        return { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) };
      }
      return i;
    }));

    setHistory(prev => [{
      id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name,
      type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', notes: validated ? 'Validado via QR' : ''
    }, ...prev]);

    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient('');
    if (validated) alert("Saída validada e concluída!");
  };

  const handleQRScan = (decodedText: string) => {
    setIsScanning(false);

    if (scanMode === 'bind') {
      setFormData({ ...formData, linkedQRCode: decodedText });
      alert("QR Code vinculado com sucesso!");
      return;
    }

    if (scanMode === 'validate') {
      if (targetItemForValidation?.linkedQRCode === decodedText) {
        processMovement(true);
      } else {
        alert("ERRO: QR Code não corresponde a este item!");
      }
      setTargetItemForValidation(null);
      return;
    }

    // Modo Busca (Padrão)
    const item = items.find(i => i.linkedQRCode === decodedText || i.partNumber === decodedText);
    if (item) {
      setSearchTerm(item.partNumber);
      if (currentUser?.role === UserRole.STOCKIST) {
        setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT });
      }
    } else {
      alert("Código não encontrado no sistema.");
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const isAdmin = currentUser?.role === UserRole.STOCKIST;

  // --- RENDER LOGIN ---
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in duration-700">
          <div className="text-center">
            <HPSLogo size="lg" />
            <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mt-4 italic">Sistema de Gestão de Frota</p>
          </div>

          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-2xl">
            {authView === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs outline-none focus:border-green-500/50" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs outline-none focus:border-green-500/50" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full py-4 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow hover:bg-green-400 transition-all active:scale-95">Acessar Painel</button>
                <button type="button" onClick={() => setAuthView('signup')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Não tem conta? Cadastre-se</button>
              </form>
            ) : (
              <form onSubmit={handleSignup} className="space-y-4">
                <input required type="text" placeholder="NOME COMPLETO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} />
                <input required type="text" placeholder="LOGIN" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} />
                <select className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
                  <option value={UserRole.MECHANIC}>Oficina (Retirada)</option>
                  <option value={UserRole.STOCKIST}>Estoque (Gestor)</option>
                </select>
                <button type="submit" className="w-full py-4 bg-white text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95">Criar Perfil</button>
                <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Já tenho cadastro</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  // --- RENDER APP ---
  return (
    <div className="min-h-screen flex flex-col bg-zinc-950 text-white font-sans pb-24">
      {/* Header Fixo */}
      <header className="bg-black/80 backdrop-blur-xl border-b border-zinc-800 px-6 py-4 flex items-center justify-between sticky top-0 z-50">
        <HPSLogo size="sm" />
        <div className="flex items-center gap-3">
          <a href="https://epc.brp.com/#" target="_blank" className="p-2.5 bg-zinc-900 border border-zinc-800 rounded-xl text-green-500 active:scale-90 transition-transform">
            <Globe size={18} />
          </a>
          {isAdmin && (
            <button onClick={() => setIsAddingItem(true)} className="p-2.5 bg-green-500 text-black rounded-xl active:scale-90 transition-transform">
              <Plus size={18} strokeWidth={3} />
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="p-4 space-y-6">
        {activeTab === 'dashboard' && (
          <div className="animate-in fade-in duration-500 space-y-6">
            <div className="grid grid-cols-2 gap-3">
              <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1">Total Peças</p>
                <p className="text-2xl font-black">{items.length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1">Alertas</p>
                <p className="text-2xl font-black text-amber-500">{items.filter(i => i.quantity <= i.minQuantity).length}</p>
              </div>
            </div>

            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600" size={16} />
              <input type="text" placeholder="Buscar por nome ou PN..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-zinc-900 border border-zinc-800 pl-12 pr-6 py-4 rounded-2xl font-bold text-sm outline-none focus:border-green-500/30" />
            </div>

            <div className="grid gap-3">
              {filteredItems.map(item => (
                <div key={item.id} className="bg-zinc-900/50 border border-zinc-800 p-4 rounded-[2rem] flex items-center gap-4 group active:bg-zinc-800/80 transition-all">
                  <div className="w-14 h-14 bg-black rounded-2xl flex items-center justify-center text-zinc-800 shrink-0 border border-zinc-800 overflow-hidden">
                    {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={20} />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className="font-black text-xs uppercase italic truncate">{item.name}</h4>
                    <p className="text-[8px] text-zinc-600 font-bold uppercase">PN: {item.partNumber}</p>
                    <div className="mt-1">
                      <span className={`text-[9px] font-black ${item.quantity <= item.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>
                        {item.quantity} UN DISPONÍVEL
                      </span>
                    </div>
                  </div>
                  {isAdmin && (
                    <div className="flex gap-2">
                      <button onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.IN })} className="p-3 bg-zinc-800 text-green-500 rounded-xl"><Plus size={16} /></button>
                      <button onClick={() => setMovementModal({ isOpen: true, itemId: item.id, type: TransactionType.OUT })} className="p-3 bg-zinc-800 text-white rounded-xl"><LogOut size={16} className="rotate-180" /></button>
                    </div>
                  )}
                </div>
              ))}
              {filteredItems.length === 0 && (
                <div className="py-20 text-center text-zinc-700 font-black uppercase text-[10px] tracking-widest italic border-2 border-dashed border-zinc-900 rounded-[2rem]">Nenhum item encontrado</div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'history' && <TransactionHistory transactions={history.filter(h => isAdmin || h.recipientName === currentUser.name)} />}

        {activeTab === 'reports' && (
           <div className="space-y-4">
              <div className="flex justify-between items-center px-2">
                <h2 className="text-xl font-black uppercase italic italic tracking-widest">Estoque</h2>
                <button onClick={() => window.print()} className="p-3 bg-zinc-900 border border-zinc-800 rounded-xl"><Printer size={18} /></button>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 rounded-3xl overflow-hidden">
                <table className="w-full text-left text-[10px]">
                  <thead className="bg-zinc-800 text-zinc-500 font-black uppercase">
                    <tr><th className="p-4">Item</th><th className="p-4 text-center">Qtd</th><th className="p-4 text-right">Valor</th></tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-800 font-bold">
                    {items.map(item => (
                      <tr key={item.id} className="active:bg-zinc-800">
                        <td className="p-4">{item.name}<br/><span className="text-[8px] text-zinc-600">PN: {item.partNumber}</span></td>
                        <td className="p-4 text-center text-green-500">{item.quantity}</td>
                        <td className="p-4 text-right">R$ {item.value.toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
           </div>
        )}

        {activeTab === 'profile' && (
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] space-y-6 text-center">
            <div className="w-24 h-24 bg-black border-2 border-green-500/30 rounded-full mx-auto flex items-center justify-center text-zinc-800 shadow-glow mb-2">
              <UserCircle size={48} />
            </div>
            <div>
              <h2 className="text-xl font-black uppercase italic">{currentUser.name}</h2>
              <p className="text-[9px] text-zinc-600 font-black uppercase tracking-[0.2em]">{isAdmin ? 'Acesso Gestão HPS' : 'Técnico de Oficina'}</p>
            </div>
            <div className="pt-6">
              <button onClick={() => setCurrentUser(null)} className="w-full py-4 bg-zinc-800 text-red-400 font-black uppercase text-xs rounded-2xl active:bg-red-500 active:text-white transition-all">Sair do Sistema</button>
            </div>
          </div>
        )}
      </main>

      {/* Nav Inferior */}
      <nav className="fixed bottom-0 left-0 right-0 bg-black/90 backdrop-blur-2xl border-t border-zinc-800 p-4 flex justify-around items-center z-50">
        <button onClick={() => setActiveTab('dashboard')} className={`flex flex-col items-center gap-1 ${activeTab === 'dashboard' ? 'text-green-500' : 'text-zinc-600'}`}>
          <TrendingUp size={22} /><span className="text-[8px] font-black uppercase">Home</span>
        </button>
        <button onClick={() => setActiveTab('reports')} className={`flex flex-col items-center gap-1 ${activeTab === 'reports' ? 'text-green-500' : 'text-zinc-600'}`}>
          <FileText size={22} /><span className="text-[8px] font-black uppercase">Stock</span>
        </button>
        <button onClick={() => { setScanMode('search'); setIsScanning(true); }} className="w-14 h-14 bg-green-500 rounded-full flex items-center justify-center -mt-10 border-4 border-zinc-950 shadow-glow active:scale-90 transition-transform">
          <QrCode size={26} className="text-black" strokeWidth={3} />
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 ${activeTab === 'history' ? 'text-green-500' : 'text-zinc-600'}`}>
          <History size={22} /><span className="text-[8px] font-black uppercase">Logs</span>
        </button>
        <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center gap-1 ${activeTab === 'profile' ? 'text-green-500' : 'text-zinc-600'}`}>
          <UserCircle size={22} /><span className="text-[8px] font-black uppercase">Conta</span>
        </button>
      </nav>

      {/* MODAL ADICIONAR ITEM */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex items-end justify-center backdrop-blur-md overflow-y-auto pt-20">
          <div className="bg-zinc-900 border border-zinc-800 rounded-t-[3rem] w-full max-w-lg shadow-glow animate-in slide-in-from-bottom-20 duration-500">
            <div className="p-8 border-b border-zinc-800 flex justify-between items-center">
              <h3 className="text-lg font-black uppercase italic">Novo Cadastro</h3>
              <button onClick={() => setIsAddingItem(false)} className="p-3 bg-zinc-800 rounded-xl"><X size={20} /></button>
            </div>
            <form onSubmit={handleAddItem} className="p-8 space-y-4">
              <input required type="text" placeholder="NOME DA PEÇA" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-3">
                <input required type="text" placeholder="PART NUMBER" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                <input required type="number" step="0.01" placeholder="VALOR UNIT." className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-green-500 font-black text-[11px]" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
              </div>

              <div className="bg-black border border-zinc-800 p-5 rounded-2xl space-y-3">
                <p className="text-[8px] font-black uppercase text-zinc-500 italic">Vínculo de Segurança QR</p>
                <div className="flex gap-2">
                  <div className="flex-1 bg-zinc-900 border border-zinc-800 p-3 rounded-xl text-[10px] font-black text-green-500 truncate">
                    {formData.linkedQRCode || "Código Não Vinculado"}
                  </div>
                  <button type="button" onClick={() => { setScanMode('bind'); setIsScanning(true); }} className="bg-green-500 text-black px-4 py-2 rounded-xl font-black text-[10px] uppercase shadow-glow">
                    Ler QR
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <input required type="number" placeholder="SALDO INICIAL" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                <input required type="number" placeholder="ESTOQUE MÍN." className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.minQuantity || ''} onChange={e => setFormData({...formData, minQuantity: parseInt(e.target.value) || 0})} />
              </div>
              <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow">Finalizar Registro</button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL MOVIMENTAÇÃO */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[100] flex items-center justify-center p-6 backdrop-blur-xl">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] w-full max-w-xs shadow-glow">
            <div className={`p-6 rounded-t-[2.5rem] flex items-center gap-4 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
               {movementModal.type === TransactionType.IN ? <Plus size={24} strokeWidth={3} /> : <LogOut size={24} className="rotate-180" strokeWidth={3} />}
               <h3 className="text-lg font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Retirada'}</h3>
            </div>
            <div className="p-8 space-y-6">
               <input type="number" className="w-full bg-zinc-950 border border-zinc-800 p-6 rounded-2xl text-4xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
               {movementModal.type === TransactionType.OUT && (
                 <select className="w-full bg-zinc-800 p-4 rounded-xl text-white font-black text-[10px] uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                   <option value="">SELECIONE O TÉCNICO...</option>
                   {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                 </select>
               )}
               <div className="flex gap-2">
                 <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-4 bg-zinc-800 text-zinc-500 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
                 <button onClick={() => processMovement()} className={`flex-[2] py-4 font-black rounded-xl uppercase text-[9px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* SCANNER COMPONENT */}
      {isScanning && (
        <QRScanner 
          onScan={handleQRScan} 
          onClose={() => { setIsScanning(false); setTargetItemForValidation(null); }} 
        />
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  STOCKIST = 'STOCKIST', // Acesso Total (Gerenciamento)
  MECHANIC = 'MECHANIC'  // Acesso Limitado (Apenas retirada destinada)
}

export interface User {
  id: string;
  username: string;
  password?: string;
  email?: string;
  name: string;
  role: UserRole;
  avatarUrl?: string;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  minQuantity: number;
  qrGroup: string;
  entryDate: string;
  linkedQRCode?: string;
  description?: string;
  imageUrl?: string;
  observations?: string; // Campo para observações gerais do item
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export enum MovementDestination {
  OS = 'OS',
  INTERNAL = 'INTERNAL'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string;
  notes?: string;
  destination?: MovementDestination;
  osNumber?: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, Upload, 
  Camera, Save, Mail, CheckCircle2, Globe, ShieldAlert, Check,
  ChevronRight, Smartphone, Eye, Info, Wrench, Factory, Filter
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';

const QR_GROUPS = ["FREIOS", "SUSPENSÃO", "MOTOR", "TRANSMISSÃO", "ELÉTRICA", "ACESSÓRIOS"];

type ActiveTab = 'dashboard' | 'history' | 'reports' | 'profile';
type AuthView = 'login' | 'signup' | 'forgot' | 'email-sent';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => {
  return (
    <div className="flex flex-col items-center select-none">
      <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
        <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  // --- ESTADO GLOBAL ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [targetItemForValidation, setTargetItemForValidation] = useState<InventoryItem | null>(null);
  const [selectedItemDetails, setSelectedItemDetails] = useState<InventoryItem | null>(null);

  // --- FORM STATE ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', email: '', password: '', role: UserRole.MECHANIC, avatarUrl: '' });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    qrGroup: QR_GROUPS[0], linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  const itemImageInputRef = useRef<HTMLInputElement>(null);

  // --- PERSISTÊNCIA ---
  useEffect(() => {
    const savedItems = localStorage.getItem('hps_v3_items');
    const savedHistory = localStorage.getItem('hps_v3_history');
    const savedUsers = localStorage.getItem('hps_v3_users');

    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedUsers) setUsers(JSON.parse(savedUsers));
  }, []);

  useEffect(() => {
    localStorage.setItem('hps_v3_items', JSON.stringify(items));
    localStorage.setItem('hps_v3_history', JSON.stringify(history));
    localStorage.setItem('hps_v3_users', JSON.stringify(users));
  }, [items, history, users]);

  // --- ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
    } else {
      alert("Usuário ou senha incorretos.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === signupForm.username.toLowerCase())) {
      alert("Este nome de usuário já está em uso.");
      return;
    }
    const newUser: User = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers(prev => [...prev, newUser]);
    setAuthView('login');
    alert("Conta criada! Agora entre com seus dados.");
  };

  const handleImageFile = (file: File, callback: (base64: string) => void) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      callback(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { 
      id: Math.random().toString(36).substr(2, 9), 
      ...formData, 
      entryDate: new Date().toISOString() 
    };

    setItems(prev => [newItem, ...prev]);

    setHistory(prev => [{
      id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name,
      type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'DEPÓSITO', notes: 'Cadastro Inicial: ' + formData.observations
    }, ...prev]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, qrGroup: QR_GROUPS[0], linkedQRCode: '', imageUrl: '', observations: '' });
    alert("Item registrado com sucesso!");
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setTargetItemForValidation(item);
      setScanMode('validate');
      setIsScanning(true);
      return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Estoque insuficiente!");
      return;
    }

    setItems(prev => prev.map(i => {
      if (i.id === item.id) {
        return { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) };
      }
      return i;
    }));

    setHistory(prev => [{
      id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name,
      type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', 
      notes: validated ? 'Validado via QR' : '',
      destination: movementModal.type === TransactionType.OUT ? destination : undefined,
      osNumber: movementModal.type === TransactionType.OUT && destination === MovementDestination.OS ? osNumber : undefined
    }, ...prev]);

    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setOsNumber('');
    if (validated) alert("Saída validada e concluída!");
  };

  const handleQRScan = (decodedText: string) => {
    setIsScanning(false);

    if (scanMode === 'bind') {
      setFormData({ ...formData, linkedQRCode: decodedText });
      alert("QR Code vinculado com sucesso!");
      return;
    }

    if (scanMode === 'validate') {
      if (targetItemForValidation?.linkedQRCode === decodedText) {
        processMovement(true);
      } else {
        alert("ERRO: QR Code não corresponde a este item!");
      }
      setTargetItemForValidation(null);
      return;
    }

    const item = items.find(i => i.linkedQRCode === decodedText || i.partNumber === decodedText);
    if (item) {
      setSelectedItemDetails(item);
    } else {
      alert("Código não encontrado no sistema.");
    }
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const isAdmin = currentUser?.role === UserRole.STOCKIST;

  // --- RENDER LOGIN ---
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in duration-700">
          <div className="text-center">
            <HPSLogo size="lg" />
            <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mt-4 italic">Controle de Estoque e Insumos</p>
          </div>

          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-2xl">
            {authView === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs outline-none focus:border-green-500/50" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs outline-none focus:border-green-500/50" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full py-4 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow hover:bg-green-400 transition-all active:scale-95">Acessar Painel</button>
                <button type="button" onClick={() => setAuthView('signup')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Não tem conta? Cadastre-se</button>
              </form>
            ) : (
              <form onSubmit={handleSignup} className="space-y-4">
                <input required type="text" placeholder="NOME COMPLETO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} />
                <input required type="text" placeholder="LOGIN" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} />
                <select className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-black text-xs" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
                  <option value={UserRole.MECHANIC}>Oficina (Retirada)</option>
                  <option value={UserRole.STOCKIST}>Estoque (Gestor)</option>
                </select>
                <button type="submit" className="w-full py-4 bg-white text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95">Criar Perfil</button>
                <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Já tenho cadastro</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  // --- RENDER APP ---
  return (
    <div className="min-h-screen flex flex-col bg-zinc-950 text-white font-sans pb-24">
      {/* Header Fixo */}
      <header className="bg-black/80 backdrop-blur-xl border-b border-zinc-800 px-6 py-4 flex items-center justify-between sticky top-0 z-50">
        <HPSLogo size="sm" />
        <div className="flex items-center gap-3">
          <a href="https://epc.brp.com/#" target="_blank" className="p-2.5 bg-zinc-900 border border-zinc-800 text-green-500 active:scale-90 transition-transform">
            <Globe size={18} />
          </a>
          {isAdmin && (
            <button onClick={() => setIsAddingItem(true)} className="p-2.5 bg-green-500 text-black rounded-xl active:scale-90 transition-transform">
              <Plus size={18} strokeWidth={3} />
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="p-4 space-y-6">
        {activeTab === 'dashboard' && (
          <div className="animate-in fade-in duration-500 space-y-6">
            <div className="grid grid-cols-2 gap-3">
              <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1">Total Peças</p>
                <p className="text-2xl font-black">{items.length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-3xl">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1">Alertas</p>
                <p className="text-2xl font-black text-amber-500">{items.filter(i => i.quantity <= i.minQuantity).length}</p>
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex items-center gap-2 px-1">
                <Filter size={14} className="text-green-500" />
                <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Busca Ágil (Nome ou Part Number)</span>
              </div>
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600" size={16} />
                <input type="text" placeholder="Localizar item..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-zinc-900 border border-zinc-800 pl-12 pr-6 py-4 rounded-2xl font-bold text-sm outline-none focus:border-green-500/30" />
              </div>
            </div>

            <div className="grid gap-3">
              {filteredItems.map(item => (
                <div 
                  key={item.id} 
                  onClick={() => setSelectedItemDetails(item)}
                  className="bg-zinc-900/50 border border-zinc-800 p-4 rounded-[2rem] flex items-center gap-4 group active:bg-zinc-800/80 transition-all cursor-pointer"
                >
                  <div className="w-14 h-14 bg-black rounded-2xl flex items-center justify-center text-zinc-800 shrink-0 border border-zinc-800 overflow-hidden">
                    {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={20} />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className="font-black text-xs uppercase italic truncate">{item.name}</h4>
                    <p className="text-[8px] text-zinc-600 font-bold uppercase">PN: {item.partNumber}</p>
                    <div className="mt-1">
                      <span className={`text-[9px] font-black ${item.quantity <= item.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>
                        {item.quantity} UN DISPONÍVEL
                      </span>
                    </div>
                  </div>
                  <div className="p-2 bg-zinc-800 rounded-lg group-hover:bg-green-500/10 transition-colors">
                    <ChevronRight size={16} className="text-zinc-500 group-hover:text-green-500" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'history' && <TransactionHistory transactions={history.filter(h => isAdmin || h.recipientName === currentUser.name)} />}

        {activeTab === 'reports' && (
           <div className="space-y-4">
              <div className="flex justify-between items-center px-2">
                <h2 className="text-xl font-black uppercase italic italic tracking-widest">Estoque</h2>
                <button onClick={() => window.print()} className="p-3 bg-zinc-900 border border-zinc-800 rounded-xl"><Printer size={18} /></button>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 rounded-3xl overflow-hidden shadow-2xl">
                <table className="w-full text-left text-[10px]">
                  <thead className="bg-zinc-800 text-zinc-500 font-black uppercase">
                    <tr><th className="p-4">Item</th><th className="p-4 text-center">Qtd</th><th className="p-4 text-right">Valor</th></tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-800 font-bold">
                    {items.map(item => (
                      <tr key={item.id} className="active:bg-zinc-800">
                        <td className="p-4">{item.name}<br/><span className="text-[8px] text-zinc-600">PN: {item.partNumber}</span></td>
                        <td className="p-4 text-center text-green-500">{item.quantity}</td>
                        <td className="p-4 text-right">R$ {item.value.toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
           </div>
        )}

        {activeTab === 'profile' && (
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] space-y-6 text-center">
            <div className="w-24 h-24 bg-black border-2 border-green-500/30 rounded-full mx-auto flex items-center justify-center text-zinc-800 shadow-glow mb-2">
              <UserCircle size={48} />
            </div>
            <div>
              <h2 className="text-xl font-black uppercase italic">{currentUser.name}</h2>
              <p className="text-[9px] text-zinc-600 font-black uppercase tracking-[0.2em]">{isAdmin ? 'Acesso Gestão HPS' : 'Técnico de Oficina'}</p>
            </div>
            <div className="pt-6">
              <button onClick={() => setCurrentUser(null)} className="w-full py-4 bg-zinc-800 text-red-400 font-black uppercase text-xs rounded-2xl active:bg-red-500 active:text-white transition-all">Sair do Sistema</button>
            </div>
          </div>
        )}
      </main>

      {/* Nav Inferior */}
      <nav className="fixed bottom-0 left-0 right-0 bg-black/90 backdrop-blur-2xl border-t border-zinc-800 p-4 flex justify-around items-center z-50">
        <button onClick={() => setActiveTab('dashboard')} className={`flex flex-col items-center gap-1 ${activeTab === 'dashboard' ? 'text-green-500' : 'text-zinc-600'}`}>
          <TrendingUp size={22} /><span className="text-[8px] font-black uppercase">Home</span>
        </button>
        <button onClick={() => setActiveTab('reports')} className={`flex flex-col items-center gap-1 ${activeTab === 'reports' ? 'text-green-500' : 'text-zinc-600'}`}>
          <FileText size={22} /><span className="text-[8px] font-black uppercase">Stock</span>
        </button>
        <button onClick={() => { setScanMode('search'); setIsScanning(true); }} className="w-14 h-14 bg-green-500 rounded-full flex items-center justify-center -mt-10 border-4 border-zinc-950 shadow-glow active:scale-90 transition-transform">
          <QrCode size={26} className="text-black" strokeWidth={3} />
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 ${activeTab === 'history' ? 'text-green-500' : 'text-zinc-600'}`}>
          <History size={22} /><span className="text-[8px] font-black uppercase">Logs</span>
        </button>
        <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center gap-1 ${activeTab === 'profile' ? 'text-green-500' : 'text-zinc-600'}`}>
          <UserCircle size={22} /><span className="text-[8px] font-black uppercase">Conta</span>
        </button>
      </nav>

      {/* MODAL DETALHES DO ITEM */}
      {selectedItemDetails && (
        <div className="fixed inset-0 bg-black/98 z-[150] flex flex-col animate-in fade-in slide-in-from-bottom-5 duration-300">
           <header className="p-6 flex items-center justify-between border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-xl sticky top-0">
             <div className="flex items-center gap-3">
               <Info className="text-green-500" />
               <h3 className="font-black uppercase italic text-sm">Ficha Técnica do Item</h3>
             </div>
             <button onClick={() => setSelectedItemDetails(null)} className="p-3 bg-zinc-800 rounded-2xl active:bg-red-500 transition-all">
               <X size={20} />
             </button>
           </header>

           <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
             {/* Imagem do Item */}
             <div className="w-full aspect-square bg-zinc-900 rounded-[3rem] border-2 border-zinc-800 overflow-hidden shadow-2xl group relative">
               {selectedItemDetails.imageUrl ? (
                 <img src={selectedItemDetails.imageUrl} className="w-full h-full object-cover" />
               ) : (
                 <div className="w-full h-full flex items-center justify-center text-zinc-800">
                   <Package size={80} />
                 </div>
               )}
               <div className="absolute bottom-6 right-6 bg-black/60 backdrop-blur px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest text-green-500">
                 PN: {selectedItemDetails.partNumber}
               </div>
             </div>

             {/* Informações Básicas */}
             <div className="space-y-4">
               <div>
                 <h1 className="text-2xl font-black uppercase italic leading-tight">{selectedItemDetails.name}</h1>
                 <p className="text-[10px] font-black text-zinc-500 uppercase mt-1">Registrado em: {new Date(selectedItemDetails.entryDate).toLocaleDateString('pt-BR')}</p>
               </div>

               <div className="grid grid-cols-2 gap-3">
                 <div className="bg-zinc-900 p-4 rounded-2xl border border-zinc-800">
                   <p className="text-[8px] font-black text-zinc-500 uppercase mb-1">Saldo Atual</p>
                   <p className={`text-xl font-black ${selectedItemDetails.quantity <= selectedItemDetails.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>
                     {selectedItemDetails.quantity} UN
                   </p>
                 </div>
                 <div className="bg-zinc-900 p-4 rounded-2xl border border-zinc-800">
                   <p className="text-[8px] font-black text-zinc-500 uppercase mb-1">Valor Unitário</p>
                   <p className="text-xl font-black text-white">R$ {selectedItemDetails.value.toFixed(2)}</p>
                 </div>
               </div>
             </div>

             {/* Observações */}
             <div className="bg-zinc-900/40 border border-zinc-800 p-6 rounded-[2rem] space-y-3">
               <h4 className="text-[10px] font-black uppercase text-green-500 tracking-widest italic flex items-center gap-2">
                 <FileText size={14} /> Observações HPS
               </h4>
               <p className="text-xs text-zinc-400 font-medium leading-relaxed italic">
                 {selectedItemDetails.observations || "Nenhuma observação cadastrada para este item."}
               </p>
             </div>

             {/* Histórico Local deste Item */}
             <div className="space-y-4 pb-20">
               <h4 className="text-[10px] font-black uppercase text-zinc-500 tracking-widest italic px-2">Histórico de Movimentação</h4>
               <div className="space-y-3">
                 {history.filter(h => h.itemId === selectedItemDetails.id).map(h => (
                   <div key={h.id} className="bg-zinc-900 border border-zinc-800 p-4 rounded-2xl flex justify-between items-center">
                     <div>
                       <p className={`text-[8px] font-black uppercase ${h.type === TransactionType.IN ? 'text-green-500' : 'text-white'}`}>
                         {h.type === TransactionType.IN ? 'Entrada' : 'Saída'} - {h.quantity} UN
                       </p>
                       <p className="text-[7px] text-zinc-600 font-bold mt-1">
                         {new Date(h.date).toLocaleString('pt-BR')} • {h.destination === MovementDestination.OS ? `OS: ${h.osNumber}` : 'Consumo Interno'}
                       </p>
                     </div>
                     <ChevronRight size={14} className="text-zinc-800" />
                   </div>
                 ))}
               </div>
             </div>
           </div>

           {/* Ações de Rodapé no Detalhe */}
           {isAdmin && (
             <div className="p-6 bg-black border-t border-zinc-800 grid grid-cols-2 gap-3">
               <button 
                 onClick={() => {
                   setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.IN });
                 }}
                 className="py-4 bg-green-500 text-black font-black uppercase text-[10px] rounded-2xl shadow-glow active:scale-95 transition-all"
               >
                 Dar Entrada
               </button>
               <button 
                 onClick={() => {
                   setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.OUT });
                 }}
                 className="py-4 bg-white text-black font-black uppercase text-[10px] rounded-2xl shadow-glow active:scale-95 transition-all"
               >
                 Dar Baixa
               </button>
             </div>
           )}
        </div>
      )}

      {/* MODAL ADICIONAR ITEM */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex items-end justify-center backdrop-blur-md overflow-y-auto pt-20">
          <div className="bg-zinc-900 border border-zinc-800 rounded-t-[3rem] w-full max-w-lg shadow-glow animate-in slide-in-from-bottom-20 duration-500">
            <div className="p-8 border-b border-zinc-800 flex justify-between items-center">
              <h3 className="text-lg font-black uppercase italic">Novo Cadastro</h3>
              <button onClick={() => setIsAddingItem(false)} className="p-3 bg-zinc-800 rounded-xl"><X size={20} /></button>
            </div>
            <form onSubmit={handleAddItem} className="p-8 space-y-4">
              <div className="flex flex-col items-center mb-4">
                <div 
                  onClick={() => itemImageInputRef.current?.click()}
                  className="w-28 h-28 bg-black border-2 border-dashed border-zinc-800 rounded-2xl flex items-center justify-center text-zinc-700 relative group overflow-hidden cursor-pointer shadow-glow"
                >
                  {formData.imageUrl ? (
                    <img src={formData.imageUrl} className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center">
                      <Upload size={24} />
                      <span className="text-[7px] font-black uppercase mt-1">Foto da Peça</span>
                    </div>
                  )}
                </div>
                <input 
                  type="file" 
                  ref={itemImageInputRef} 
                  accept="image/*" 
                  capture="environment" 
                  className="hidden" 
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleImageFile(file, (base64) => setFormData({...formData, imageUrl: base64}));
                  }}
                />
              </div>

              <input required type="text" placeholder="DESCRIÇÃO / NOME DA PEÇA" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-3">
                <input required type="text" placeholder="PART NUMBER" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                <input required type="number" step="0.01" placeholder="VALOR UNIT." className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-green-500 font-black text-[11px]" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
              </div>

              <textarea 
                placeholder="OBSERVAÇÕES TÉCNICAS..." 
                className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-zinc-400 font-bold text-[10px] h-20 resize-none outline-none"
                value={formData.observations}
                onChange={e => setFormData({...formData, observations: e.target.value})}
              />

              <div className="bg-black border border-zinc-800 p-5 rounded-2xl space-y-3">
                <p className="text-[8px] font-black uppercase text-zinc-500 italic">Vínculo de Segurança QR</p>
                <div className="flex gap-2">
                  <div className="flex-1 bg-zinc-900 border border-zinc-800 p-3 rounded-xl text-[10px] font-black text-green-500 truncate">
                    {formData.linkedQRCode || "Nenhum Código Lido"}
                  </div>
                  <button type="button" onClick={() => { setScanMode('bind'); setIsScanning(true); }} className="bg-green-500 text-black px-4 py-2 rounded-xl font-black text-[10px] uppercase shadow-glow active:scale-95 transition-all">
                    Ler QR
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <input required type="number" placeholder="SALDO INICIAL" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                <input required type="number" placeholder="ESTOQUE MÍN." className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-[11px]" value={formData.minQuantity || ''} onChange={e => setFormData({...formData, minQuantity: parseInt(e.target.value) || 0})} />
              </div>
              <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-all">Finalizar Registro</button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL MOVIMENTAÇÃO */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[200] flex items-center justify-center p-6 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] w-full max-w-xs shadow-glow">
            <div className={`p-6 rounded-t-[2.5rem] flex items-center gap-4 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
               {movementModal.type === TransactionType.IN ? <Plus size={24} strokeWidth={3} /> : <LogOut size={24} className="rotate-180" strokeWidth={3} />}
               <h3 className="text-lg font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Baixa'}</h3>
            </div>
            <div className="p-8 space-y-6">
               <div className="space-y-1">
                 <p className="text-[8px] font-black uppercase text-zinc-500 text-center">Quantidade</p>
                 <input type="number" className="w-full bg-zinc-950 border border-zinc-800 p-6 rounded-2xl text-4xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
               </div>

               {movementModal.type === TransactionType.OUT && (
                 <div className="space-y-4">
                   <div className="grid grid-cols-2 gap-2">
                     <button 
                        type="button"
                        onClick={() => setDestination(MovementDestination.OS)}
                        className={`py-3 rounded-xl flex flex-col items-center gap-1 border transition-all ${destination === MovementDestination.OS ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-zinc-800 border-zinc-700 text-zinc-600'}`}
                     >
                       <Wrench size={16} />
                       <span className="text-[8px] font-black uppercase">Ordem de Serviço</span>
                     </button>
                     <button 
                        type="button"
                        onClick={() => setDestination(MovementDestination.INTERNAL)}
                        className={`py-3 rounded-xl flex flex-col items-center gap-1 border transition-all ${destination === MovementDestination.INTERNAL ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-zinc-800 border-zinc-700 text-zinc-600'}`}
                     >
                       <Factory size={16} />
                       <span className="text-[8px] font-black uppercase">Consumo Oficina</span>
                     </button>
                   </div>

                   {destination === MovementDestination.OS && (
                     <input 
                        type="text" 
                        placeholder="NÚMERO DA OS" 
                        className="w-full bg-zinc-800 p-4 rounded-xl text-white font-black text-[10px] uppercase outline-none border border-zinc-700 focus:border-green-500/50" 
                        value={osNumber} 
                        onChange={e => setOsNumber(e.target.value)} 
                     />
                   )}

                   <select className="w-full bg-zinc-800 p-4 rounded-xl text-white font-black text-[10px] uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                     <option value="">SELECIONE O TÉCNICO...</option>
                     {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                   </select>
                 </div>
               )}

               <div className="flex gap-2">
                 <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-4 bg-zinc-800 text-zinc-500 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
                 <button onClick={() => processMovement()} className={`flex-[2] py-4 font-black rounded-xl uppercase text-[9px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* SCANNER COMPONENT */}
      {isScanning && (
        <QRScanner 
          onScan={handleQRScan} 
          onClose={() => { setIsScanning(false); setTargetItemForValidation(null); }} 
        />
      )}
    </div>
  );
};

export default App;

