                  }}
                />
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-zinc-500 uppercase px-1">Descrição Comercial</label>
                <input required type="text" placeholder="Ex: Pastilha de Freio Carbon..." className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-xs" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase px-1">Part Number</label>
                  <input required type="text" placeholder="Código Fábrica" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-xs" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase px-1">Valor R$ (Unitário)</label>
                  <input required type="number" step="0.01" placeholder="0,00" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-green-500 font-black text-xs" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-zinc-500 uppercase px-1">Observações Técnicas</label>
                <textarea placeholder="Informações adicionais da peça..." className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-zinc-400 font-bold text-[11px] h-24 resize-none outline-none" value={formData.observations} onChange={e => setFormData({...formData, observations: e.target.value})} />
              </div>

              <div className="bg-black border border-zinc-800 p-6 rounded-[2rem] space-y-4">
                <p className="text-[9px] font-black uppercase text-zinc-500 italic tracking-widest text-center">Vínculo de Segurança QR</p>
                <div className="flex gap-3">
                  <div className="flex-1 bg-zinc-900 border border-zinc-800 p-4 rounded-xl text-[10px] font-black text-green-500 truncate shadow-inner">
                    {formData.linkedQRCode || "NENHUM QR VINCULADO"}
                  </div>
                  <button type="button" onClick={() => { setScanMode('bind'); setIsScanning(true); }} className="bg-green-500 text-black px-6 py-4 rounded-xl font-black text-[10px] uppercase shadow-glow active:scale-95 transition-all">
                    Ler QR
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase px-1">Saldo em Estoque</label>
                  <input required type="number" placeholder="Saldo Inicial" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-xs" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-500 uppercase px-1">Estoque Crítico</label>
                  <input required type="number" placeholder="Limite Mínimo" className="w-full bg-black border border-zinc-800 p-4 rounded-xl text-white font-black text-xs" value={formData.minQuantity || ''} onChange={e => setFormData({...formData, minQuantity: parseInt(e.target.value) || 0})} />
                </div>
              </div>
              <button type="submit" className="w-full py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2rem] shadow-glow active:scale-95 transition-all mt-4">Gravar no Inventário HPS</button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL MOVIMENTAÇÃO */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-center justify-center p-6 backdrop-blur-3xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3rem] w-full max-w-sm shadow-[0_20px_60px_rgba(0,0,0,0.8)] border-white/5">
            <div className={`p-8 rounded-t-[3rem] flex items-center gap-5 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
               <div className="p-4 bg-black/10 rounded-2xl">
                 {movementModal.type === TransactionType.IN ? <Plus size={32} strokeWidth={4} /> : <LogOut size={32} className="rotate-180" strokeWidth={4} />}
               </div>
               <h3 className="text-2xl font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Baixa'}</h3>
            </div>
            <div className="p-10 space-y-8">
               <div className="space-y-2 text-center">
                 <p className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.3em]">Quantidade Operação</p>
                 <input type="number" className="w-full bg-transparent p-4 text-6xl font-black text-center text-green-500 outline-none placeholder-zinc-800" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
               </div>

               {movementModal.type === TransactionType.OUT && (
                 <div className="space-y-5 animate-in slide-in-from-bottom-2">
                   <div className="grid grid-cols-2 gap-3">
                     <button type="button" onClick={() => setDestination(MovementDestination.OS)} className={`py-4 rounded-2xl flex flex-col items-center gap-1 border transition-all ${destination === MovementDestination.OS ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-black border-zinc-800 text-zinc-600'}`}>
                       <Wrench size={18} />
                       <span className="text-[9px] font-black uppercase">Ordem Serviço</span>
                     </button>
                     <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-4 rounded-2xl flex flex-col items-center gap-1 border transition-all ${destination === MovementDestination.INTERNAL ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-black border-zinc-800 text-zinc-600'}`}>
                       <Factory size={18} />
                       <span className="text-[9px] font-black uppercase">Consumo Oficina</span>
                     </button>
                   </div>

                   {destination === MovementDestination.OS && (
                     <input type="text" placeholder="DIGITE O NÚMERO DA OS" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none focus:border-green-500/50" value={osNumber} onChange={e => setOsNumber(e.target.value)} />
                   )}

                   <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                     <option value="">PROFISSIONAL DESTINO...</option>
                     {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                   </select>
                 </div>
               )}

               <div className="flex gap-3">
                 <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-5 bg-zinc-800 text-zinc-500 font-black rounded-2xl uppercase text-[10px] active:scale-95 transition-all">Voltar</button>
                 <button onClick={() => processMovement()} className={`flex-[2] py-5 font-black rounded-2xl uppercase text-[10px] shadow-glow active:scale-95 transition-all ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Concluir</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* COMPONENTE DE SCANNER */}
      {isScanning && (
        <QRScanner onScan={handleQRScan} onClose={() => { setIsScanning(false); setTargetItemForValidation(null); }} />
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  STOCKIST = 'STOCKIST', // Acesso Total (Gerenciamento)
  MECHANIC = 'MECHANIC'  // Acesso Limitado (Apenas retirada destinada)
}

export enum ItemCategory {
  FREIOS = 'Freios',
  MOTOR = 'Motor',
  TRANSMISSAO = 'Transmissão e câmbio',
  RODAS = 'Rodas e pneus',
  INSUMOS = 'Insumos',
  ELETRICA = 'Elétrica e eletrônicos'
}

export interface User {
  id: string;
  username: string;
  password?: string;
  email?: string;
  name: string;
  role: UserRole;
  avatarUrl?: string;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  minQuantity: number;
  category: ItemCategory;
  entryDate: string;
  linkedQRCode?: string;
  description?: string;
  imageUrl?: string;
  observations?: string;
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export enum MovementDestination {
  OS = 'OS',
  INTERNAL = 'INTERNAL'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string;
  notes?: string;
  destination?: MovementDestination;
  osNumber?: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, Upload, 
  Camera, Save, Mail, CheckCircle2, Globe, ShieldAlert, Check,
  ChevronRight, Smartphone, Eye, Info, Wrench, Factory, Filter,
  Users, Key, ShieldCheck, Trash2, Layers, Tag
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';

const CATEGORIES = Object.values(ItemCategory);

type ActiveTab = 'dashboard' | 'history' | 'reports' | 'profile' | 'access_manager';
type AuthView = 'login' | 'signup' | 'forgot';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => {
  return (
    <div className="flex flex-col items-center select-none">
      <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
        <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  // --- ESTADO DE DADOS ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- ESTADO DE INTERFACE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [stockCategoryFilter, setStockCategoryFilter] = useState<ItemCategory | 'TODOS'>('TODOS');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [targetItemForValidation, setTargetItemForValidation] = useState<InventoryItem | null>(null);
  const [selectedItemDetails, setSelectedItemDetails] = useState<InventoryItem | null>(null);

  // --- ESTADOS DE FORMULÁRIO ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', email: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  const itemImageInputRef = useRef<HTMLInputElement>(null);

  // --- CARREGAMENTO INICIAL E PERSISTÊNCIA ---
  useEffect(() => {
    const savedUsers = localStorage.getItem('hps_vault_users_v4');
    const savedItems = localStorage.getItem('hps_vault_items_v4');
    const savedHistory = localStorage.getItem('hps_vault_history_v4');
    const savedSession = localStorage.getItem('hps_vault_session_v4');

    if (savedUsers) setUsers(JSON.parse(savedUsers));
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedSession) setCurrentUser(JSON.parse(savedSession));
  }, []);

  useEffect(() => {
    if (users.length > 0) localStorage.setItem('hps_vault_users_v4', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('hps_vault_items_v4', JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem('hps_vault_history_v4', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('hps_vault_session_v4', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('hps_vault_session_v4');
    }
  }, [currentUser]);

  // --- FUNÇÕES DE AUTENTICAÇÃO ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const normalizedUser = loginForm.username.trim().toLowerCase();
    const user = users.find(u => u.username.toLowerCase() === normalizedUser && u.password === loginForm.password);

    if (user) {
      setCurrentUser(user);
      setLoginForm({ username: '', password: '' });
    } else {
      alert("ACESSO NEGADO: Verifique seu login e senha no cofre.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    const normalizedUser = signupForm.username.trim().toLowerCase();
    if (users.some(u => u.username.toLowerCase() === normalizedUser)) {
      alert("Login já existente.");
      return;
    }
    const newUser: User = { 
      id: Math.random().toString(36).substr(2, 9), 
      ...signupForm,
      username: normalizedUser
    };
    setUsers(prev => [...prev, newUser]);
    alert("CADASTRADO: Seus dados foram salvos com sucesso.");
    setAuthView('login');
  };

  const handleLogout = () => {
    if (window.confirm("Deseja realmente encerrar a sessão de trabalho?")) {
      setCurrentUser(null);
      setActiveTab('dashboard');
    }
  };

  // --- GESTÃO DE ESTOQUE ---
  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { 
      id: Math.random().toString(36).substr(2, 9), 
      ...formData, 
      entryDate: new Date().toISOString() 
    };

    setItems(prev => [newItem, ...prev]);
    setHistory(prev => [{
      id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name,
      type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'DEPÓSITO', notes: `Entrada inicial em ${formData.category}`
    }, ...prev]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setTargetItemForValidation(item);
      setScanMode('validate');
      setIsScanning(true);
      return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Saldo insuficiente para esta saída.");
      return;
    }

    setItems(prev => prev.map(i => {
      if (i.id === item.id) {
        return { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) };
      }
      return i;
    }));

    setHistory(prev => [{
      id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name,
      type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', 
      destination: movementModal.type === TransactionType.OUT ? destination : undefined,
      osNumber: movementModal.type === TransactionType.OUT && destination === MovementDestination.OS ? osNumber : undefined
    }, ...prev]);

    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setOsNumber('');
  };

  const handleQRScan = (decodedText: string) => {
    setIsScanning(false);
    if (scanMode === 'bind') {
      setFormData({ ...formData, linkedQRCode: decodedText });
      return;
    }
    if (scanMode === 'validate') {
      if (targetItemForValidation?.linkedQRCode === decodedText) {
        processMovement(true);
      } else {
        alert("QR CODE INVÁLIDO: Esta peça não corresponde ao registro.");
      }
      setTargetItemForValidation(null);
      return;
    }
    const item = items.find(i => i.linkedQRCode === decodedText || i.partNumber === decodedText);
    if (item) setSelectedItemDetails(item);
    else alert("ITEM NÃO ENCONTRADO.");
  };

  const filteredItems = items.filter(i => 
    (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())) &&
    (stockCategoryFilter === 'TODOS' || i.category === stockCategoryFilter)
  );

  const isAdmin = currentUser?.role === UserRole.STOCKIST;

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center p-6 font-sans selection:bg-green-500 selection:text-black">
        <div className="w-full max-w-md space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center space-y-2">
            <div className="inline-flex p-4 bg-green-500/10 rounded-full text-green-500 mb-4 shadow-[0_0_30px_rgba(34,197,94,0.15)]">
              <ShieldCheck size={48} />
            </div>
            <h1 className="text-3xl font-black text-white tracking-tighter uppercase italic">HPS <span className="text-green-500">CONTROL</span></h1>
            <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-[0.4em]">Controle de Estoque e Insumos</p>
          </div>

          <div className="bg-zinc-900 border border-zinc-800 p-10 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
            {authView === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-5">
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-all">Entrar no Sistema</button>
                <button type="button" onClick={() => setAuthView('signup')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Criar acesso pela primeira vez</button>
              </form>
            ) : (
              <form onSubmit={handleSignup} className="space-y-4">
                <input required type="text" placeholder="NOME COMPLETO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} />
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} />
                <select className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
                  <option value={UserRole.MECHANIC}>Mecânico</option>
                  <option value={UserRole.STOCKIST}>Estoquista</option>
                </select>
                <button type="submit" className="w-full py-5 bg-white text-black font-black uppercase text-xs rounded-2xl shadow-xl active:scale-95 transition-all">Salvar Acesso</button>
                <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Voltar para Login</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-[#050505] text-zinc-100 font-sans pb-24 selection:bg-green-500 selection:text-black overflow-x-hidden">
      {/* Header HPS */}
      <header className="bg-black/90 backdrop-blur-2xl border-b border-zinc-800 px-6 py-4 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <HPSLogo size="sm" />
          <div className="hidden sm:flex flex-col border-l border-zinc-800 pl-4">
            <span className="text-[9px] font-black text-green-500 uppercase tracking-tighter">OPERADOR</span>
            <span className="text-xs font-bold text-zinc-300 uppercase truncate max-w-[120px]">{currentUser.name}</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <a href="https://epc.brp.com/#" target="_blank" className="p-3 bg-zinc-900 border border-zinc-800 rounded-xl text-green-500 hover:bg-green-500 hover:text-black transition-all active:scale-90">
            <Globe size={18} />
          </a>
          {isAdmin && (
            <button onClick={() => setIsAddingItem(true)} className="p-3 bg-green-500 text-black rounded-xl shadow-glow active:scale-90 transition-all">
              <Plus size={18} strokeWidth={3} />
            </button>
          )}
          <button onClick={handleLogout} className="p-3 bg-zinc-800 border border-zinc-700 text-red-400 rounded-xl active:scale-90 transition-all hover:bg-red-500 hover:text-white">
            <LogOut size={18} />
          </button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 md:p-6 space-y-8 animate-in fade-in duration-500">
        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            {/* KPI Cards Relex Style */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              <div className="bg-zinc-900/50 border border-zinc-800 p-5 rounded-[2rem] hover:border-zinc-700 transition-all group">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1 tracking-widest">Saldo Total</p>
                <div className="flex items-end justify-between">
                  <p className="text-3xl font-black text-white">{items.length}</p>
                  <Package size={16} className="text-zinc-700 group-hover:text-green-500 transition-colors mb-1" />
                </div>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-5 rounded-[2rem] hover:border-zinc-700 transition-all group">
