                  {selectedItemDetails.linkedQRCode && (
                    <div className="bg-green-500/90 backdrop-blur-xl p-3 rounded-2xl text-black shadow-2xl">
                      <QrCode size={18} strokeWidth={3} />
                    </div>
                  )}
               </div>
             </div>

             <div className="space-y-6">
               <div className="space-y-2">
                 <h1 className="text-4xl font-black uppercase italic leading-[0.9] text-white tracking-tighter">{selectedItemDetails.name}</h1>
                 <p className="text-[9px] font-black text-zinc-600 uppercase mt-2 tracking-[0.4em] italic">Registro Operacional: {new Date(selectedItemDetails.entryDate).toLocaleDateString('pt-BR')}</p>
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div className="bg-zinc-900 border border-zinc-800 p-7 rounded-[2.5rem]">
                   <p className="text-[9px] font-black text-zinc-500 uppercase mb-3 tracking-widest">Saldo Físico</p>
                   <p className={`text-4xl font-black ${selectedItemDetails.quantity <= selectedItemDetails.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>
                     {selectedItemDetails.quantity} <span className="text-xs uppercase opacity-30">un</span>
                   </p>
                 </div>
                 <div className="bg-zinc-900 border border-zinc-800 p-7 rounded-[2.5rem]">
                   <p className="text-[9px] font-black text-zinc-500 uppercase mb-3 tracking-widest">Patrimonial</p>
                   <p className="text-2xl font-black text-white leading-none">R$ {selectedItemDetails.value.toFixed(2)}<br/><span className="text-[10px] opacity-40 uppercase">por unidade</span></p>
                 </div>
               </div>
             </div>

             <div className="bg-zinc-900/50 border border-zinc-800 p-8 rounded-[3rem] space-y-4 shadow-inner">
               <h4 className="text-[10px] font-black uppercase text-green-500 tracking-widest italic flex items-center gap-3">
                 <Info size={16} /> Ficha Técnica HPS
               </h4>
               <p className="text-xs text-zinc-400 font-bold leading-relaxed italic border-l-2 border-zinc-800 pl-4 py-1">
                 {selectedItemDetails.observations || "Nenhum detalhe técnico específico cadastrado para este lote."}
               </p>
             </div>

             <div className="space-y-4">
                <h4 className="text-[10px] font-black uppercase text-zinc-600 tracking-widest italic px-4">Rastreio de Lote</h4>
                <div className="space-y-3">
                  {history.filter(h => h.itemId === selectedItemDetails.id).slice(0, 5).map(h => (
                    <div key={h.id} className="bg-zinc-900 border border-zinc-800/50 p-6 rounded-[2rem] flex justify-between items-center group">
                      <div className="flex items-center gap-4">
                         <div className={`w-2 h-2 rounded-full shadow-[0_0_8px] ${h.type === TransactionType.IN ? 'bg-green-500 shadow-green-500/50' : 'bg-white shadow-white/50'}`}></div>
                         <div>
                            <p className={`text-[11px] font-black uppercase ${h.type === TransactionType.IN ? 'text-green-500' : 'text-white'}`}>
                              {h.type === TransactionType.IN ? 'Entrada de Estoque' : 'Baixa / Destinação'}
                            </p>
                            <p className="text-[8px] text-zinc-600 font-bold uppercase mt-1">
                              {new Date(h.date).toLocaleDateString('pt-BR')} • {h.destination === MovementDestination.OS ? `OS #${h.osNumber}` : 'Interno'}
                            </p>
                         </div>
                      </div>
                      <span className="text-lg font-black text-zinc-200">{h.type === TransactionType.IN ? '+' : '-'}{h.quantity}</span>
                    </div>
                  ))}
                </div>
             </div>
           </div>

           {isAdmin && (
             <div className="p-8 bg-black border-t border-zinc-800 grid grid-cols-2 gap-5 sticky bottom-0 z-20">
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.IN })} className="py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2rem] shadow-glow active:scale-95 transition-all">Entrada</button>
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.OUT })} className="py-6 bg-white text-black font-black uppercase text-xs rounded-[2rem] shadow-xl active:scale-95 transition-all">Baixa</button>
             </div>
           )}
        </div>
      )}

      {isScanning && (
        <QRScanner onScan={handleQRScan} onClose={() => { setIsScanning(false); setTargetItemForValidation(null); }} />
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  STOCKIST = 'STOCKIST', 
  MECHANIC = 'MECHANIC'
}

export enum ItemCategory {
  FREIOS = 'Freios',
  MOTOR = 'Motor',
  TRANSMISSAO = 'Transmissão e câmbio',
  RODAS = 'Rodas e pneus',
  INSUMOS = 'Insumos',
  ELETRICA = 'Elétrica e eletrônicos'
}

export interface User {
  id: string;
  username: string;
  password?: string;
  email?: string;
  name: string;
  role: UserRole;
  avatarUrl?: string;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  minQuantity: number;
  category: ItemCategory;
  boxNumber: string; // Identificação física (Caixa 01, Gaveta B, etc)
  entryDate: string;
  linkedQRCode?: string;
  description?: string;
  imageUrl?: string;
  observations?: string;
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export enum MovementDestination {
  OS = 'OS',
  INTERNAL = 'INTERNAL'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string;
  notes?: string;
  destination?: MovementDestination;
  osNumber?: string;
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, Upload, 
  Camera, Globe, ShieldCheck, ChevronRight, Smartphone, Eye, 
  Info, Wrench, Factory, Filter, Key, Trash2, Layers, Tag, Box
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';

const CATEGORIES = Object.values(ItemCategory);

type ActiveTab = 'dashboard' | 'history' | 'reports' | 'profile' | 'access_manager';
type AuthView = 'login' | 'signup';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => (
  <div className="flex flex-col items-center select-none">
    <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
      <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
    </div>
  </div>
);

const App: React.FC = () => {
  // --- DATABASE ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [stockCategoryFilter, setStockCategoryFilter] = useState<ItemCategory | 'TODOS'>('TODOS');
  const [stockBoxFilter, setStockBoxFilter] = useState<string>('TODAS');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [targetItemForValidation, setTargetItemForValidation] = useState<InventoryItem | null>(null);
  const [selectedItemDetails, setSelectedItemDetails] = useState<InventoryItem | null>(null);

  // --- FORM STATES ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  const itemImageInputRef = useRef<HTMLInputElement>(null);

  // --- PERSISTENCE ---
  useEffect(() => {
    const savedUsers = localStorage.getItem('hps_v5_users');
    const savedItems = localStorage.getItem('hps_v5_items');
    const savedHistory = localStorage.getItem('hps_v5_history');
    const savedSession = localStorage.getItem('hps_v5_session');

    if (savedUsers) setUsers(JSON.parse(savedUsers));
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedSession) setCurrentUser(JSON.parse(savedSession));
  }, []);

  useEffect(() => {
    if (users.length > 0) localStorage.setItem('hps_v5_users', JSON.stringify(users));
    localStorage.setItem('hps_v5_items', JSON.stringify(items));
    localStorage.setItem('hps_v5_history', JSON.stringify(history));
    if (currentUser) localStorage.setItem('hps_v5_session', JSON.stringify(currentUser));
    else localStorage.removeItem('hps_v5_session');
  }, [users, items, history, currentUser]);

  // --- ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
    } else {
      alert("Usuário ou senha inválidos.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === signupForm.username.toLowerCase())) {
      alert("Nome de usuário já cadastrado."); return;
    }
    const newUser = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers([...users, newUser]);
    alert("Usuário registrado no cofre.");
    setAuthView('login');
  };

  const handleLogout = () => {
    if (window.confirm("Encerrar sessão de trabalho?")) {
      setCurrentUser(null);
      setActiveTab('dashboard');
    }
  };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.boxNumber) { alert("Informe a Caixa de Destino."); return; }

    const newItem: InventoryItem = { 
      id: Math.random().toString(36).substr(2, 9), 
      ...formData, 
      entryDate: new Date().toISOString() 
    };

    setItems([newItem, ...items]);
    setHistory([{
      id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name,
      type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'ESTOQUE', notes: `Alocado na ${formData.boxNumber}`
    }, ...history]);

    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setTargetItemForValidation(item);
      setScanMode('validate');
      setIsScanning(true);
      return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Quantidade maior que o saldo disponível."); return;
    }

    setItems(items.map(i => i.id === item.id ? { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) } : i));

    setHistory([{
      id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name,
      type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', 
      destination: movementModal.type === TransactionType.OUT ? destination : undefined,
      osNumber: movementModal.type === TransactionType.OUT && destination === MovementDestination.OS ? osNumber : undefined
    }, ...history]);

    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setOsNumber('');
  };

  const handleQRScan = (decodedText: string) => {
    setIsScanning(false);
    if (scanMode === 'bind') { setFormData({...formData, linkedQRCode: decodedText}); return; }
    if (scanMode === 'validate') {
      if (targetItemForValidation?.linkedQRCode === decodedText) processMovement(true);
      else alert("Erro: QR Code não compatível com o item.");
      setTargetItemForValidation(null);
      return;
    }
    const item = items.find(i => i.linkedQRCode === decodedText || i.partNumber === decodedText);
    if (item) setSelectedItemDetails(item);
    else alert("Peça não localizada.");
  };

  // --- FILTERS LOGIC ---
  const availableBoxes = useMemo(() => {
    const boxes = items
      .filter(i => stockCategoryFilter === 'TODOS' || i.category === stockCategoryFilter)
      .map(i => i.boxNumber);
    return Array.from(new Set(boxes)).sort();
  }, [items, stockCategoryFilter]);

  const filteredItems = useMemo(() => {
    return items.filter(i => 
      (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())) &&
      (stockCategoryFilter === 'TODOS' || i.category === stockCategoryFilter) &&
      (stockBoxFilter === 'TODAS' || i.boxNumber === stockBoxFilter)
    );
  }, [items, searchTerm, stockCategoryFilter, stockBoxFilter]);

  const isAdmin = currentUser?.role === UserRole.STOCKIST;

  // --- AUTH RENDER ---
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6 sm:p-12">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center">
            <HPSLogo size="lg" />
            <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.4em] mt-4">Controle de Estoque e Insumos</p>
          </div>
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-2xl">
            {authView === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-transform">Acessar Sistema</button>
                <button type="button" onClick={() => setAuthView('signup')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Primeiro acesso? Cadastre-se</button>
              </form>
            ) : (
              <form onSubmit={handleSignup} className="space-y-4">
                <input required type="text" placeholder="NOME COMPLETO" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} />
                <input required type="text" placeholder="USUÁRIO (LOGIN)" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} />
                <input required type="password" placeholder="CRIE UMA SENHA" className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} />
                <select className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
                  <option value={UserRole.MECHANIC}>Oficina (Mecânico)</option>
                  <option value={UserRole.STOCKIST}>Estoque (Gestor)</option>
                </select>
                <button type="submit" className="w-full py-5 bg-white text-black font-black uppercase text-xs rounded-2xl shadow-xl active:scale-95 transition-transform">Salvar Credenciais</button>
                <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Voltar para Login</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  // --- APP RENDER ---
  return (
    <div className="min-h-screen flex flex-col bg-zinc-950 text-zinc-100 font-sans pb-24 lg:pb-0 lg:pl-20">

      {/* Desktop Sidebar / Mobile Top Bar */}
      <header className="bg-black/95 backdrop-blur-xl border-b lg:border-r lg:border-b-0 border-zinc-800 px-6 py-4 lg:py-8 lg:px-4 flex lg:flex-col items-center justify-between lg:justify-start lg:gap-8 fixed top-0 lg:left-0 lg:bottom-0 w-full lg:w-20 z-50 transition-all">
        <HPSLogo size="sm" />
        <div className="hidden lg:flex flex-col gap-6 items-center pt-10">
           <button onClick={() => setActiveTab('dashboard')} className={`p-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-500 hover:text-white'}`}><TrendingUp size={24} /></button>
           <button onClick={() => setActiveTab('reports')} className={`p-3 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-500 hover:text-white'}`}><Layers size={24} /></button>
           <button onClick={() => setActiveTab('history')} className={`p-3 rounded-xl transition-all ${activeTab === 'history' ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-500 hover:text-white'}`}><History size={24} /></button>
           <button onClick={() => setActiveTab('profile')} className={`p-3 rounded-xl transition-all ${activeTab === 'profile' ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-500 hover:text-white'}`}><UserCircle size={24} /></button>
        </div>
        <div className="flex items-center gap-2 lg:mt-auto">
          {isAdmin && <button onClick={() => setIsAddingItem(true)} className="p-3 bg-green-500 text-black rounded-xl lg:rounded-2xl shadow-glow active:scale-90 transition-all"><Plus size={20} strokeWidth={3} /></button>}
          <button onClick={handleLogout} className="p-3 bg-zinc-800 border border-zinc-700 text-red-400 rounded-xl active:scale-90 transition-all hover:bg-red-500 hover:text-white"><LogOut size={20} /></button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full p-4 sm:p-8 pt-20 lg:pt-8 space-y-8">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem]">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1 tracking-widest">Saldo Total</p>
                <p className="text-3xl font-black text-white">{items.length}</p>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem]">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1 tracking-widest">Alertas Críticos</p>
                <p className="text-3xl font-black text-amber-500">{items.filter(i => i.quantity <= i.minQuantity).length}</p>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem] hidden md:block">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1 tracking-widest">Itens na Oficina</p>
                <p className="text-3xl font-black text-green-500">{history.filter(h => h.type === TransactionType.OUT).length}</p>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem] hidden md:block">
                <p className="text-[8px] text-zinc-500 uppercase font-black mb-1 tracking-widest">Patrimônio</p>
                <p className="text-lg font-black text-white">R$ {items.reduce((acc, i) => acc + (i.value * i.quantity), 0).toLocaleString('pt-BR')}</p>
              </div>
            </div>

            <div className="space-y-4">
               <div className="relative group">
                  <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-zinc-600 group-focus-within:text-green-500 transition-colors" size={20} />
                  <input type="text" placeholder="Pesquisar por Nome, PN ou Código..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-zinc-900 border border-zinc-800 pl-14 pr-6 py-5 rounded-[2rem] font-bold text-sm outline-none focus:border-green-500/30 shadow-xl transition-all" />
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {filteredItems.slice(0, 15).map(item => (
                <div key={item.id} onClick={() => setSelectedItemDetails(item)} className="bg-zinc-900/30 border border-zinc-800/50 p-5 rounded-[2.5rem] flex items-center gap-5 group hover:bg-zinc-900/60 transition-all cursor-pointer">
                  <div className="w-16 h-16 bg-black rounded-3xl flex items-center justify-center border border-zinc-800 overflow-hidden shrink-0">
                    {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={24} />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className="font-black text-xs uppercase italic truncate text-zinc-100">{item.name}</h4>
                    <div className="flex items-center gap-2 mt-1">
                      <Box size={10} className="text-green-500" />
                      <span className="text-[8px] text-zinc-500 font-black uppercase tracking-widest">{item.boxNumber}</span>
                    </div>
                    <div className="flex items-center gap-2 mt-3">
                      <div className={`px-2 py-0.5 rounded-lg text-[8px] font-black ${item.quantity <= item.minQuantity ? 'bg-amber-500 text-black' : 'bg-zinc-800 text-zinc-400'}`}>{item.quantity} UN</div>
                      <span className="text-[8px] text-zinc-700 font-bold">PN: {item.partNumber}</span>
                    </div>
                  </div>
                  <ChevronRight size={18} className="text-zinc-800 group-hover:text-green-500 transition-colors" />
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
           <div className="space-y-6 animate-in slide-in-from-bottom-5">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 px-2">
                <h2 className="text-xl font-black uppercase italic tracking-widest">Stock Central</h2>

                {/* Advanced Filtering Drill-down */}
                <div className="flex flex-wrap gap-2 items-center">
                   <select className="bg-zinc-900 border border-zinc-800 p-3 rounded-xl text-[10px] font-black uppercase text-green-500 outline-none" value={stockCategoryFilter} onChange={e => {setStockCategoryFilter(e.target.value as ItemCategory | 'TODOS'); setStockBoxFilter('TODAS');}}>
                     <option value="TODOS">TODOS OS GRUPOS</option>
