                            <span className="text-zinc-100 uppercase italic font-black">{item.name}</span><br/>
                            <span className="text-[9px] text-zinc-600">PN: {item.partNumber} • {item.category}</span>
                          </td>
                          <td className="p-6 text-center">
                             <span className="px-3 py-1 bg-black rounded-lg text-[9px] text-green-500 font-black border border-zinc-800">{item.boxNumber}</span>
                          </td>
                          <td className={`p-6 text-center font-black ${item.quantity <= item.minQuantity ? 'text-amber-500' : 'text-zinc-200'}`}>
                            {item.quantity} un
                          </td>
                          <td className="p-6 text-right">
                             <button onClick={() => setSelectedItemDetails(item)} className="p-2 bg-zinc-800 rounded-lg text-zinc-500 hover:text-green-500 transition-colors"><Eye size={16} /></button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {filteredItems.length === 0 && <div className="p-20 text-center opacity-40 font-black uppercase text-[10px]">Nenhum item alocado nestas condições.</div>}
                </div>
              </div>
           </div>
        )}

        {activeTab === 'history' && <TransactionHistory transactions={history.filter(h => isAdmin || h.recipientName === currentUser.name)} />}

        {activeTab === 'profile' && (
          <div className="bg-zinc-900 border border-zinc-800 p-12 rounded-[3.5rem] space-y-10 text-center max-w-sm mx-auto shadow-2xl animate-in slide-in-from-bottom-10">
            <div className="relative inline-block">
               <div className="w-28 h-28 bg-black border-4 border-green-500/20 rounded-full mx-auto flex items-center justify-center text-zinc-800 shadow-glow overflow-hidden">
                 <UserCircle size={64} />
               </div>
               <div className="absolute -bottom-1 -right-1 bg-green-500 p-2.5 rounded-full text-black border-4 border-zinc-900 shadow-xl"><ShieldCheck size={18} strokeWidth={3} /></div>
            </div>
            <div>
              <h2 className="text-2xl font-black uppercase italic tracking-tighter text-white">{currentUser.name}</h2>
