          <TrendingUp size={24} /><span className="text-[8px] font-black uppercase tracking-widest">Painel</span>
        </button>
        <button onClick={() => setActiveTab('reports')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'reports' ? 'text-green-500 scale-110' : 'text-zinc-600'}`}>
