        <button onClick={() => { setScanMode('search'); setIsScanning(true); }} className="w-16 h-16 bg-green-500 rounded-[1.8rem] flex items-center justify-center -mt-12 border-4 border-zinc-950 shadow-glow active:scale-90 transition-all">
          <QrCode size={30} className="text-black" strokeWidth={3} />
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'history' ? 'text-green-500 scale-110' : 'text-zinc-600'}`}>
          <History size={24} /><span className="text-[8px] font-black uppercase tracking-widest">Logs</span>
        </button>
        <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'profile' ? 'text-green-500 scale-110' : 'text-zinc-600'}`}>
          <UserCircle size={24} /><span className="text-[8px] font-black uppercase tracking-widest">Conta</span>
