            <div className="p-8 border-b border-zinc-800 flex justify-between items-center">
              <h3 className="text-xl font-black uppercase italic tracking-tighter">Entrada de Peça</h3>
              <button onClick={() => setIsAddingItem(false)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500 hover:text-white transition-all"><X size={22} /></button>
            </div>
            <form onSubmit={handleAddItem} className="p-8 space-y-6">
              <div className="flex flex-col items-center">
                <div onClick={() => itemImageInputRef.current?.click()} className="w-36 h-36 bg-black border-2 border-dashed border-zinc-800 rounded-[2.5rem] flex items-center justify-center text-zinc-800 relative group overflow-hidden cursor-pointer hover:border-green-500 transition-all shadow-inner">
                  {formData.imageUrl ? <img src={formData.imageUrl} className="w-full h-full object-cover" /> : <div className="flex flex-col items-center gap-2"><Camera size={32} /><span className="text-[8px] font-black uppercase tracking-widest">Foto Real</span></div>}
                </div>
                <input type="file" ref={itemImageInputRef} accept="image/*" capture="environment" className="hidden" 
                  onChange={(e) => {
                    const file = e.target.files?.[0];
