                      const reader = new FileReader();
                      reader.onloadend = () => setFormData({...formData, imageUrl: reader.result as string});
                      reader.readAsDataURL(file);
                    }
                  }}
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-600 uppercase px-1 tracking-widest">Grupo Logístico</label>
                  <select required className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none focus:border-green-500/50" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as ItemCategory})}>
