              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-600 uppercase px-1 tracking-widest">Part Number (PN)</label>
                  <input required type="text" placeholder="Código BRP" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
