                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-600 uppercase px-1 tracking-widest">Valor Unitário R$</label>
                  <input required type="number" step="0.01" placeholder="0.00" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-green-500 font-black text-xs" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                </div>
              </div>

              <div className="bg-black border border-zinc-800 p-6 rounded-[2.5rem] space-y-4">
                <p className="text-[9px] font-black uppercase text-zinc-600 italic tracking-widest text-center">Vínculo de Segurança QR</p>
                <div className="flex gap-3">
                  <div className="flex-1 bg-zinc-900/50 border border-zinc-800 p-4 rounded-xl text-[10px] font-black text-green-500 truncate italic">{formData.linkedQRCode || "AGUARDANDO LEITURA..."}</div>
                  <button type="button" onClick={() => { setScanMode('bind'); setIsScanning(true); }} className="bg-white text-black px-6 py-4 rounded-2xl font-black text-[10px] uppercase shadow-xl active:scale-95 transition-all">Scan QR</button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-600 uppercase px-1 tracking-widest">Saldo Inicial</label>
                  <input required type="number" placeholder="0" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-zinc-600 uppercase px-1 tracking-widest">Estoque Mínimo</label>
                  <input required type="number" placeholder="Alertar em..." className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs" value={formData.minQuantity || ''} onChange={e => setFormData({...formData, minQuantity: parseInt(e.target.value) || 0})} />
                </div>
              </div>
              <button type="submit" className="w-full py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2.5rem] shadow-glow active:scale-95 transition-all tracking-widest">Efetivar Cadastro</button>
            </form>
          </div>
        </div>
      )}

      {/* MOVIMENTAÇÃO MODAL */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-center justify-center p-6 backdrop-blur-3xl animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3.5rem] w-full max-w-sm shadow-2xl overflow-hidden">
            <div className={`p-8 flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
               <div className="p-4 bg-black/10 rounded-2xl">{movementModal.type === TransactionType.IN ? <Plus size={32} strokeWidth={4} /> : <LogOut size={32} className="rotate-180" strokeWidth={4} />}</div>
               <h3 className="text-2xl font-black uppercase italic tracking-tighter leading-none">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Baixa'}</h3>
            </div>
            <div className="p-10 space-y-8">
               <div className="space-y-2 text-center">
                 <p className="text-[10px] font-black uppercase text-zinc-600 tracking-[0.4em]">Quantidade Unidades</p>
                 <input type="number" className="w-full bg-transparent p-4 text-7xl font-black text-center text-green-500 outline-none placeholder-zinc-800" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
               </div>
               {movementModal.type === TransactionType.OUT && (
                 <div className="space-y-5 animate-in slide-in-from-bottom-2">
                   <div className="grid grid-cols-2 gap-3">
                     <button type="button" onClick={() => setDestination(MovementDestination.OS)} className={`py-4 rounded-2xl flex flex-col items-center gap-1 border transition-all ${destination === MovementDestination.OS ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-black border-zinc-800 text-zinc-600'}`}><Wrench size={18} /><span className="text-[9px] font-black uppercase">Ordem Serviço</span></button>
                     <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-4 rounded-2xl flex flex-col items-center gap-1 border transition-all ${destination === MovementDestination.INTERNAL ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-black border-zinc-800 text-zinc-600'}`}><Factory size={18} /><span className="text-[9px] font-black uppercase">Consumo Interno</span></button>
                   </div>
                   {destination === MovementDestination.OS && <input type="text" placeholder="NÚMERO DA OS" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none focus:border-green-500/50" value={osNumber} onChange={e => setOsNumber(e.target.value)} />}
                   <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                     <option value="">PROFISSIONAL DESTINO...</option>
                     {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                   </select>
                 </div>
               )}
               <div className="flex gap-3">
                 <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-5 bg-zinc-800 text-zinc-600 font-black rounded-[1.8rem] uppercase text-[10px]">Voltar</button>
                 <button onClick={() => processMovement()} className={`flex-[2] py-5 font-black rounded-[1.8rem] uppercase text-[10px] shadow-glow active:scale-95 transition-all ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* DETALHES MODAL */}
      {selectedItemDetails && (
        <div className="fixed inset-0 bg-black z-[250] flex flex-col animate-in fade-in slide-in-from-bottom-10 duration-500">
           <header className="p-6 flex items-center justify-between border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-3xl sticky top-0 z-10">
             <div className="flex items-center gap-3">
               <div className="px-3 py-1 bg-green-500/10 border border-green-500/20 rounded-lg"><span className="text-[10px] font-black text-green-500 uppercase tracking-widest italic">{selectedItemDetails.category}</span></div>
               <div className="px-3 py-1 bg-white/5 border border-white/10 rounded-lg"><span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">{selectedItemDetails.boxNumber}</span></div>
             </div>
             <button onClick={() => setSelectedItemDetails(null)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500 hover:text-white transition-all"><X size={24} /></button>
           </header>

           <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-32">
             <div className="w-full aspect-square bg-zinc-900 rounded-[3.5rem] border-2 border-zinc-800 overflow-hidden shadow-2xl relative max-w-2xl mx-auto">
               {selectedItemDetails.imageUrl ? <img src={selectedItemDetails.imageUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-zinc-800"><Package size={120} /></div>}
               <div className="absolute bottom-10 left-10 bg-black/90 backdrop-blur-xl px-5 py-3 rounded-2xl border border-zinc-800 shadow-2xl text-[10px] font-black uppercase tracking-[0.2em] text-green-500">PN: {selectedItemDetails.partNumber}</div>
             </div>

             <div className="max-w-2xl mx-auto w-full space-y-6">
               <div className="space-y-2 text-center sm:text-left">
                 <h1 className="text-4xl font-black uppercase italic leading-[0.9] text-white tracking-tighter">{selectedItemDetails.name}</h1>
                 <p className="text-[9px] font-black text-zinc-600 uppercase mt-2 tracking-[0.4em] italic">Localização Física: {selectedItemDetails.boxNumber.toUpperCase()}</p>
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] text-center sm:text-left">
                   <p className="text-[9px] font-black text-zinc-500 uppercase mb-3 tracking-widest">Saldo Físico</p>
                   <p className={`text-4xl font-black ${selectedItemDetails.quantity <= selectedItemDetails.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>{selectedItemDetails.quantity} <span className="text-xs uppercase opacity-30">un</span></p>
                 </div>
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] text-center sm:text-left">
                   <p className="text-[9px] font-black text-zinc-500 uppercase mb-3 tracking-widest">Patrimonial</p>
                   <p className="text-2xl font-black text-white leading-none">R$ {selectedItemDetails.value.toFixed(2)}<br/><span className="text-[10px] opacity-40 uppercase">Unitário</span></p>
                 </div>
               </div>

               <div className="bg-zinc-900/50 border border-zinc-800 p-8 rounded-[3rem] space-y-4">
                 <h4 className="text-[10px] font-black uppercase text-green-500 tracking-widest italic flex items-center gap-3"><Info size={16} /> Nota Técnica HPS</h4>
                 <p className="text-xs text-zinc-400 font-bold leading-relaxed italic border-l-2 border-zinc-800 pl-4 py-1">{selectedItemDetails.observations || "Sem notas adicionais."}</p>
               </div>
             </div>
           </div>

           {isAdmin && (
             <div className="p-8 bg-black border-t border-zinc-800 grid grid-cols-2 gap-5 sticky bottom-0 z-20">
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.IN })} className="py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2rem] shadow-glow active:scale-95 transition-all">Entrada</button>
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.OUT })} className="py-6 bg-white text-black font-black uppercase text-xs rounded-[2rem] shadow-xl active:scale-95 transition-all">Baixa</button>
             </div>
           )}
        </div>
      )}

      {isScanning && (
        <QRScanner onScan={handleQRScan} onClose={() => { setIsScanning(false); setTargetItemForValidation(null); }} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, Upload, 
  Camera, Globe, ShieldCheck, ChevronRight, Smartphone, Eye, 
  Info, Wrench, Factory, Filter, Key, Trash2, Layers, Tag, Box,
  BarChart3, Download, Sparkles, CheckCircle2, ChevronDown
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { GoogleGenAI } from "@google/genai";

const CATEGORIES = Object.values(ItemCategory);

type ActiveTab = 'dashboard' | 'history' | 'reports' | 'profile' | 'labels';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => (
  <div className="flex flex-col items-center select-none">
    <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
      <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
    </div>
  </div>
);

const App: React.FC = () => {
  // --- DATABASE ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [reportSubTab, setReportSubTab] = useState<'inventory' | 'analytics'>('inventory');
  const [searchTerm, setSearchTerm] = useState('');
  const [stockCategoryFilter, setStockCategoryFilter] = useState<ItemCategory | 'TODOS'>('TODOS');
  const [stockBoxFilter, setStockBoxFilter] = useState<string>('TODAS');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [targetItemForValidation, setTargetItemForValidation] = useState<InventoryItem | null>(null);
  const [selectedItemDetails, setSelectedItemDetails] = useState<InventoryItem | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- FORM STATES ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  const itemImageInputRef = useRef<HTMLInputElement>(null);

  // --- PERSISTENCE ---
  useEffect(() => {
    const savedUsers = localStorage.getItem('hps_v6_users');
    const savedItems = localStorage.getItem('hps_v6_items');
    const savedHistory = localStorage.getItem('hps_v6_history');
    const savedSession = localStorage.getItem('hps_v6_session');

    if (savedUsers) setUsers(JSON.parse(savedUsers));
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedSession) setCurrentUser(JSON.parse(savedSession));
  }, []);

  useEffect(() => {
    if (users.length > 0) localStorage.setItem('hps_v6_users', JSON.stringify(users));
    localStorage.setItem('hps_v6_items', JSON.stringify(items));
    localStorage.setItem('hps_v6_history', JSON.stringify(history));
    if (currentUser) localStorage.setItem('hps_v6_session', JSON.stringify(currentUser));
    else localStorage.removeItem('hps_v6_session');
  }, [users, items, history, currentUser]);

  // --- GEMINI INTEGRATION (BRP EPC SIMULATION) ---
  const fetchBRPData = async () => {
    if (!formData.partNumber) { alert("Insira o Part Number primeiro."); return; }
    setIsAiLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise o Part Number BRP "${formData.partNumber}" e sugira o nome comercial da peça e a categoria mais provável entre: ${CATEGORIES.join(', ')}. Responda APENAS em formato JSON: {"name": "...", "category": "..."}`,
      });
      const data = JSON.parse(response.text.trim());
      setFormData(prev => ({ 
        ...prev, 
        name: data.name || prev.name, 
        category: (CATEGORIES.includes(data.category as any) ? data.category : ItemCategory.INSUMOS) as ItemCategory
      }));
    } catch (e) {
      console.error("AI Fetch Error", e);
    } finally {
      setIsAiLoading(false);
    }
  };

  // --- ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) setCurrentUser(user);
    else alert("Credenciais incorretas.");
  };

  const handleLogout = () => { if (window.confirm("Sair do sistema?")) setCurrentUser(null); };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    setItems([newItem, ...items]);
    setHistory([{ id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name, type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'ESTOQUE' }, ...history]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item || (movementModal.type === TransactionType.OUT && item.quantity < movementQty)) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setTargetItemForValidation(item); setScanMode('validate'); setIsScanning(true); return;
    }

    setItems(items.map(i => i.id === item.id ? { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) } : i));
    setHistory([{ id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name, type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', destination, osNumber: destination === MovementDestination.OS ? osNumber : undefined }, ...history]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
  };

  // --- ANALYTICS CALCULATIONS ---
  const technicianStats = useMemo(() => {
    const stats: Record<string, number> = {};
    history.filter(h => h.type === TransactionType.OUT).forEach(h => {
      stats[h.recipientName] = (stats[h.recipientName] || 0) + h.quantity;
    });
    return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [history]);

  const filteredItems = useMemo(() => {
    return items.filter(i => 
      (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())) &&
      (stockCategoryFilter === 'TODOS' || i.category === stockCategoryFilter) &&
      (stockBoxFilter === 'TODAS' || i.boxNumber === stockBoxFilter)
    );
  }, [items, searchTerm, stockCategoryFilter, stockBoxFilter]);

  const availableBoxes = useMemo(() => Array.from(new Set(items.map(i => i.boxNumber))).sort(), [items]);

  const isAdmin = currentUser?.role === UserRole.STOCKIST;

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in duration-700">
          <div className="text-center"><HPSLogo size="lg" /></div>
          <div className="bg-zinc-900/50 border border-zinc-800 p-8 rounded-[2.5rem] backdrop-blur-xl">
            <form onSubmit={handleLogin} className="space-y-4">
              <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500/50" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
              <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500/50" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-all">Acessar Terminal</button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-zinc-950 text-zinc-100 font-sans pb-24 lg:pb-0 lg:pl-24 selection:bg-green-500 selection:text-black">

      {/* Impressão de Etiquetas (Só visível no Print) */}
      <div className="print-only label-sheet">
        {items.map(item => (
          <div key={item.id} className="label-card">
            <div className="font-bold text-sm uppercase">{item.name}</div>
            <div className="text-[10px] font-mono">PN: {item.partNumber}</div>
            <div className="text-[10px] uppercase">{item.category} | {item.boxNumber}</div>
