                      <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mt-1">{item.category} • {item.boxNumber}</p>
                      <div className="flex items-center gap-3 mt-3">
                        <div className={`px-2 py-0.5 rounded-lg text-[8px] font-black ${item.quantity <= item.minQuantity ? 'bg-amber-500 text-black' : 'bg-green-500/10 text-green-500 border border-green-500/20'}`}>{item.quantity} UN</div>
