                    <Sparkles className={`text-green-500 ${isAiLoading ? 'animate-spin' : ''}`} size={16} />
                 </div>
                 <div className="flex gap-3">
                    <input type="text" placeholder="PART NUMBER (PN)" className="flex-1 bg-zinc-900 border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none focus:border-green-500" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
