            </form>
          </div>
        </div>
      )}

      {/* DETALHES MODAL */}
      {selectedItemDetails && (
        <div className="fixed inset-0 bg-black z-[250] flex flex-col animate-in fade-in slide-in-from-bottom-10 duration-500">
           <header className="p-6 flex items-center justify-between border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-3xl sticky top-0 z-10">
             <div className="flex flex-col">
                <span className="text-[10px] font-black text-green-500 uppercase tracking-widest italic">{selectedItemDetails.category}</span>
                <span className="text-[12px] font-black text-zinc-400 uppercase tracking-tighter">{selectedItemDetails.boxNumber}</span>
             </div>
             <button onClick={() => setSelectedItemDetails(null)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500"><X size={24} /></button>
           </header>

           <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-32">
             <div className="w-full aspect-square bg-zinc-900 rounded-[4rem] border-2 border-zinc-800 overflow-hidden shadow-2xl relative max-w-2xl mx-auto">
               {selectedItemDetails.imageUrl ? <img src={selectedItemDetails.imageUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-zinc-800"><Package size={120} /></div>}
               <div className="absolute bottom-10 left-10 bg-black/90 px-5 py-3 rounded-2xl border border-zinc-800 text-[10px] font-black text-green-500">PN: {selectedItemDetails.partNumber}</div>
             </div>

             <div className="max-w-2xl mx-auto w-full space-y-6">
               <h1 className="text-4xl font-black uppercase italic leading-tight text-white tracking-tighter">{selectedItemDetails.name}</h1>
               <div className="grid grid-cols-2 gap-4">
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-3 tracking-widest">Saldo Atual</p>
                   <p className={`text-4xl font-black ${selectedItemDetails.quantity <= selectedItemDetails.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>{selectedItemDetails.quantity} <span className="text-xs uppercase opacity-30">un</span></p>
                 </div>
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-3 tracking-widest">Patrimônio</p>
                   <p className="text-2xl font-black text-white">R$ {selectedItemDetails.value.toFixed(2)}</p>
                 </div>
               </div>
             </div>
           </div>

           {isAdmin && (
             <div className="p-8 bg-black border-t border-zinc-800 grid grid-cols-2 gap-5 sticky bottom-0 z-20">
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.IN })} className="py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Entrada</button>
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.OUT })} className="py-6 bg-white text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Baixa</button>
             </div>
           )}
        </div>
      )}

      {/* MOVEMENT MODAL */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3.5rem] w-full max-w-sm shadow-2xl">
             <div className={`p-8 rounded-t-[3.5rem] flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
                <div className="p-4 bg-black/10 rounded-2xl">{movementModal.type === TransactionType.IN ? <Plus size={32} /> : <LogOut size={32} className="rotate-180" />}</div>
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Baixa'}</h3>
             </div>
             <div className="p-10 space-y-8">
                <input type="number" className="w-full bg-transparent p-4 text-7xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
                {movementModal.type === TransactionType.OUT && (
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setDestination(MovementDestination.OS)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.OS ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>Ordem Serviço</button>
                      <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.INTERNAL ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>Interno</button>
                    </div>
                    {destination === MovementDestination.OS && <input type="text" placeholder="NÚMERO DA OS" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={osNumber} onChange={e => setOsNumber(e.target.value)} />}
                    <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                      <option value="">TÉCNICO DESTINO...</option>
                      {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                    </select>
                  </div>
                )}
                <button onClick={() => processMovement()} className={`w-full py-5 font-black rounded-3xl uppercase text-[10px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar Movimentação</button>
             </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, Upload, 
  Camera, Globe, ShieldCheck, ChevronRight, Smartphone, Eye, 
  Info, Wrench, Factory, Filter, Key, Trash2, Layers, Tag, Box,
  BarChart3, Download, Sparkles, CheckCircle2, ChevronDown
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
// Importado Type conforme as diretrizes do SDK
import { GoogleGenAI, Type } from "@google/genai";

const CATEGORIES = Object.values(ItemCategory);

type ActiveTab = 'dashboard' | 'history' | 'reports' | 'profile' | 'labels';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => (
  <div className="flex flex-col items-center select-none">
    <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
      <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
    </div>
  </div>
);

const App: React.FC = () => {
  // --- DATABASE ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [reportSubTab, setReportSubTab] = useState<'inventory' | 'analytics'>('inventory');
  const [searchTerm, setSearchTerm] = useState('');
  const [stockCategoryFilter, setStockCategoryFilter] = useState<ItemCategory | 'TODOS'>('TODOS');
  const [stockBoxFilter, setStockBoxFilter] = useState<string>('TODAS');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [targetItemForValidation, setTargetItemForValidation] = useState<InventoryItem | null>(null);
  const [selectedItemDetails, setSelectedItemDetails] = useState<InventoryItem | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- FORM STATES ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  const itemImageInputRef = useRef<HTMLInputElement>(null);

  // --- PERSISTENCE ---
  useEffect(() => {
    const savedUsers = localStorage.getItem('hps_v6_users');
    const savedItems = localStorage.getItem('hps_v6_items');
    const savedHistory = localStorage.getItem('hps_v6_history');
    const savedSession = localStorage.getItem('hps_v6_session');

    if (savedUsers) setUsers(JSON.parse(savedUsers));
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedSession) setCurrentUser(JSON.parse(savedSession));
  }, []);

  useEffect(() => {
    if (users.length > 0) localStorage.setItem('hps_v6_users', JSON.stringify(users));
    localStorage.setItem('hps_v6_items', JSON.stringify(items));
    localStorage.setItem('hps_v6_history', JSON.stringify(history));
    if (currentUser) localStorage.setItem('hps_v6_session', JSON.stringify(currentUser));
    else localStorage.removeItem('hps_v6_session');
  }, [users, items, history, currentUser]);

  // --- GEMINI INTEGRATION (BRP EPC SIMULATION) ---
  const fetchBRPData = async () => {
    if (!formData.partNumber) { alert("Insira o Part Number primeiro."); return; }
    setIsAiLoading(true);
    try {
      // Criação da instância GoogleGenAI seguindo as diretrizes
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise o Part Number BRP "${formData.partNumber}" e identifique o componente técnico.`,
        config: {
          // Utilização de responseMimeType e responseSchema recomendada para respostas JSON
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              name: { 
                type: Type.STRING, 
                description: "Nome comercial da peça em português (ex: Vira-brequim, Junta do Cabeçote)" 
              },
              category: { 
                type: Type.STRING, 
                description: "Categoria mais adequada entre as disponíveis",
                enum: CATEGORIES
              }
            },
            required: ["name", "category"]
          }
        }
      });

      // Acessando a propriedade .text conforme as diretrizes para extrair a resposta
      const jsonStr = response.text || '{}';
      const data = JSON.parse(jsonStr.trim());

      setFormData(prev => ({ 
        ...prev, 
        name: data.name || prev.name, 
        category: (CATEGORIES.includes(data.category as any) ? data.category : ItemCategory.INSUMOS) as ItemCategory
      }));
    } catch (e) {
      console.error("AI Fetch Error", e);
    } finally {
      setIsAiLoading(false);
    }
  };

  // --- ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) setCurrentUser(user);
    else alert("Credenciais incorretas.");
  };

  const handleLogout = () => { if (window.confirm("Sair do sistema?")) setCurrentUser(null); };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    setItems([newItem, ...items]);
    setHistory([{ id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name, type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'ESTOQUE' }, ...history]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item || (movementModal.type === TransactionType.OUT && item.quantity < movementQty)) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setTargetItemForValidation(item); setScanMode('validate'); setIsScanning(true); return;
    }

    setItems(items.map(i => i.id === item.id ? { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) } : i));
    setHistory([{ id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name, type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', destination, osNumber: destination === MovementDestination.OS ? osNumber : undefined }, ...history]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
  };

  // Fix: Adicionado handleQRScan para resolver o erro "Cannot find name 'handleQRScan'" no render do scanner
  const handleQRScan = (data: string) => {
    setIsScanning(false);

    if (scanMode === 'search') {
      // Busca peça pelo Part Number ou QR Code vinculado
      const foundItem = items.find(i => i.partNumber === data || i.linkedQRCode === data);
      if (foundItem) {
        setSelectedItemDetails(foundItem);
      } else {
        alert("Peça não encontrada no banco HPS.");
      }
    } else if (scanMode === 'validate') {
      // Validação de segurança obrigatória para itens marcados com QR
      if (targetItemForValidation?.linkedQRCode === data || targetItemForValidation?.partNumber === data) {
        processMovement(true); // Continua movimentação após sucesso na leitura física
      } else {
        alert("QR Code inválido: A peça física lida não corresponde à baixa solicitada.");
      }
      setTargetItemForValidation(null);
    }
  };

  // --- ANALYTICS CALCULATIONS ---
  const technicianStats = useMemo(() => {
    const stats: Record<string, number> = {};
    history.filter(h => h.type === TransactionType.OUT).forEach(h => {
      stats[h.recipientName] = (stats[h.recipientName] || 0) + h.quantity;
    });
    return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [history]);

  const filteredItems = useMemo(() => {
    return items.filter(i => 
      (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())) &&
      (stockCategoryFilter === 'TODOS' || i.category === stockCategoryFilter) &&
      (stockBoxFilter === 'TODAS' || i.boxNumber === stockBoxFilter)
    );
  }, [items, searchTerm, stockCategoryFilter, stockBoxFilter]);

  const availableBoxes = useMemo(() => Array.from(new Set(items.map(i => i.boxNumber))).sort(), [items]);

  const isAdmin = currentUser?.role === UserRole.STOCKIST;

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in duration-700">
          <div className="text-center"><HPSLogo size="lg" /></div>
          <div className="bg-zinc-900/50 border border-zinc-800 p-8 rounded-[2.5rem] backdrop-blur-xl">
            <form onSubmit={handleLogin} className="space-y-4">
              <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500/50" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
              <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500/50" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-all">Acessar Terminal</button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-zinc-950 text-zinc-100 font-sans pb-24 lg:pb-0 lg:pl-24 selection:bg-green-500 selection:text-black">

      {/* Impressão de Etiquetas (Só visível no Print) */}
      <div className="print-only label-sheet">
        {items.map(item => (
          <div key={item.id} className="label-card">
            <div className="font-bold text-sm uppercase">{item.name}</div>
            <div className="text-[10px] font-mono">PN: {item.partNumber}</div>
            <div className="text-[10px] uppercase">{item.category} | {item.boxNumber}</div>
            <div className="mt-2 flex justify-center opacity-50"><QrCode size={40} /></div>
          </div>
        ))}
      </div>

      {/* Sidebar Desktop */}
      <aside className="print-hidden hidden lg:flex flex-col items-center py-10 gap-8 fixed left-0 top-0 bottom-0 w-24 bg-black border-r border-zinc-800 z-50">
        <HPSLogo size="sm" />
        <div className="flex flex-col gap-4 mt-8">
          {[
            { id: 'dashboard', icon: TrendingUp },
            { id: 'history', icon: History },
            { id: 'reports', icon: BarChart3 },
            { id: 'profile', icon: UserCircle }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`p-4 rounded-2xl transition-all ${activeTab === tab.id ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-600 hover:text-white hover:bg-zinc-900'}`}>
              <tab.icon size={24} />
            </button>
          ))}
        </div>
        <button onClick={handleLogout} className="mt-auto p-4 text-zinc-700 hover:text-red-500 transition-colors"><LogOut size={24} /></button>
      </aside>

      {/* Main Content Area */}
      <main className="print-hidden flex-1 max-w-7xl mx-auto w-full p-4 sm:p-10 pt-20 lg:pt-10">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <header className="flex justify-between items-center px-2 lg:hidden">
               <HPSLogo size="sm" />
               <div className="flex gap-2">
                 <button onClick={() => setIsAddingItem(true)} className="p-3 bg-green-500 text-black rounded-xl"><Plus size={20} /></button>
                 <button onClick={handleLogout} className="p-3 bg-zinc-900 rounded-xl text-red-500"><LogOut size={20} /></button>
               </div>
            </header>

            {/* Dashboard Alerts */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem] relative group overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-20 transition-opacity"><Package size={80} /></div>
                <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Itens Ativos</p>
                <p className="text-4xl font-black">{items.length}</p>
              </div>
              <div className={`border p-6 rounded-[2rem] transition-all ${items.some(i => i.quantity <= i.minQuantity) ? 'bg-amber-500/10 border-amber-500/30' : 'bg-zinc-900/50 border-zinc-800'}`}>
                <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Reposição Crítica</p>
                <div className="flex items-center gap-3">
                  <p className="text-4xl font-black text-amber-500">{items.filter(i => i.quantity <= i.minQuantity).length}</p>
                  {items.some(i => i.quantity <= i.minQuantity) && <AlertTriangle className="text-amber-500 animate-pulse" />}
                </div>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem] hidden md:block">
                <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Movimentos/Mês</p>
                <p className="text-4xl font-black text-green-500">{history.length}</p>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem] hidden md:block">
                <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Valor Patrimonial</p>
                <p className="text-xl font-black text-white">R$ {items.reduce((acc, i) => acc + (i.value * i.quantity), 0).toLocaleString('pt-BR')}</p>
              </div>
            </div>

            {/* Search & Stock Grid */}
            <div className="space-y-6">
              <div className="relative group max-w-3xl">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-zinc-700 group-focus-within:text-green-500 transition-colors" size={22} />
                <input type="text" placeholder="Nome, Part Number ou Localização..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-zinc-900 border border-zinc-800 pl-16 pr-6 py-5 rounded-[2.5rem] font-bold text-sm outline-none focus:border-green-500/30 transition-all shadow-xl" />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                {filteredItems.slice(0, 12).map(item => (
                  <div key={item.id} onClick={() => setSelectedItemDetails(item)} className="bg-zinc-900/40 border border-zinc-800/50 p-6 rounded-[3rem] flex items-center gap-5 group hover:bg-zinc-900/60 hover:border-zinc-700 transition-all cursor-pointer">
                    <div className="w-16 h-16 bg-black rounded-3xl border border-zinc-800 overflow-hidden flex items-center justify-center shrink-0">
                      {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={28} className="text-zinc-800" />}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <h4 className="font-black text-sm uppercase italic truncate text-zinc-100">{item.name}</h4>
                        {item.quantity <= item.minQuantity && <AlertTriangle size={14} className="text-amber-500" />}
                      </div>
                      <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mt-1">{item.category} • {item.boxNumber}</p>
                      <div className="flex items-center gap-3 mt-3">
                        <div className={`px-2 py-0.5 rounded-lg text-[8px] font-black ${item.quantity <= item.minQuantity ? 'bg-amber-500 text-black' : 'bg-green-500/10 text-green-500 border border-green-500/20'}`}>{item.quantity} UN</div>
                        <span className="text-[9px] text-zinc-700 font-bold uppercase">PN: {item.partNumber}</span>
                      </div>
                    </div>
                    <ChevronRight size={20} className="text-zinc-800 group-hover:text-green-500 transition-all" />
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-5">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-6">
               <div className="flex gap-4">
