      {/* DETALHES MODAL */}
      {selectedItemDetails && (
        <div className="fixed inset-0 bg-black z-[250] flex flex-col animate-in fade-in slide-in-from-bottom-10 duration-500">
           <header className="p-6 flex items-center justify-between border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-3xl sticky top-0 z-10">
             <div className="flex flex-col">
                <span className="text-[10px] font-black text-green-500 uppercase tracking-widest italic">{selectedItemDetails.category}</span>
                <span className="text-[12px] font-black text-zinc-400 uppercase tracking-tighter">{selectedItemDetails.boxNumber}</span>
             </div>
             <button onClick={() => setSelectedItemDetails(null)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500"><X size={24} /></button>
           </header>

           <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-32">
             <div className="w-full aspect-square bg-zinc-900 rounded-[4rem] border-2 border-zinc-800 overflow-hidden shadow-2xl relative max-w-2xl mx-auto">
               {selectedItemDetails.imageUrl ? <img src={selectedItemDetails.imageUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-zinc-800"><Package size={120} /></div>}
               <div className="absolute bottom-10 left-10 bg-black/90 px-5 py-3 rounded-2xl border border-zinc-800 text-[10px] font-black text-green-500">PN: {selectedItemDetails.partNumber}</div>
             </div>

             <div className="max-w-2xl mx-auto w-full space-y-6">
               <h1 className="text-4xl font-black uppercase italic leading-tight text-white tracking-tighter">{selectedItemDetails.name}</h1>
               <div className="grid grid-cols-2 gap-4">
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-3 tracking-widest">Saldo Atual</p>
                   <p className={`text-4xl font-black ${selectedItemDetails.quantity <= selectedItemDetails.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>{selectedItemDetails.quantity} <span className="text-xs uppercase opacity-30">un</span></p>
                 </div>
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-3 tracking-widest">Patrimônio</p>
                   <p className="text-2xl font-black text-white">R$ {selectedItemDetails.value.toFixed(2)}</p>
                 </div>
               </div>
             </div>
           </div>

           {isAdmin && (
             <div className="p-8 bg-black border-t border-zinc-800 grid grid-cols-2 gap-5 sticky bottom-0 z-20">
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.IN })} className="py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Entrada</button>
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.OUT })} className="py-6 bg-white text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Baixa</button>
             </div>
           )}
        </div>
      )}

      {/* MOVEMENT MODAL */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3.5rem] w-full max-w-sm shadow-2xl">
             <div className={`p-8 rounded-t-[3.5rem] flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
                <div className="p-4 bg-black/10 rounded-2xl">{movementModal.type === TransactionType.IN ? <Plus size={32} /> : <LogOut size={32} className="rotate-180" />}</div>
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Baixa'}</h3>
             </div>
             <div className="p-10 space-y-8">
                <input type="number" className="w-full bg-transparent p-4 text-7xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
                {movementModal.type === TransactionType.OUT && (
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setDestination(MovementDestination.OS)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.OS ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>Ordem Serviço</button>
                      <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.INTERNAL ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>Interno</button>
                    </div>
                    {destination === MovementDestination.OS && <input type="text" placeholder="NÚMERO DA OS" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={osNumber} onChange={e => setOsNumber(e.target.value)} />}
                    <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                      <option value="">TÉCNICO DESTINO...</option>
                      {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                    </select>
                  </div>
                )}
                <button onClick={() => processMovement()} className={`w-full py-5 font-black rounded-3xl uppercase text-[10px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar Movimentação</button>
             </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, Upload, 
  Camera, Globe, ShieldCheck, ChevronRight, Smartphone, Eye, 
  Info, Wrench, Factory, Filter, Key, Trash2, Layers, Tag, Box,
  BarChart3, Download, Sparkles, CheckCircle2, ChevronDown
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { GoogleGenAI, Type } from "@google/genai";

const CATEGORIES = Object.values(ItemCategory);

type ActiveTab = 'dashboard' | 'history' | 'reports' | 'profile' | 'labels';
type AuthView = 'login' | 'signup';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => (
  <div className="flex flex-col items-center select-none">
    <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
      <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
    </div>
  </div>
);

const App: React.FC = () => {
  // --- DATABASE ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [reportSubTab, setReportSubTab] = useState<'inventory' | 'analytics'>('inventory');
  const [searchTerm, setSearchTerm] = useState('');
  const [stockCategoryFilter, setStockCategoryFilter] = useState<ItemCategory | 'TODOS'>('TODOS');
  const [stockBoxFilter, setStockBoxFilter] = useState<string>('TODAS');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [targetItemForValidation, setTargetItemForValidation] = useState<InventoryItem | null>(null);
  const [selectedItemDetails, setSelectedItemDetails] = useState<InventoryItem | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- FORM STATES ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  const itemImageInputRef = useRef<HTMLInputElement>(null);

  // --- PERSISTENCE (v6_final) ---
  useEffect(() => {
    const savedUsers = localStorage.getItem('hps_v6_final_users');
    const savedItems = localStorage.getItem('hps_v6_final_items');
    const savedHistory = localStorage.getItem('hps_v6_final_history');
    const savedSession = localStorage.getItem('hps_v6_final_session');

    if (savedUsers) setUsers(JSON.parse(savedUsers));
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedSession) setCurrentUser(JSON.parse(savedSession));
  }, []);

  useEffect(() => {
    if (users.length > 0) localStorage.setItem('hps_v6_final_users', JSON.stringify(users));
    localStorage.setItem('hps_v6_final_items', JSON.stringify(items));
    localStorage.setItem('hps_v6_final_history', JSON.stringify(history));
    if (currentUser) localStorage.setItem('hps_v6_final_session', JSON.stringify(currentUser));
    else localStorage.removeItem('hps_v6_final_session');
  }, [users, items, history, currentUser]);

  // --- GEMINI INTEGRATION ---
  const fetchBRPData = async () => {
    if (!formData.partNumber) { alert("Insira o Part Number primeiro."); return; }
    setIsAiLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise o Part Number BRP "${formData.partNumber}" para veículos Can-Am/Sea-Doo e identifique o componente técnico.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING, enum: CATEGORIES }
            },
            required: ["name", "category"]
          }
        }
      });

      const jsonStr = response.text || '{}';
      const data = JSON.parse(jsonStr.trim());

      setFormData(prev => ({ 
        ...prev, 
        name: data.name || prev.name, 
        category: data.category as ItemCategory || prev.category
      }));
    } catch (e) {
      console.error("AI Error", e);
      alert("Não foi possível identificar o Part Number automaticamente.");
    } finally {
      setIsAiLoading(false);
    }
  };

  // --- ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
      setLoginForm({ username: '', password: '' });
    } else {
      alert("Usuário ou senha inválidos.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === signupForm.username.toLowerCase())) {
      alert("Nome de usuário já existe."); return;
    }
    const newUser = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers([...users, newUser]);
    alert("Usuário registrado com sucesso!");
    setAuthView('login');
  };

  const handleLogout = () => { if (window.confirm("Deseja encerrar a sessão?")) setCurrentUser(null); };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    setItems([newItem, ...items]);
    setHistory([{ 
      id: Math.random().toString(36).substr(2, 9), 
      itemId: newItem.id, 
      itemName: newItem.name, 
      userId: currentUser!.id, 
      userName: currentUser!.name, 
      type: TransactionType.IN, 
      quantity: newItem.quantity, 
      date: new Date().toISOString(), 
      recipientName: 'ESTOQUE' 
    }, ...history]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setTargetItemForValidation(item); setScanMode('validate'); setIsScanning(true); return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Saldo insuficiente."); return;
    }

    setItems(items.map(i => i.id === item.id ? { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) } : i));
    setHistory([{ id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name, type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', destination, osNumber: destination === MovementDestination.OS ? osNumber : undefined }, ...history]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setOsNumber('');
  };

  const handleQRScan = (data: string) => {
    setIsScanning(false);
    if (scanMode === 'bind') { setFormData({...formData, linkedQRCode: data}); return; }
    if (scanMode === 'validate') {
      if (targetItemForValidation?.linkedQRCode === data || targetItemForValidation?.partNumber === data) processMovement(true);
      else alert("Erro: QR Code físico não corresponde ao item selecionado.");
      setTargetItemForValidation(null);
      return;
    }
    const foundItem = items.find(i => i.partNumber === data || i.linkedQRCode === data);
    if (foundItem) setSelectedItemDetails(foundItem);
    else alert("Peça não encontrada.");
  };

  // --- ANALYTICS & FILTERS ---
  const technicianStats = useMemo(() => {
    const stats: Record<string, number> = {};
    history.filter(h => h.type === TransactionType.OUT).forEach(h => {
      stats[h.recipientName] = (stats[h.recipientName] || 0) + h.quantity;
    });
    return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [history]);

  const filteredItems = useMemo(() => {
    return items.filter(i => 
      (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())) &&
      (stockCategoryFilter === 'TODOS' || i.category === stockCategoryFilter) &&
      (stockBoxFilter === 'TODAS' || i.boxNumber === stockBoxFilter)
    );
  }, [items, searchTerm, stockCategoryFilter, stockBoxFilter]);

  const availableBoxes = useMemo(() => Array.from(new Set(items.map(i => i.boxNumber))).sort(), [items]);

  const isAdmin = currentUser?.role === UserRole.STOCKIST;

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in duration-700">
          <div className="text-center"><HPSLogo size="lg" /></div>
          <div className="bg-zinc-900/50 border border-zinc-800 p-8 rounded-[2.5rem] shadow-2xl backdrop-blur-xl">
            {authView === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500/50" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500/50" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-all">Entrar</button>
                <button type="button" onClick={() => setAuthView('signup')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Primeiro acesso? Cadastre-se</button>
              </form>
            ) : (
              <form onSubmit={handleSignup} className="space-y-4">
                <input required type="text" placeholder="NOME COMPLETO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} />
                <input required type="text" placeholder="LOGIN" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} />
                <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as UserRole})}>
                   <option value={UserRole.MECHANIC}>Mecânico</option>
                   <option value={UserRole.STOCKIST}>Estoquista (Gestor)</option>
                </select>
                <button type="submit" className="w-full py-5 bg-white text-black font-black uppercase text-xs rounded-2xl shadow-xl active:scale-95 transition-all">Criar Conta</button>
                <button type="button" onClick={() => setAuthView('login')} className="w-full text-[9px] font-black uppercase text-zinc-600 mt-2">Já tem conta? Login</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-zinc-950 text-zinc-100 font-sans pb-24 lg:pb-0 lg:pl-24 selection:bg-green-500 selection:text-black overscroll-none">

      {/* Impressão de Etiquetas */}
      <div className="print-only label-sheet">
        {items.map(item => (
          <div key={item.id} className="label-card">
            <div className="font-bold text-sm uppercase">{item.name}</div>
            <div className="text-[10px] font-mono">PN: {item.partNumber}</div>
            <div className="text-[10px] uppercase">{item.category} | {item.boxNumber}</div>
            <div className="mt-2 flex justify-center opacity-50"><QrCode size={40} /></div>
          </div>
        ))}
      </div>

      {/* Sidebar Desktop */}
      <aside className="print-hidden hidden lg:flex flex-col items-center py-10 gap-8 fixed left-0 top-0 bottom-0 w-24 bg-black border-r border-zinc-800 z-50">
        <HPSLogo size="sm" />
        <div className="flex flex-col gap-4 mt-8">
          {[
            { id: 'dashboard', icon: TrendingUp },
            { id: 'history', icon: History },
            { id: 'reports', icon: BarChart3 },
            { id: 'profile', icon: UserCircle }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`p-4 rounded-2xl transition-all ${activeTab === tab.id ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-600 hover:text-white hover:bg-zinc-900'}`}>
              <tab.icon size={24} />
            </button>
          ))}
        </div>
        <button onClick={handleLogout} className="mt-auto p-4 text-zinc-700 hover:text-red-500 transition-colors"><LogOut size={24} /></button>
      </aside>

      {/* Content */}
      <main className="print-hidden flex-1 max-w-7xl mx-auto w-full p-4 sm:p-10 pt-20 lg:pt-10">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <header className="flex justify-between items-center lg:hidden">
               <HPSLogo size="sm" />
               <div className="flex gap-2">
                 {isAdmin && <button onClick={() => setIsAddingItem(true)} className="p-3 bg-green-500 text-black rounded-xl"><Plus size={20} /></button>}
                 <button onClick={handleLogout} className="p-3 bg-zinc-900 rounded-xl text-red-500"><LogOut size={20} /></button>
               </div>
            </header>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem]">
                <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Itens em Estoque</p>
                <p className="text-4xl font-black">{items.length}</p>
              </div>
              <div className={`p-6 rounded-[2rem] border ${items.some(i => i.quantity <= i.minQuantity) ? 'bg-amber-500/10 border-amber-500/30 text-amber-500' : 'bg-zinc-900/50 border-zinc-800 text-white'}`}>
                <p className="text-[9px] opacity-60 font-black uppercase tracking-widest mb-1">Alertas Reposição</p>
                <p className="text-4xl font-black">{items.filter(i => i.quantity <= i.minQuantity).length}</p>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem] hidden md:block">
                <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Logs Operacionais</p>
                <p className="text-4xl font-black text-green-500">{history.length}</p>
              </div>
              <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2rem] hidden md:block">
                <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Valor Patrimonial</p>
                <p className="text-xl font-black text-white">R$ {items.reduce((acc, i) => acc + (i.value * i.quantity), 0).toLocaleString('pt-BR')}</p>
              </div>
            </div>

            <div className="space-y-6">
              <div className="relative group max-w-3xl">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-zinc-700 group-focus-within:text-green-500 transition-colors" size={22} />
                <input type="text" placeholder="Pesquisar componente ou caixa..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-zinc-900 border border-zinc-800 pl-16 pr-6 py-5 rounded-[2.5rem] font-bold text-sm outline-none focus:border-green-500/30 transition-all shadow-xl" />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                {filteredItems.slice(0, 15).map(item => (
                  <div key={item.id} onClick={() => setSelectedItemDetails(item)} className="bg-zinc-900/40 border border-zinc-800/50 p-6 rounded-[3rem] flex items-center gap-5 group hover:bg-zinc-900/60 transition-all cursor-pointer">
                    <div className="w-16 h-16 bg-black rounded-3xl border border-zinc-800 flex items-center justify-center shrink-0">
                      {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={28} className="text-zinc-800" />}
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="font-black text-sm uppercase italic truncate text-zinc-100">{item.name}</h4>
                      <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mt-1">{item.category} • {item.boxNumber}</p>
                      <div className="flex items-center gap-3 mt-3">
                        <div className={`px-2 py-0.5 rounded-lg text-[8px] font-black ${item.quantity <= item.minQuantity ? 'bg-amber-500 text-black' : 'bg-green-500/10 text-green-500'}`}>{item.quantity} UN</div>
                        <span className="text-[9px] text-zinc-700 font-bold uppercase">PN: {item.partNumber}</span>
                      </div>
                    </div>
                    <ChevronRight size={20} className="text-zinc-800 group-hover:text-green-500 transition-all" />
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-5">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-6">
               <div className="flex gap-4">
                 <button onClick={() => setReportSubTab('inventory')} className={`text-xs font-black uppercase tracking-widest pb-2 transition-all ${reportSubTab === 'inventory' ? 'text-green-500 border-b-2 border-green-500' : 'text-zinc-600'}`}>Inventário</button>
                 <button onClick={() => setReportSubTab('analytics')} className={`text-xs font-black uppercase tracking-widest pb-2 transition-all ${reportSubTab === 'analytics' ? 'text-green-500 border-b-2 border-green-500' : 'text-zinc-600'}`}>Desempenho</button>
               </div>
               <button onClick={() => window.print()} className="p-3 bg-zinc-900 rounded-xl text-white hover:bg-white hover:text-black transition-all"><Printer size={20} /></button>
            </div>

            {reportSubTab === 'inventory' ? (
              <div className="space-y-6">
                <div className="flex flex-wrap gap-2">
                   <select className="bg-zinc-900 border border-zinc-800 p-3 rounded-xl text-[10px] font-black text-green-500 uppercase outline-none" value={stockCategoryFilter} onChange={e => setStockCategoryFilter(e.target.value as any)}>
                      <option value="TODOS">GRUPOS</option>
                      {CATEGORIES.map(c => <option key={c} value={c}>{c.toUpperCase()}</option>)}
                   </select>
                   <select className="bg-zinc-900 border border-zinc-800 p-3 rounded-xl text-[10px] font-black text-white uppercase outline-none" value={stockBoxFilter} onChange={e => setStockBoxFilter(e.target.value)}>
                      <option value="TODAS">CAIXAS</option>
                      {availableBoxes.map(b => <option key={b} value={b}>{b.toUpperCase()}</option>)}
                   </select>
                </div>
                <div className="bg-zinc-900/50 border border-zinc-800 rounded-[2.5rem] overflow-hidden">
                  <table className="w-full text-left text-[11px]">
                    <thead className="bg-black/50 text-zinc-500 font-black uppercase border-b border-zinc-800">
                      <tr><th className="p-6">Componente</th><th className="p-6">Caixa</th><th className="p-6 text-center">Saldo</th><th className="p-6 text-right">Valor</th></tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800">
                      {filteredItems.map(item => (
                        <tr key={item.id} className="hover:bg-white/5 transition-colors group">
                          <td className="p-6"><p className="font-black uppercase text-zinc-100 italic">{item.name}</p><p className="text-[9px] text-zinc-600">PN: {item.partNumber}</p></td>
                          <td className="p-6"><span className="text-[10px] font-black text-green-500">{item.boxNumber}</span></td>
                          <td className="p-6 text-center"><span className={`font-black text-lg ${item.quantity <= item.minQuantity ? 'text-amber-500' : 'text-zinc-300'}`}>{item.quantity}</span></td>
                          <td className="p-6 text-right font-bold text-zinc-400">R$ {(item.value * item.quantity).toFixed(2)}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-zinc-900/50 border border-zinc-800 p-8 rounded-[3rem] space-y-6">
                   <h4 className="text-xs font-black uppercase tracking-widest text-green-500">Ranking Técnicos</h4>
                   <div className="space-y-4">
                     {technicianStats.map(([name, qty]) => (
                       <div key={name} className="space-y-1">
                         <div className="flex justify-between text-[10px] font-black uppercase"><span>{name}</span><span className="text-green-500">{qty} un</span></div>
                         <div className="h-1.5 bg-black rounded-full overflow-hidden"><div className="h-full bg-green-500 transition-all duration-1000" style={{ width: `${(qty / (technicianStats[0][1] || 1)) * 100}%` }}></div></div>
                       </div>
                     ))}
                   </div>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && <TransactionHistory transactions={history} />}

        {activeTab === 'profile' && (
          <div className="max-w-md mx-auto space-y-8 pt-10">
            <div className="bg-zinc-900 border border-zinc-800 p-12 rounded-[4rem] text-center shadow-2xl">
               <div className="w-24 h-24 bg-black border-4 border-zinc-800 rounded-full mx-auto flex items-center justify-center text-zinc-700 shadow-glow mb-6">
                 <UserCircle size={50} />
               </div>
               <h2 className="text-3xl font-black uppercase italic text-white tracking-tighter">{currentUser.name}</h2>
               <p className="text-[10px] text-green-500 font-black uppercase tracking-[0.5em] mt-2 italic">{isAdmin ? 'Master Stockist' : 'Field Technician'}</p>
               <button onClick={handleLogout} className="w-full mt-10 py-5 bg-red-500/10 border border-red-500/20 text-red-500 font-black uppercase text-xs rounded-[2rem] hover:bg-red-500 hover:text-white transition-all">Encerrar Sessão</button>
            </div>
          </div>
        )}
      </main>

      {/* Nav Mobile */}
      <nav className="print-hidden lg:hidden fixed bottom-0 left-0 right-0 bg-black border-t border-zinc-800 px-6 py-4 flex justify-around items-center z-50 backdrop-blur-3xl">
        {[
          { id: 'dashboard', icon: TrendingUp },
          { id: 'reports', icon: BarChart3 },
          { id: 'history', icon: History },
          { id: 'profile', icon: UserCircle }
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeTab === tab.id ? 'text-green-500 scale-110' : 'text-zinc-700'}`}>
            <tab.icon size={22} />
          </button>
        ))}
        <button onClick={() => { setScanMode('search'); setIsScanning(true); }} className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center -mt-16 border-4 border-zinc-950 shadow-glow active:scale-90 transition-all"><QrCode size={28} className="text-black" strokeWidth={3} /></button>
      </nav>

      {/* MODAL ADICIONAR ITEM */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-end justify-center backdrop-blur-xl overflow-y-auto pt-20">
          <div className="bg-zinc-900 border border-zinc-800 rounded-t-[4rem] w-full max-w-xl animate-in slide-in-from-bottom-20 duration-500 pb-10">
            <div className="p-8 flex justify-between items-center border-b border-zinc-800">
               <h3 className="text-xl font-black uppercase italic tracking-widest text-green-500">Novo Registro</h3>
               <button onClick={() => setIsAddingItem(false)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500"><X size={24} /></button>
            </div>
            <form onSubmit={handleAddItem} className="p-8 space-y-6">

              <div className="bg-black border border-zinc-800 p-6 rounded-[2.5rem] space-y-5">
                 <div className="flex justify-between items-center px-1">
                    <p className="text-[9px] font-black uppercase text-zinc-600 italic">Preenchimento IA (Part Number)</p>
                    <Sparkles className={`text-green-500 ${isAiLoading ? 'animate-spin' : ''}`} size={16} />
                 </div>
                 <div className="flex gap-3">
                    <input type="text" placeholder="PART NUMBER" className="flex-1 bg-zinc-900 border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none focus:border-green-500" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                    <button type="button" onClick={fetchBRPData} className={`bg-green-500 text-black px-6 py-5 rounded-2xl font-black text-[10px] uppercase active:scale-95 transition-all ${isAiLoading ? 'opacity-50' : ''}`}>
                       {isAiLoading ? '...' : 'Puxar'}
                    </button>
                 </div>
              </div>

              <div className="space-y-4">
                 <input required type="text" placeholder="DESCRIÇÃO COMERCIAL" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                 <div className="grid grid-cols-2 gap-4">
                   <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})}>
                     {CATEGORIES.map(c => <option key={c} value={c}>{c.toUpperCase()}</option>)}
                   </select>
                   <input required type="text" placeholder="CAIXA/GAVETA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase" value={formData.boxNumber} onChange={e => setFormData({...formData, boxNumber: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <input required type="number" step="0.01" placeholder="VALOR R$" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-green-500 font-black text-xs" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                    <input required type="number" placeholder="SALDO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                 </div>
              </div>

              <button type="submit" className="w-full py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2.5rem] shadow-glow active:scale-95 transition-all">Finalizar Cadastro</button>
            </form>
          </div>
        </div>
      )}

      {/* DETALHES MODAL */}
      {selectedItemDetails && (
        <div className="fixed inset-0 bg-black z-[250] flex flex-col animate-in fade-in slide-in-from-bottom-10 duration-500">
           <header className="p-6 flex items-center justify-between border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-3xl sticky top-0 z-10">
             <div className="flex flex-col">
                <span className="text-[10px] font-black text-green-500 uppercase tracking-widest">{selectedItemDetails.category}</span>
                <span className="text-[12px] font-black text-zinc-400 uppercase">{selectedItemDetails.boxNumber}</span>
             </div>
             <button onClick={() => setSelectedItemDetails(null)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500"><X size={24} /></button>
           </header>

           <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-32">
             <div className="w-full aspect-square bg-zinc-900 rounded-[4rem] border-2 border-zinc-800 overflow-hidden shadow-2xl relative max-w-2xl mx-auto flex items-center justify-center">
               {selectedItemDetails.imageUrl ? <img src={selectedItemDetails.imageUrl} className="w-full h-full object-cover" /> : <Package size={120} className="text-zinc-800" />}
               <div className="absolute bottom-10 left-10 bg-black/90 px-5 py-3 rounded-2xl border border-zinc-800 text-[10px] font-black text-green-500">PN: {selectedItemDetails.partNumber}</div>
             </div>

             <div className="max-w-2xl mx-auto w-full space-y-6">
               <h1 className="text-4xl font-black uppercase italic leading-tight text-white tracking-tighter">{selectedItemDetails.name}</h1>
               <div className="grid grid-cols-2 gap-4">
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-3">Saldo</p>
                   <p className={`text-4xl font-black ${selectedItemDetails.quantity <= selectedItemDetails.minQuantity ? 'text-amber-500' : 'text-green-500'}`}>{selectedItemDetails.quantity} <span className="text-xs uppercase opacity-30">un</span></p>
                 </div>
                 <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-3">Valor</p>
                   <p className="text-2xl font-black text-white">R$ {selectedItemDetails.value.toFixed(2)}</p>
                 </div>
               </div>
             </div>
           </div>

           {isAdmin && (
             <div className="p-8 bg-black border-t border-zinc-800 grid grid-cols-2 gap-5 sticky bottom-0 z-20">
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.IN })} className="py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Entrada</button>
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItemDetails.id, type: TransactionType.OUT })} className="py-6 bg-white text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Baixa</button>
             </div>
           )}
        </div>
      )}

      {/* MOVEMENT MODAL */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3.5rem] w-full max-w-sm shadow-2xl">
             <div className={`p-8 rounded-t-[3.5rem] flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
                <div className="p-4 bg-black/10 rounded-2xl">{movementModal.type === TransactionType.IN ? <Plus size={32} /> : <LogOut size={32} className="rotate-180" />}</div>
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Baixa'}</h3>
             </div>
             <div className="p-10 space-y-8 text-center">
                <p className="text-[10px] text-zinc-500 font-black uppercase tracking-widest">Quantidade</p>
                <input type="number" className="w-full bg-transparent text-7xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
                {movementModal.type === TransactionType.OUT && (
                  <div className="space-y-4 text-left">
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setDestination(MovementDestination.OS)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.OS ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>OS</button>
                      <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.INTERNAL ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>Interno</button>
                    </div>
                    {destination === MovementDestination.OS && <input type="text" placeholder="Nº DA OS" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={osNumber} onChange={e => setOsNumber(e.target.value)} />}
                    <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                      <option value="">TÉCNICO</option>
                      {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                    </select>
                  </div>
                )}
                <button onClick={() => processMovement()} className={`w-full py-5 font-black rounded-3xl uppercase text-[10px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar</button>
             </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, FileText, Printer, X, 
  Camera, Globe, ShieldCheck, ChevronRight, Smartphone, Eye, 
  Info, Wrench, Factory, Layers, BarChart3, Download, Sparkles, 
  Settings, Users, Trash2, ExternalLink
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { GoogleGenAI, Type } from "@google/genai";

const CATEGORIES = Object.values(ItemCategory);
const DB_PREFIX = "HPS_PRO_V7_";

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'analytics' | 'users' | 'labels' | 'profile';
type AuthView = 'login' | 'signup';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => (
  <div className="flex flex-col items-center select-none">
    <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
      <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
    </div>
  </div>
);

const App: React.FC = () => {
  // --- DATABASE STATE ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- FORM STATES ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  // --- PERSISTENCE LOGIC ---
  useEffect(() => {
    const load = (key: string) => {
      const val = localStorage.getItem(DB_PREFIX + key);
      return val ? JSON.parse(val) : null;
    };
    setUsers(load('users') || []);
    setItems(load('items') || []);
    setHistory(load('history') || []);
    setCurrentUser(load('session'));
  }, []);

  useEffect(() => {
    const save = (key: string, data: any) => localStorage.setItem(DB_PREFIX + key, JSON.stringify(data));
    save('users', users);
    save('items', items);
    save('history', history);
    save('session', currentUser);
  }, [users, items, history, currentUser]);

  // --- AUTH ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
      setActiveTab('dashboard');
    } else {
      alert("Credenciais incorretas ou usuário não encontrado.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === signupForm.username.toLowerCase())) {
      alert("Este login já está em uso."); return;
    }
    const newUser: User = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers([...users, newUser]);
    alert("Conta criada com sucesso! Agora realize o login.");
    setAuthView('login');
  };

  const handleLogout = () => { if (window.confirm("Deseja sair?")) setCurrentUser(null); };

  // --- AI ACTIONS ---
  const fetchBRPData = async () => {
    if (!formData.partNumber) return;
    setIsAiLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Identifique a peça BRP Part Number: ${formData.partNumber}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING, enum: CATEGORIES }
            },
            required: ["name", "category"]
          }
        }
      });
      const data = JSON.parse(response.text || '{}');
      setFormData(prev => ({ ...prev, name: data.name || prev.name, category: data.category as any || prev.category }));
    } catch (e) {
      console.error(e);
    } finally { setIsAiLoading(false); }
  };

  // --- ITEM ACTIONS ---
  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    setItems([newItem, ...items]);
    setHistory([{ id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name, type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'ESTOQUE' }, ...history]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setIsScanning(true); setScanMode('validate'); return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Quantidade indisponível em estoque."); return;
    }

    setItems(items.map(i => i.id === item.id ? { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) } : i));
    setHistory([{ id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name, type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', destination, osNumber: destination === MovementDestination.OS ? osNumber : undefined }, ...history]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setOsNumber('');
  };

  const handleQRScan = (data: string) => {
    setIsScanning(false);
    if (scanMode === 'bind') { setFormData({...formData, linkedQRCode: data}); return; }
    const found = items.find(i => i.linkedQRCode === data || i.partNumber === data);
    if (found) setSelectedItem(found);
    else alert("Peça não localizada.");
  };

  // --- UI HELPERS ---
  const isAdmin = currentUser?.role === UserRole.STOCKIST;
  const filteredItems = items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase()));

  // --- RENDER LOGIN ---
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6 sm:p-12">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center"><HPSLogo size="lg" /></div>
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem] shadow-2xl">
            {authView === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow">Acessar Sistema</button>
                <button type="button" onClick={() => setAuthView('signup')} className="w-full text-[10px] text-zinc-600 font-bold uppercase mt-4">Criar nova conta</button>
              </form>
            ) : (
              <form onSubmit={handleSignup} className="space-y-4">
                <input required type="text" placeholder="NOME" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} />
                <input required type="text" placeholder="LOGIN" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} />
                <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as any})}>
                  <option value={UserRole.MECHANIC}>Mecânico</option>
                  <option value={UserRole.STOCKIST}>Estoquista</option>
                </select>
                <button type="submit" className="w-full py-5 bg-white text-black font-black uppercase text-xs rounded-2xl">Confirmar Cadastro</button>
                <button type="button" onClick={() => setAuthView('login')} className="w-full text-[10px] text-zinc-600 font-bold uppercase mt-4">Voltar para login</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100 flex flex-col lg:flex-row pb-24 lg:pb-0">

      {/* Sidebar Desktop */}
      <nav className="print-hidden hidden lg:flex flex-col w-24 bg-black border-r border-zinc-800 py-10 items-center gap-8 fixed left-0 top-0 bottom-0 z-50">
        <HPSLogo size="sm" />
        <div className="flex flex-col gap-4 mt-8 flex-1">
          {[
            { id: 'dashboard', icon: TrendingUp },
            { id: 'inventory', icon: Layers },
            { id: 'history', icon: History },
            { id: 'analytics', icon: BarChart3 },
            { id: 'labels', icon: QrCode },
            { id: 'users', icon: Users, adminOnly: true },
          ].map(tab => (!tab.adminOnly || isAdmin) && (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`p-4 rounded-2xl transition-all ${activeTab === tab.id ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-600 hover:text-white'}`}>
              <tab.icon size={24} />
            </button>
          ))}
        </div>
        <button onClick={handleLogout} className="p-4 text-zinc-700 hover:text-red-500"><LogOut size={24} /></button>
      </nav>

      {/* Main Content */}
      <main className="print-hidden flex-1 lg:pl-24 p-4 sm:p-10 max-w-7xl mx-auto w-full">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
              <div>
                <h1 className="text-3xl font-black uppercase italic tracking-tighter">Painel de Controle</h1>
                <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest mt-1">Bem-vindo, {currentUser.name}</p>
              </div>
              <a href="https://epc.brp.com/#" target="_blank" className="flex items-center gap-2 bg-zinc-900 border border-zinc-800 px-6 py-3 rounded-2xl text-[10px] font-black uppercase text-green-500 hover:bg-green-500 hover:text-black transition-all">
                <ExternalLink size={14} /> Acessar Catálogo BRP
              </a>
            </div>

            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2.5rem]">
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Itens Ativos</p>
                <p className="text-4xl font-black">{items.length}</p>
              </div>
              <div className={`bg-zinc-900 border p-6 rounded-[2.5rem] ${items.some(i => i.quantity <= i.minQuantity) ? 'border-amber-500/50' : 'border-zinc-800'}`}>
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Reposição Necessária</p>
                <p className="text-4xl font-black text-amber-500">{items.filter(i => i.quantity <= i.minQuantity).length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2.5rem] hidden sm:block">
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Mecânicos em Campo</p>
                <p className="text-4xl font-black text-green-500">{users.filter(u => u.role === UserRole.MECHANIC).length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2.5rem] hidden sm:block">
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Logs/Mês</p>
                <p className="text-4xl font-black text-white">{history.length}</p>
              </div>
            </div>

            <div className="relative group max-w-2xl">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-zinc-700" size={20} />
              <input type="text" placeholder="Buscar por PN, Nome ou Caixa..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-zinc-900 border border-zinc-800 pl-14 pr-6 py-5 rounded-[2rem] font-bold text-xs outline-none" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredItems.slice(0, 12).map(item => (
                <div key={item.id} onClick={() => setSelectedItem(item)} className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2.5rem] flex items-center gap-5 cursor-pointer hover:bg-zinc-900 transition-all group overflow-hidden">
                  <div className="w-14 h-14 bg-black rounded-2xl flex items-center justify-center shrink-0 border border-zinc-800">
                    {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={24} className="text-zinc-800" />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className="font-black text-xs uppercase truncate text-zinc-100">{item.name}</h4>
                    <p className="text-[9px] text-zinc-600 font-black uppercase tracking-widest mt-1">{item.category} • {item.boxNumber}</p>
                    <div className="flex items-center gap-2 mt-3">
                      <span className={`px-2 py-0.5 rounded text-[8px] font-black ${item.quantity <= item.minQuantity ? 'bg-amber-500 text-black' : 'bg-green-500/10 text-green-500'}`}>{item.quantity} UN</span>
                    </div>
                  </div>
                  <ChevronRight size={18} className="text-zinc-800 group-hover:text-green-500" />
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'inventory' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-5">
            <div className="flex justify-between items-center border-b border-zinc-800 pb-6">
              <h2 className="text-2xl font-black uppercase italic italic tracking-tighter">Estoque Geral</h2>
              {isAdmin && <button onClick={() => setIsAddingItem(true)} className="flex items-center gap-2 bg-green-500 text-black px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-glow"><Plus size={16} /> Nova Peça</button>}
            </div>
            <div className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] overflow-hidden">
               <div className="overflow-x-auto">
                 <table className="w-full text-left text-[11px]">
                   <thead className="bg-black text-zinc-500 font-black uppercase">
                     <tr><th className="p-6">Componente</th><th className="p-6">Caixa</th><th className="p-6 text-center">Saldo</th><th className="p-6 text-right">Valor UN</th></tr>
                   </thead>
                   <tbody className="divide-y divide-zinc-800">
                     {filteredItems.map(item => (
                       <tr key={item.id} className="hover:bg-white/5 cursor-pointer transition-colors" onClick={() => setSelectedItem(item)}>
                         <td className="p-6"><p className="font-black text-white uppercase">{item.name}</p><p className="text-[9px] text-zinc-600">PN: {item.partNumber}</p></td>
                         <td className="p-6 text-green-500 font-black">{item.boxNumber.toUpperCase()}</td>
                         <td className="p-6 text-center font-black">{item.quantity}</td>
                         <td className="p-6 text-right font-black">R$ {item.value.toFixed(2)}</td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'analytics' && (
          <div className="space-y-10 animate-in fade-in duration-500">
            <h2 className="text-2xl font-black uppercase italic tracking-tighter">Análise de Performance</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem] space-y-6">
                <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-green-500">Ranking de Uso por Técnico</h4>
                <div className="space-y-5">
                  {users.filter(u => u.role === UserRole.MECHANIC).map(u => {
                    const qty = history.filter(h => h.recipientName === u.name && h.type === TransactionType.OUT).reduce((acc, h) => acc + h.quantity, 0);
                    const max = Math.max(...users.map(u => history.filter(h => h.recipientName === u.name).length), 1);
                    return (
                      <div key={u.id} className="space-y-1">
                        <div className="flex justify-between text-[10px] font-black uppercase"><span>{u.name}</span><span>{qty} un</span></div>
                        <div className="h-2 bg-black rounded-full overflow-hidden border border-zinc-800"><div className="h-full bg-green-500" style={{ width: `${(qty / max) * 100}%` }}></div></div>
                      </div>
                    );
                  })}
                </div>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem] space-y-6">
                <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-green-500">Consumo por Categoria</h4>
                <div className="space-y-4">
                  {CATEGORIES.map(cat => {
                    const qty = history.filter(h => h.type === TransactionType.OUT && items.find(i => i.id === h.itemId)?.category === cat).reduce((acc, h) => acc + h.quantity, 0);
                    if (qty === 0) return null;
                    return (
                      <div key={cat} className="flex justify-between items-center p-4 bg-black rounded-2xl border border-zinc-800">
                        <span className="text-[10px] font-black uppercase">{cat}</span>
                        <span className="text-lg font-black text-white">{qty} un</span>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'labels' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-center">
               <h2 className="text-2xl font-black uppercase italic tracking-tighter">Emissão de Etiquetas</h2>
               <button onClick={() => window.print()} className="bg-white text-black px-8 py-4 rounded-2xl font-black uppercase text-[10px] flex items-center gap-2"><Printer size={16} /> Imprimir em PDF</button>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
               {items.map(item => (
                 <div key={item.id} className="bg-white p-4 rounded-xl text-black flex flex-col items-center gap-2 border border-zinc-200">
                    <p className="text-[9px] font-black uppercase text-center leading-none">{item.name}</p>
                    <div className="w-20 h-20 bg-zinc-100 rounded-lg flex items-center justify-center border border-zinc-200"><QrCode size={40} /></div>
                    <p className="text-[8px] font-bold">PN: {item.partNumber}</p>
                    <p className="text-[7px] font-black uppercase bg-zinc-900 text-white px-2 py-0.5 rounded-full">{item.boxNumber}</p>
                 </div>
               ))}
            </div>
          </div>
        )}

        {activeTab === 'users' && isAdmin && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <h2 className="text-2xl font-black uppercase italic tracking-tighter">Gerenciamento de Equipe</h2>
            <div className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] overflow-hidden">
               <div className="overflow-x-auto">
                 <table className="w-full text-left text-[11px]">
                   <thead className="bg-black text-zinc-500 font-black uppercase">
                     <tr><th className="p-6">Usuário</th><th className="p-6">Acesso</th><th className="p-6 text-right">Ações</th></tr>
                   </thead>
                   <tbody className="divide-y divide-zinc-800">
                     {users.map(u => (
                       <tr key={u.id} className="hover:bg-white/5 transition-colors">
                         <td className="p-6">
                            <p className="font-black text-white uppercase">{u.name}</p>
                            <p className="text-[9px] text-zinc-600">Login: {u.username}</p>
                         </td>
                         <td className="p-6">
                            <span className={`px-2 py-1 rounded-md text-[9px] font-black uppercase ${u.role === UserRole.STOCKIST ? 'bg-green-500 text-black' : 'bg-zinc-800 text-zinc-400'}`}>
                              {u.role === UserRole.STOCKIST ? 'Estoquista' : 'Mecânico'}
                            </span>
                         </td>
                         <td className="p-6 text-right">
                            <button onClick={() => { if(window.confirm("Remover usuário?")) setUsers(users.filter(usr => usr.id !== u.id)); }} className="p-2 text-zinc-700 hover:text-red-500 transition-all"><Trash2 size={16} /></button>
                         </td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'history' && <TransactionHistory transactions={history} />}

      </main>

      {/* Nav Mobile */}
      <nav className="print-hidden lg:hidden fixed bottom-0 left-0 right-0 bg-black border-t border-zinc-800 p-4 flex justify-around items-center z-50 backdrop-blur-3xl">
        {[
          { id: 'dashboard', icon: TrendingUp },
          { id: 'inventory', icon: Layers },
          { id: 'history', icon: History },
          { id: 'profile', icon: UserCircle },
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeTab === tab.id ? 'text-green-500 scale-110' : 'text-zinc-700'}`}>
            <tab.icon size={22} />
          </button>
        ))}
        <button onClick={() => { setScanMode('search'); setIsScanning(true); }} className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center -mt-16 border-4 border-zinc-950 shadow-glow"><QrCode size={26} className="text-black" strokeWidth={3} /></button>
      </nav>

      {/* MODAL ADICIONAR ITEM */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-end justify-center backdrop-blur-xl overflow-y-auto pt-20">
          <div className="bg-zinc-900 border border-zinc-800 rounded-t-[4rem] w-full max-w-xl shadow-glow animate-in slide-in-from-bottom-20 duration-500 pb-10">
            <div className="p-8 border-b border-zinc-800 flex justify-between items-center">
              <h3 className="text-xl font-black uppercase italic italic tracking-widest text-green-500">Cadastro de Peça</h3>
              <button onClick={() => setIsAddingItem(false)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500"><X size={24} /></button>
            </div>
            <form onSubmit={handleAddItem} className="p-8 space-y-6">

              <div className="bg-black border border-zinc-800 p-6 rounded-[2.5rem] space-y-4">
                 <div className="flex justify-between items-center px-1">
                    <p className="text-[9px] font-black uppercase text-zinc-600">Part Number Intelligence</p>
                    <Sparkles className={`text-green-500 ${isAiLoading ? 'animate-spin' : ''}`} size={16} />
                 </div>
                 <div className="flex gap-3">
                    <input type="text" placeholder="PART NUMBER" className="flex-1 bg-zinc-900 border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase outline-none focus:border-green-500" value={formData.partNumber} onChange={e => setFormData({...formData, partNumber: e.target.value})} />
                    <button type="button" onClick={fetchBRPData} className="bg-green-500 text-black px-6 py-5 rounded-2xl font-black text-[10px] uppercase active:scale-95 transition-all">Puxar</button>
                 </div>
              </div>

              <div className="space-y-4">
                 <input required type="text" placeholder="DESCRIÇÃO COMERCIAL" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                 <div className="grid grid-cols-2 gap-4">
                   <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})}>
                     {CATEGORIES.map(c => <option key={c} value={c}>{c.toUpperCase()}</option>)}
                   </select>
                   <input required type="text" placeholder="CAIXA/GAVETA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs uppercase" value={formData.boxNumber} onChange={e => setFormData({...formData, boxNumber: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <input required type="number" step="0.01" placeholder="VALOR R$" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-green-500 font-black text-xs" value={formData.value || ''} onChange={e => setFormData({...formData, value: parseFloat(e.target.value) || 0})} />
                    <input required type="number" placeholder="SALDO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} />
                 </div>
              </div>

              <button type="submit" className="w-full py-6 bg-green-500 text-black font-black uppercase text-xs rounded-[2.5rem] shadow-glow active:scale-95 transition-all">Efetivar no Banco HPS</button>
            </form>
          </div>
        </div>
      )}

      {/* DETALHES MODAL */}
      {selectedItem && (
        <div className="fixed inset-0 bg-black z-[250] flex flex-col animate-in fade-in slide-in-from-bottom-10 duration-500">
           <header className="p-6 flex items-center justify-between border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-3xl sticky top-0 z-10">
             <div className="flex flex-col">
                <span className="text-[10px] font-black text-green-500 uppercase tracking-widest">{selectedItem.category}</span>
                <span className="text-[12px] font-black text-zinc-400 uppercase tracking-tighter">{selectedItem.boxNumber}</span>
             </div>
             <button onClick={() => setSelectedItem(null)} className="p-3 bg-zinc-800 rounded-2xl text-zinc-500"><X size={24} /></button>
           </header>

           <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-32">
             <div className="w-full aspect-square bg-zinc-900 rounded-[3.5rem] border-2 border-zinc-800 overflow-hidden shadow-2xl relative max-w-2xl mx-auto flex items-center justify-center">
               {selectedItem.imageUrl ? <img src={selectedItem.imageUrl} className="w-full h-full object-cover" /> : <Package size={100} className="text-zinc-800" />}
               <div className="absolute bottom-8 left-8 bg-black/90 px-4 py-2 rounded-xl border border-zinc-800 text-[9px] font-black text-green-500">PN: {selectedItem.partNumber}</div>
             </div>

             <div className="max-w-2xl mx-auto w-full space-y-6">
               <h1 className="text-3xl font-black uppercase italic leading-tight text-white tracking-tighter">{selectedItem.name}</h1>
               <div className="grid grid-cols-2 gap-4">
                 <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2.5rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Saldo Atual</p>
                   <p className="text-4xl font-black text-green-500">{selectedItem.quantity} <span className="text-xs uppercase opacity-30 font-black">un</span></p>
                 </div>
                 <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2.5rem]">
                   <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Valor Unitário</p>
                   <p className="text-2xl font-black text-white">R$ {selectedItem.value.toFixed(2)}</p>
                 </div>
               </div>
               <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-[2rem] space-y-3">
                  <p className="text-[9px] font-black uppercase text-green-500 italic tracking-widest flex items-center gap-2"><Info size={14} /> Notas Técnicas</p>
                  <p className="text-xs text-zinc-400 font-medium leading-relaxed italic">{selectedItem.observations || "Nenhuma nota de serviço registrada."}</p>
               </div>
             </div>
           </div>

           {isAdmin && (
             <div className="p-8 bg-black border-t border-zinc-800 grid grid-cols-2 gap-5 sticky bottom-0 z-20">
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItem.id, type: TransactionType.IN })} className="py-5 bg-green-500 text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Dar Entrada</button>
               <button onClick={() => setMovementModal({ isOpen: true, itemId: selectedItem.id, type: TransactionType.OUT })} className="py-5 bg-white text-black font-black uppercase text-xs rounded-[2rem] active:scale-95 transition-all">Lançar Baixa</button>
             </div>
           )}
        </div>
      )}

      {/* MOVEMENT MODAL */}
      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[3.5rem] w-full max-w-sm shadow-2xl">
             <div className={`p-8 rounded-t-[3.5rem] flex items-center gap-6 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
                <div className="p-4 bg-black/10 rounded-2xl">{movementModal.type === TransactionType.IN ? <Plus size={28} strokeWidth={4} /> : <LogOut size={28} className="rotate-180" strokeWidth={4} />}</div>
                <h3 className="text-xl font-black uppercase italic tracking-tighter leading-none">{movementModal.type === TransactionType.IN ? 'Entrada' : 'Saída Insumo'}</h3>
             </div>
             <div className="p-8 space-y-6 text-center">
                <div>
                  <p className="text-[9px] text-zinc-500 font-black uppercase mb-1 tracking-widest">Quantidade de Unidades</p>
                  <input type="number" className="w-full bg-transparent text-7xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
                </div>
                {movementModal.type === TransactionType.OUT && (
                  <div className="space-y-4 text-left">
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setDestination(MovementDestination.OS)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.OS ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>Ordem Serviço</button>
                      <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-4 rounded-2xl border transition-all text-[10px] font-black uppercase ${destination === MovementDestination.INTERNAL ? 'bg-green-500 border-green-500 text-black' : 'bg-black border-zinc-800 text-zinc-600'}`}>Uso Interno</button>
                    </div>
                    {destination === MovementDestination.OS && <input type="text" placeholder="NÚMERO DA OS" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={osNumber} onChange={e => setOsNumber(e.target.value)} />}
                    <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-black text-xs outline-none" value={recipient} onChange={e => setRecipient(e.target.value)}>
                      <option value="">SELECIONE O MECÂNICO</option>
                      {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name}</option>)}
                    </select>
                  </div>
                )}
                <div className="flex gap-3">
                  <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-5 bg-zinc-800 rounded-3xl font-black uppercase text-[10px]">Voltar</button>
                  <button onClick={() => processMovement()} className={`flex-[2] py-5 font-black rounded-3xl uppercase text-[10px] shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar</button>
                </div>
             </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, Printer, X, 
  ChevronRight, Smartphone, Info, Layers, BarChart3, 
  Sparkles, Users, Trash2, ExternalLink, Filter, Calendar, CheckCircle2
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { GoogleGenAI, Type } from "@google/genai";

const CATEGORIES = Object.values(ItemCategory);
const DB_KEY = "HPS_MASTER_DB_V10";

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'analytics' | 'users' | 'labels' | 'profile' | 'mechanic_view';
type AuthView = 'login' | 'signup';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => (
  <div className="flex flex-col items-center select-none">
    <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
      <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
    </div>
  </div>
);

const App: React.FC = () => {
  // --- DATABASE STATE ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- UI STATE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [historySearchTerm, setHistorySearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- FORM STATES ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  // --- PERSISTENCE ENGINE (ESTÁVEL) ---
  useEffect(() => {
    const rawData = localStorage.getItem(DB_KEY);
    if (rawData) {
      const db = JSON.parse(rawData);
      setUsers(db.users || []);
      setItems(db.items || []);
      setHistory(db.history || []);
      if (db.session) setCurrentUser(db.session);
    }
  }, []);

  const saveDB = (newUsers: User[], newItems: InventoryItem[], newHistory: Transaction[], session: User | null) => {
    const db = { users: newUsers, items: newItems, history: newHistory, session };
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  };

  // --- AUTH ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
      saveDB(users, items, history, user);
      setActiveTab(user.role === UserRole.STOCKIST ? 'dashboard' : 'mechanic_view');
    } else {
      alert("Erro: Usuário ou senha incorretos. Verifique se a conta foi criada corretamente.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === signupForm.username.toLowerCase())) {
      alert("Este login já existe."); return;
    }
    const newUser: User = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    const updatedUsers = [...users, newUser];
    setUsers(updatedUsers);
    saveDB(updatedUsers, items, history, currentUser); // Salva imediatamente
    alert("Conta criada! Agora você pode entrar.");
    setAuthView('login');
  };

  const handleLogout = () => {
    if (window.confirm("Deseja encerrar a sessão?")) {
      setCurrentUser(null);
      saveDB(users, items, history, null);
    }
  };

  // --- USER MGMT (MASTER) ---
  const deleteUser = (id: string) => {
    if (window.confirm("Remover este acesso permanentemente?")) {
      const updated = users.filter(u => u.id !== id);
      setUsers(updated);
      saveDB(updated, items, history, currentUser);
    }
  };

  // --- AI ACTIONS ---
  const fetchBRPData = async () => {
    if (!formData.partNumber) return;
    setIsAiLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Identifique a peça BRP para o Part Number: ${formData.partNumber}. Retorne o nome comercial e categoria técnica.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING, enum: CATEGORIES }
            },
            required: ["name", "category"]
          }
        }
      });
      const data = JSON.parse(response.text || '{}');
      setFormData(prev => ({ ...prev, name: data.name || prev.name, category: data.category as any || prev.category }));
    } catch (e) { console.error(e); } finally { setIsAiLoading(false); }
  };

  // --- ITEM ACTIONS ---
  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    const updatedItems = [newItem, ...items];
    const newTx = { id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, userId: currentUser!.id, userName: currentUser!.name, type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'ESTOQUE' };
    const updatedHistory = [newTx, ...history];

    setItems(updatedItems);
    setHistory(updatedHistory);
    saveDB(users, updatedItems, updatedHistory, currentUser);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setIsScanning(true); setScanMode('validate'); return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Atenção: Saldo insuficiente em estoque."); return;
    }

    const updatedItems = items.map(i => i.id === item.id ? { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) } : i);
    const newTx = { id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, userId: currentUser!.id, userName: currentUser!.name, type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', destination, osNumber: destination === MovementDestination.OS ? osNumber : undefined };
    const updatedHistory = [newTx, ...history];

    setItems(updatedItems);
    setHistory(updatedHistory);
    saveDB(users, updatedItems, updatedHistory, currentUser);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setOsNumber('');
  };

  const handleQRScan = (data: string) => {
    setIsScanning(false);
    const found = items.find(i => i.linkedQRCode === data || i.partNumber === data);
    if (found) setSelectedItem(found);
    else alert("Part Number ou QR não cadastrado no banco.");
  };

  // --- FILTERS & ANALYTICS ---
  const isAdmin = currentUser?.role === UserRole.STOCKIST;
  const filteredItems = items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase()));

  const filteredHistory = history.filter(h => 
    h.type === TransactionType.OUT && 
    (h.itemName.toLowerCase().includes(historySearchTerm.toLowerCase()) || 
     (h.osNumber && h.osNumber.includes(historySearchTerm)))
  );

  const mechanicInsumos = history.filter(h => h.recipientName === currentUser?.name && h.type === TransactionType.OUT);

  const technicianStats = useMemo(() => {
    const stats: Record<string, number> = {};
