                      <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-6 rounded-[2rem] border transition-all text-[11px] font-black uppercase tracking-widest ${destination === MovementDestination.INTERNAL ? 'bg-green-500 border-green-500 text-black shadow-glow' : 'bg-black border-zinc-800 text-zinc-600'}`}>Uso Oficina</button>
                    </div>
                    {destination === MovementDestination.OS && <input type="text" placeholder="INSIRA O Nº DA O.S." className="w-full bg-black border border-zinc-800 p-7 rounded-[2rem] text-white font-black text-xs outline-none focus:border-green-500/50" value={osNumber} onChange={e => setOsNumber(e.target.value)} />}
                    <select className="w-full bg-black border border-zinc-800 p-7 rounded-[2rem] text-white font-black text-xs outline-none focus:border-green-500/50 uppercase italic" value={recipient} onChange={e => setRecipient(e.target.value)}>
                      <option value="">ENTREGUE PARA QUAL TÉCNICO?</option>
                      {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name.toUpperCase()}</option>)}
                    </select>
                  </div>
                )}
                <div className="flex gap-4">
                  <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-7 bg-zinc-800 rounded-[2.5rem] font-black uppercase text-[12px] italic tracking-widest">Cancelar</button>
                  <button onClick={() => processMovement()} className={`flex-[2] py-7 font-black rounded-[2.5rem] uppercase text-[12px] italic tracking-widest shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar Lançamento</button>
                </div>
             </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;

export enum UserRole {
  STOCKIST = 'STOCKIST', 
  MECHANIC = 'MECHANIC'
}

export enum ItemCategory {
  FREIOS = 'Freios',
  MOTOR = 'Motor',
  TRANSMISSAO = 'Transmissão e câmbio',
  RODAS = 'Rodas e pneus',
  INSUMOS = 'Insumos',
  ELETRICA = 'Elétrica e eletrônicos'
}

export interface User {
  id: string;
  username: string;
  password?: string;
  email?: string;
  name: string;
  role: UserRole;
  avatarUrl?: string;
}

export interface InventoryItem {
  id: string;
  name: string;
  partNumber: string;
  value: number;
  quantity: number;
  minQuantity: number;
  category: ItemCategory;
  boxNumber: string; // Identificação física (Caixa 01, Gaveta B, etc)
  entryDate: string;
  linkedQRCode?: string;
  description?: string;
  imageUrl?: string;
  observations?: string;
}

export enum TransactionType {
  IN = 'IN',
  OUT = 'OUT'
}

export enum MovementDestination {
  OS = 'OS',
  INTERNAL = 'INTERNAL'
}

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  // Added partNumber to track component reference in history logs
  partNumber?: string;
  userId: string;
  userName: string;
  type: TransactionType;
  quantity: number;
  date: string;
  recipientName: string;
  notes?: string;
  destination?: MovementDestination;
  osNumber?: string;
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, Package, Search, QrCode, LogOut, TrendingUp, History, 
  UserCircle, AlertTriangle, Printer, X, 
  ChevronRight, Smartphone, Info, Layers, BarChart3, 
  Sparkles, Users, Trash2, ExternalLink, Filter, Calendar, CheckCircle2,
  Wrench, Key, Shield
} from 'lucide-react';
import { User, UserRole, InventoryItem, Transaction, TransactionType, MovementDestination, ItemCategory } from './types';
import QRScanner from './components/QRScanner';
import TransactionHistory from './components/TransactionHistory';
import { GoogleGenAI, Type } from "@google/genai";

const CATEGORIES = Object.values(ItemCategory);
const DB_KEY = "HPS_PRO_DATA_V11";

type ActiveTab = 'dashboard' | 'inventory' | 'history' | 'analytics' | 'users' | 'labels' | 'profile' | 'mechanic_view';
type AuthView = 'login' | 'signup';

const HPSLogo: React.FC<{ size?: 'sm' | 'md' | 'lg' }> = ({ size = 'md' }) => (
  <div className="flex flex-col items-center select-none">
    <div className="text-green-500 font-black italic tracking-tighter text-2xl flex items-center gap-1">
      <Smartphone size={size === 'lg' ? 32 : 24} /> HPS <span className="text-white">CONTROL</span>
    </div>
  </div>
);

const App: React.FC = () => {
  // --- DATABASE STATE ---
  const [users, setUsers] = useState<User[]>([]);
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [history, setHistory] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [dbLoaded, setDbLoaded] = useState(false);

  // --- UI STATE ---
  const [authView, setAuthView] = useState<AuthView>('login');
  const [activeTab, setActiveTab] = useState<ActiveTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [historySearchTerm, setHistorySearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'search' | 'bind' | 'validate'>('search');
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- FORM STATES ---
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [signupForm, setSignupForm] = useState({ name: '', username: '', password: '', role: UserRole.MECHANIC });
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [formData, setFormData] = useState({
    name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, 
    category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: ''
  });

  const [movementModal, setMovementModal] = useState<{ isOpen: boolean; itemId: string | null; type: TransactionType }>({
    isOpen: false, itemId: null, type: TransactionType.OUT
  });
  const [movementQty, setMovementQty] = useState(1);
  const [recipient, setRecipient] = useState('');
  const [destination, setDestination] = useState<MovementDestination>(MovementDestination.OS);
  const [osNumber, setOsNumber] = useState('');

  // --- PERSISTENCE ENGINE ---
  // Load DB once on mount
  useEffect(() => {
    const rawData = localStorage.getItem(DB_KEY);
    if (rawData) {
      try {
        const db = JSON.parse(rawData);
        setUsers(db.users || []);
        setItems(db.items || []);
        setHistory(db.history || []);
        if (db.session) {
          setCurrentUser(db.session);
          setActiveTab(db.session.role === UserRole.STOCKIST ? 'dashboard' : 'mechanic_view');
        }
      } catch (e) {
        console.error("Erro ao carregar banco de dados", e);
      }
    }
    setDbLoaded(true);
  }, []);

  // Save DB whenever relevant state changes
  useEffect(() => {
    if (!dbLoaded) return;
    const db = { users, items, history, session: currentUser };
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  }, [users, items, history, currentUser, dbLoaded]);

  // --- AUTH ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = users.find(u => u.username.toLowerCase() === loginForm.username.toLowerCase() && u.password === loginForm.password);
    if (user) {
      setCurrentUser(user);
      setActiveTab(user.role === UserRole.STOCKIST ? 'dashboard' : 'mechanic_view');
      setLoginForm({ username: '', password: '' });
    } else {
      alert("Credenciais incorretas. Se você acabou de criar a conta, verifique o login/senha.");
    }
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === signupForm.username.toLowerCase())) {
      alert("Este nome de usuário já está sendo utilizado."); return;
    }
    const newUser: User = { id: Math.random().toString(36).substr(2, 9), ...signupForm };
    setUsers(prev => [...prev, newUser]);
    alert("Usuário cadastrado com sucesso! Use seus dados para entrar.");
    setAuthView('login');
  };

  const handleLogout = () => {
    if (window.confirm("Deseja realmente sair do sistema?")) {
      setCurrentUser(null);
      setActiveTab('dashboard');
    }
  };

  // --- USER MGMT (MASTER) ---
  const deleteUser = (id: string) => {
    if (window.confirm("Esta ação apagará o acesso deste funcionário permanentemente. Confirmar?")) {
      setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  const resetPassword = (id: string) => {
    const newPass = prompt("Digite a nova senha para este usuário:");
    if (newPass) {
      setUsers(prev => prev.map(u => u.id === id ? { ...u, password: newPass } : u));
      alert("Senha redefinida com sucesso.");
    }
  };

  // --- AI ACTIONS ---
  const fetchBRPData = async () => {
    if (!formData.partNumber) return;
    setIsAiLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Identifique a peça BRP para o Part Number: ${formData.partNumber}. Forneça nome comercial curto e categoria.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING, enum: CATEGORIES }
            },
            required: ["name", "category"]
          }
        }
      });
      const data = JSON.parse(response.text || '{}');
      setFormData(prev => ({ ...prev, name: data.name || prev.name, category: data.category as any || prev.category }));
    } catch (e) { console.error(e); } finally { setIsAiLoading(false); }
  };

  // --- ITEM ACTIONS ---
  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: InventoryItem = { id: Math.random().toString(36).substr(2, 9), ...formData, entryDate: new Date().toISOString() };
    // Fix: Added partNumber to Transaction object to match updated interface and enable search
    const newTx: Transaction = { id: Math.random().toString(36).substr(2, 9), itemId: newItem.id, itemName: newItem.name, partNumber: newItem.partNumber, userId: currentUser!.id, userName: currentUser!.name, type: TransactionType.IN, quantity: newItem.quantity, date: new Date().toISOString(), recipientName: 'ESTOQUE' };

    setItems(prev => [newItem, ...prev]);
    setHistory(prev => [newTx, ...prev]);
    setIsAddingItem(false);
    setFormData({ name: '', partNumber: '', value: 0, quantity: 0, minQuantity: 1, category: ItemCategory.INSUMOS, boxNumber: '', linkedQRCode: '', imageUrl: '', observations: '' });
  };

  const processMovement = (validated: boolean = false) => {
    if (!movementModal.itemId) return;
    const item = items.find(i => i.id === movementModal.itemId);
    if (!item) return;

    if (movementModal.type === TransactionType.OUT && item.linkedQRCode && !validated) {
      setIsScanning(true); setScanMode('validate'); return;
    }

    if (movementModal.type === TransactionType.OUT && item.quantity < movementQty) {
      alert("Erro: Saldo insuficiente."); return;
    }

    // Fix: Added partNumber to movement transaction for complete audit log
    const newTx: Transaction = { id: Math.random().toString(36).substr(2, 9), itemId: item.id, itemName: item.name, partNumber: item.partNumber, userId: currentUser!.id, userName: currentUser!.name, type: movementModal.type, quantity: movementQty, date: new Date().toISOString(), recipientName: recipient || 'HPS', destination, osNumber: destination === MovementDestination.OS ? osNumber : undefined };

    setItems(prev => prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + (movementModal.type === TransactionType.IN ? movementQty : -movementQty) } : i));
    setHistory(prev => [newTx, ...prev]);
    setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT });
    setMovementQty(1); setRecipient(''); setOsNumber('');
  };

  const handleQRScan = (data: string) => {
    setIsScanning(false);
    const found = items.find(i => i.linkedQRCode === data || i.partNumber === data);
    if (found) {
      setSelectedItem(found);
      setActiveTab('dashboard');
    } else {
      alert("Nenhum item encontrado com este código.");
    }
  };

  // --- FILTERS & ANALYTICS ---
  const isAdmin = currentUser?.role === UserRole.STOCKIST;
  const filteredItems = useMemo(() => items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()) || i.partNumber.toLowerCase().includes(searchTerm.toLowerCase())), [items, searchTerm]);

  // Fix: Line 215 error resolved as Transaction now has partNumber property
  const filteredHistory = useMemo(() => history.filter(h => 
    h.type === TransactionType.OUT && 
    (h.itemName.toLowerCase().includes(historySearchTerm.toLowerCase()) || 
     (h.partNumber?.toLowerCase().includes(historySearchTerm.toLowerCase())) ||
     (h.osNumber && h.osNumber.includes(historySearchTerm)))
  ), [history, historySearchTerm]);

  const mechanicInsumos = useMemo(() => history.filter(h => h.recipientName === currentUser?.name && h.type === TransactionType.OUT), [history, currentUser]);

  const technicianStats = useMemo(() => {
    const stats: Record<string, number> = {};
    history.filter(h => h.type === TransactionType.OUT).forEach(h => {
      stats[h.recipientName] = (stats[h.recipientName] || 0) + h.quantity;
    });
    return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [history]);

  // --- RENDER AUTH ---
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center p-6">
        <div className="w-full max-w-sm space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center"><HPSLogo size="lg" /></div>
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[3rem] shadow-2xl">
            {authView === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <input required type="text" placeholder="USUÁRIO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500" value={loginForm.username} onChange={e => setLoginForm({...loginForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none focus:border-green-500" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full py-5 bg-green-500 text-black font-black uppercase text-xs rounded-2xl shadow-glow active:scale-95 transition-transform">Acessar Terminal</button>
                <button type="button" onClick={() => setAuthView('signup')} className="w-full text-[10px] text-zinc-600 font-bold uppercase mt-6 text-center hover:text-zinc-400 transition-colors">Solicitar Acesso / Cadastro</button>
              </form>
            ) : (
              <form onSubmit={handleSignup} className="space-y-4">
                <input required type="text" placeholder="NOME COMPLETO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.name} onChange={e => setSignupForm({...signupForm, name: e.target.value})} />
                <input required type="text" placeholder="LOGIN DESEJADO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.username} onChange={e => setSignupForm({...signupForm, username: e.target.value})} />
                <input required type="password" placeholder="SENHA DE ACESSO" className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.password} onChange={e => setSignupForm({...signupForm, password: e.target.value})} />
                <select className="w-full bg-black border border-zinc-800 p-5 rounded-2xl text-white font-bold text-xs outline-none" value={signupForm.role} onChange={e => setSignupForm({...signupForm, role: e.target.value as any})}>
                  <option value={UserRole.MECHANIC}>Mecânico</option>
                  <option value={UserRole.STOCKIST}>Estoquista (Master)</option>
                </select>
                <button type="submit" className="w-full py-5 bg-white text-black font-black uppercase text-xs rounded-2xl active:scale-95 transition-transform">Finalizar Cadastro</button>
                <button type="button" onClick={() => setAuthView('login')} className="w-full text-[10px] text-zinc-600 font-bold uppercase mt-6 text-center hover:text-zinc-400 transition-colors">Voltar ao Login</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100 flex flex-col lg:flex-row pb-24 lg:pb-0">

      {/* Sidebar Desktop */}
      <nav className="print-hidden hidden lg:flex flex-col w-24 bg-black border-r border-zinc-800 py-10 items-center gap-8 fixed left-0 top-0 bottom-0 z-50">
        <HPSLogo size="sm" />
        <div className="flex flex-col gap-4 mt-8 flex-1">
          {[
            { id: 'dashboard', icon: TrendingUp },
            { id: 'inventory', icon: Layers },
            { id: 'history', icon: History },
            { id: 'analytics', icon: BarChart3 },
            { id: 'labels', icon: QrCode },
            { id: 'users', icon: Users, adminOnly: true },
            { id: 'mechanic_view', icon: Wrench, mechanicOnly: true },
            { id: 'profile', icon: UserCircle },
          ].map(tab => (
            ((!tab.adminOnly || isAdmin) && (!tab.mechanicOnly || !isAdmin)) && (
              <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`p-4 rounded-2xl transition-all ${activeTab === tab.id ? 'bg-green-500 text-black shadow-glow' : 'text-zinc-600 hover:text-white hover:bg-zinc-900'}`}>
                <tab.icon size={24} />
              </button>
            )
          ))}
        </div>
        <button onClick={handleLogout} className="p-4 text-zinc-700 hover:text-red-500 transition-colors"><LogOut size={24} /></button>
      </nav>

      {/* Main Content Area */}
      <main className="print-hidden flex-1 lg:pl-24 p-4 sm:p-10 max-w-7xl mx-auto w-full min-h-screen overflow-y-auto">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
              <div>
                <h1 className="text-4xl font-black uppercase italic tracking-tighter">Gestão de Peças</h1>
                <p className="text-[10px] text-green-500 font-black uppercase tracking-[0.2em] mt-1 italic">{isAdmin ? 'Acesso Administrativo HPS' : 'Acesso Técnico Campo'}</p>
              </div>
              <a href="https://epc.brp.com/#" target="_blank" className="flex items-center gap-3 bg-zinc-900 border border-zinc-800 px-6 py-4 rounded-2xl text-[10px] font-black uppercase text-green-500 hover:bg-green-500 hover:text-black transition-all shadow-xl">
                <ExternalLink size={16} /> EPC BRP OFICIAL
              </a>
            </div>

            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-sm">
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">SKUs Cadastrados</p>
                <p className="text-4xl font-black">{items.length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-sm">
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Saídas Mês</p>
                <p className="text-4xl font-black text-white">{history.filter(h => h.type === TransactionType.OUT).length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-sm">
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Stock Alertas</p>
                <p className="text-4xl font-black text-amber-500">{items.filter(i => i.quantity <= i.minQuantity).length}</p>
              </div>
              <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-sm">
                <p className="text-[9px] text-zinc-500 font-black uppercase mb-1">Valor Inventário</p>
                <p className="text-xl font-black text-green-500">R$ {items.reduce((acc, i) => acc + (i.value * i.quantity), 0).toLocaleString('pt-BR')}</p>
              </div>
            </div>

            <div className="space-y-6">
               <div className="relative group">
                 <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-zinc-700" size={20} />
                 <input type="text" placeholder="Filtrar estoque por Nome ou PN..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-zinc-900 border border-zinc-800 pl-16 pr-6 py-6 rounded-[2.5rem] font-bold text-xs outline-none focus:border-green-500/50 shadow-2xl" />
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                 {filteredItems.slice(0, 12).map(item => (
                   <div key={item.id} onClick={() => setSelectedItem(item)} className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-[2.5rem] flex items-center gap-5 cursor-pointer hover:bg-zinc-900 transition-all group overflow-hidden">
                     <div className="w-16 h-16 bg-black rounded-3xl flex items-center justify-center shrink-0 border border-zinc-800 group-hover:border-green-500/30">
                       {item.imageUrl ? <img src={item.imageUrl} className="w-full h-full object-cover" /> : <Package size={28} className="text-zinc-800 group-hover:text-green-500/50" />}
                     </div>
                     <div className="flex-1 min-w-0">
                       <h4 className="font-black text-xs uppercase truncate text-zinc-100 italic">{item.name}</h4>
                       <p className="text-[8px] text-zinc-600 font-black uppercase tracking-widest mt-1">PN: {item.partNumber}</p>
                       <div className="flex items-center gap-2 mt-3">
                         <span className={`px-2 py-0.5 rounded text-[8px] font-black ${item.quantity <= item.minQuantity ? 'bg-amber-500 text-black' : 'bg-green-500/10 text-green-500'}`}>{item.quantity} UN DISPONÍVEL</span>
                       </div>
                     </div>
                     <ChevronRight size={18} className="text-zinc-800 group-hover:text-green-500 transition-all" />
                   </div>
                 ))}
               </div>
            </div>
          </div>
        )}

        {activeTab === 'inventory' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-5">
            <div className="flex justify-between items-center border-b border-zinc-800 pb-8">
              <h2 className="text-3xl font-black uppercase italic tracking-tighter">Estoque Físico</h2>
              {isAdmin && <button onClick={() => setIsAddingItem(true)} className="flex items-center gap-3 bg-green-500 text-black px-8 py-4 rounded-2xl text-[10px] font-black uppercase shadow-glow active:scale-95 transition-transform"><Plus size={16} /> Cadastrar Componente</button>}
            </div>
            <div className="bg-zinc-900 border border-zinc-800 rounded-[3rem] overflow-hidden shadow-2xl">
               <div className="overflow-x-auto">
                 <table className="w-full text-left text-[11px]">
                   <thead className="bg-black text-zinc-500 font-black uppercase">
                     <tr><th className="p-8">Descrição Técnica</th><th className="p-8">Endereçamento</th><th className="p-8 text-center">Quantidade</th><th className="p-8 text-right">Patrimonial</th></tr>
                   </thead>
                   <tbody className="divide-y divide-zinc-800">
                     {filteredItems.map(item => (
                       <tr key={item.id} className="hover:bg-white/5 cursor-pointer transition-colors" onClick={() => setSelectedItem(item)}>
                         <td className="p-8"><p className="font-black text-white uppercase italic">{item.name}</p><p className="text-[9px] text-zinc-600 font-bold mt-1">REF: {item.partNumber}</p></td>
                         <td className="p-8 text-green-500 font-black uppercase italic tracking-widest">{item.boxNumber}</td>
