      {movementModal.isOpen && (
        <div className="fixed inset-0 bg-black/98 z-[300] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[4.5rem] w-full max-w-lg shadow-[0_40px_100px_rgba(0,0,0,0.8)]">
             <div className={`p-12 rounded-t-[4.5rem] flex items-center gap-8 ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>
                <div className="p-6 bg-black/10 rounded-[2rem]">{movementModal.type === TransactionType.IN ? <Plus size={40} strokeWidth={4} /> : <LogOut size={40} className="rotate-180" strokeWidth={4} />}</div>
                <h3 className="text-3xl font-black uppercase italic tracking-tighter leading-none">{movementModal.type === TransactionType.IN ? 'Entrada Estoque' : 'Baixa de Material'}</h3>
             </div>
             <div className="p-12 space-y-10 text-center">
                <div className="space-y-3">
                  <p className="text-[11px] text-zinc-500 font-black uppercase tracking-widest italic">Quantas unidades?</p>
                  <input type="number" className="w-full bg-transparent text-8xl font-black text-center text-green-500 outline-none" value={movementQty} onChange={e => setMovementQty(parseInt(e.target.value) || 1)} />
                </div>
                {movementModal.type === TransactionType.OUT && (
                  <div className="space-y-6 text-left">
                    <div className="grid grid-cols-2 gap-4">
                      <button type="button" onClick={() => setDestination(MovementDestination.OS)} className={`py-6 rounded-[2rem] border transition-all text-[11px] font-black uppercase tracking-widest ${destination === MovementDestination.OS ? 'bg-green-500 border-green-500 text-black shadow-glow' : 'bg-black border-zinc-800 text-zinc-600'}`}>Ordem Serviço</button>
                      <button type="button" onClick={() => setDestination(MovementDestination.INTERNAL)} className={`py-6 rounded-[2rem] border transition-all text-[11px] font-black uppercase tracking-widest ${destination === MovementDestination.INTERNAL ? 'bg-green-500 border-green-500 text-black shadow-glow' : 'bg-black border-zinc-800 text-zinc-600'}`}>Uso Oficina</button>
                    </div>
                    {destination === MovementDestination.OS && <input type="text" placeholder="INSIRA O Nº DA O.S." className="w-full bg-black border border-zinc-800 p-7 rounded-[2rem] text-white font-black text-xs outline-none focus:border-green-500/50" value={osNumber} onChange={e => setOsNumber(e.target.value)} />}
                    <select className="w-full bg-black border border-zinc-800 p-7 rounded-[2rem] text-white font-black text-xs outline-none focus:border-green-500/50 uppercase italic" value={recipient} onChange={e => setRecipient(e.target.value)}>
                      <option value="">ENTREGUE PARA QUAL TÉCNICO?</option>
                      {users.filter(u => u.role === UserRole.MECHANIC).map(u => <option key={u.id} value={u.name}>{u.name.toUpperCase()}</option>)}
                    </select>
                  </div>
                )}
                <div className="flex gap-4">
                  <button onClick={() => setMovementModal({ isOpen: false, itemId: null, type: TransactionType.OUT })} className="flex-1 py-7 bg-zinc-800 rounded-[2.5rem] font-black uppercase text-[12px] italic tracking-widest">Cancelar</button>
                  <button onClick={() => processMovement()} className={`flex-[2] py-7 font-black rounded-[2.5rem] uppercase text-[12px] italic tracking-widest shadow-glow ${movementModal.type === TransactionType.IN ? 'bg-green-500 text-black' : 'bg-white text-black'}`}>Confirmar Lançamento</button>
                </div>
             </div>
          </div>
        </div>
      )}

      {isScanning && <QRScanner onScan={handleQRScan} onClose={() => setIsScanning(false)} />}
    </div>
  );
};

export default App;
